-- Update Christian Guided content from the supplied DOCX manuscripts.
-- Match chapters by title so the chapter 8–10 reorder preserves IDs and learner progress.
do $$
declare
  chapter_item jsonb;
  lesson_item jsonb;
  block_item jsonb;
  course_version uuid;
  chapter_record uuid;
  lesson_record uuid;
  block_record uuid;
  block_position integer;
begin
  select cv.id into strict course_version
  from course_versions cv join courses c on c.id = cv.course_id
  where c.slug = 'uprooting-drug-abuse' and cv.guidance_path = 'christian';

  for chapter_item in select value from jsonb_array_elements('[{"number": 1, "title": "The Stage of Creation", "description": "Chapter 1 lays the biblical foundation for the Christian-guided recovery journey. It begins with God''s original design for humanity, then traces how identity, purpose, freedom, temptation, disobedience, consequences, stewardship, and heart-level pain all connect to the roots of addiction.\n\nThe goal of this chapter is to help the learner understand that addiction is not their identity, that God''s design was good, and that lasting healing requires truth, responsibility, and restoration at the heart level.", "lessons": [{"number": 1, "title": "God''s Original Design for Humanity", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Welcome to Your Journey", "message": "Before we can understand addiction, we must first understand who God created us to be. Many people see themselves through the lens of their current mistakes, addictions, failures, or past experiences. However, God''s view of humanity begins much earlier than our struggles. It begins at creation. In this lesson, we will explore God''s original design for humanity and discover that every person was created with value, purpose, and dignity. No matter where your journey has taken you, God''s original intention for your life was never destruction, bondage, or hopelessness. Today we begin by looking at how God created mankind and what that means for your recovery journey."}}, {"type": "reading", "content": {"title": "Created With Purpose", "body": "The Bible teaches that God intentionally created the heavens, the earth, all living creatures, and mankind.\n\nAccording to Genesis 1, God created the plant kingdom, animals, and finally mankind. All of creation God created good, but humanity was God''s ultimate and star creation, in His image and likeness.\n\nThis means that human life has value beyond appearance, achievements, possessions, or social status.\n\nGod''s original design included:\n\n- Relationship with God\n\n- Purpose and meaning\n\n- Responsibility and stewardship\n\n- Freedom to choose\n\n- A life free from shame\n\n- A life guided by God''s wisdom\n\nThis teaching explains that God declared His creation to be good. Humanity was not created broken, addicted, or trapped in destructive cycles. Humanity was created to live in harmony with God and creation.\n\nWhen addiction enters a person''s life, it often convinces them that they are worthless, damaged, or beyond recovery. God''s truth says otherwise.\n\nRecovery begins when we start seeing ourselves through God''s eyes rather than through our failures.\n\nYour addiction is something you have experienced. It is not your identity. God created you for more than survival. He created you with purpose.\n\nKey Scripture: Genesis 1:26-27. \"Then God said, Let Us make man in Our image, according to Our likeness...\""}}, {"type": "mentor_note", "content": {"note": "One of the first steps toward healing is recognizing that your worth does not come from your past. Your worth comes from being created by God."}}, {"type": "video", "content": {"title": "God''s Original Design for Humanity", "description": "Explain how God created humanity in His image and how addiction can distort a person''s understanding of their true identity. Encourage viewers to begin seeing themselves through God''s purpose rather than their past mistakes."}}, {"type": "pause_reflect", "content": {"question": "When you think about yourself, what words usually come to mind?", "context": "Keep reflecting as you answer: How has addiction affected the way you view yourself? What does it mean to you that God created you with purpose? Do you believe God still has a purpose for your life today? Why or why not?"}}, {"type": "journal_prompt", "content": {"prompt": "Take ten minutes today and write down three negative labels you have placed on yourself, three truths you believe God says about you, and one area of your life where you want to begin believing God''s truth instead of your past experiences."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to the truth that God created you with value and purpose today?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Pray and ask God to help you see yourself through His eyes as you replace false labels with His truth."}}, {"type": "mentor_note", "content": {"note": "You are more than your addiction. You are more than your failures. You are more than your worst day. God created you intentionally and lovingly. The same God who created the heavens and the earth knows your name, sees your struggles, and understands your journey. No matter how far you feel you have fallen, your story is not finished. Today is the beginning of remembering who God created you to be.\n\nMemory Verse: Genesis 1:27 - \"So God created man in His own image; in the image of God He created him; male and female He created them.\""}}, {"type": "quiz", "content": {"question": "Who created humanity?", "options": [{"text": "God", "is_correct": true}, {"text": "Nature", "is_correct": false}, {"text": "Chance", "is_correct": false}, {"text": "Society", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "According to Genesis, humanity was created in whose image?", "options": [{"text": "Angels", "is_correct": false}, {"text": "Nature", "is_correct": false}, {"text": "God''s Image", "is_correct": true}, {"text": "The Earth", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is your identity?", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you discovered that your identity is not rooted in addiction, shame, or failure. Your identity begins with God''s original design for your life.\n\nIn the next lesson, we will explore what it truly means to be created in the image of God."}}]}, {"number": 2, "title": "Created in the Image of God", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "More Than What You Have Done", "message": "Many people struggling with addiction eventually begin defining themselves by their mistakes. Some see themselves as addicts. Others see themselves as failures. Some believe they are too damaged for God to use. But before any addiction existed, before any failure occurred, God created humanity in His image and likeness. This truth changes everything. Today we will explore what it means to be created in God''s image and why that truth is essential for lasting recovery."}}, {"type": "reading", "content": {"title": "God''s Image Within Us", "body": "Genesis teaches that God created mankind differently from every other part of creation. Animals were created. Plants were created. The stars were created. But humanity was created in the image and likeness of God. The author explains that mankind was given unique value, purpose, responsibility, and authority by God. Humanity was designed to reflect God''s character and to live in relationship with Him. Being created in God''s image does not mean we physically look like God. It means we were created with qualities that reflect Him: the ability to love, choose, create, reason, build relationships, and know God. Addiction often attacks these very areas. Instead of freedom, addiction brings bondage. Instead of clear thinking, addiction brings confusion. Instead of healthy relationships, addiction often creates isolation. Instead of purpose, addiction can create hopelessness. Yet addiction cannot erase the image of God. It may distort it. It may cover it with pain and brokenness. But it cannot remove it. God''s image remains part of who you are. Recovery is not about becoming someone completely different. Recovery is about rediscovering who God originally created you to be. Key Scripture: Genesis 1:27. \"So God created man in His own image; in the image of God He created him; male and female He created them.\""}}, {"type": "mentor_note", "content": {"note": "When we understand our value comes from God, we stop seeking value through addictive substances, approval, pleasure, or escape."}}, {"type": "video", "content": {"title": "Understanding Your God-Given Identity", "description": "Explain what it means to be created in God''s image and how addiction can distort a person''s view of themselves. Encourage viewers to see themselves as valuable, loved, and created with purpose."}}, {"type": "pause_reflect", "content": {"question": "How would you describe yourself today?", "context": "Reflect further as you answer: Do you believe you have value apart from your achievements or failures? How has drug abuse and addiction affected your sense of identity? What would change in your life if you truly believed you were created in God''s image? Which quality of God''s image do you most want restored in your life right now?"}}, {"type": "journal_prompt", "content": {"prompt": "Find a quiet place and write down three ways addiction has negatively shaped how you see yourself, three qualities God placed within humanity that reflect His image, and one practical step you can take this week to honor the value God has placed within you."}}, {"type": "mood_checkin", "content": {"question": "How strongly do you feel your God-given worth today?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Spend a few moments praying and thanking God for creating you with purpose and dignity."}}, {"type": "mentor_note", "content": {"note": "You may have made mistakes. You may have hurt yourself and others. You may feel broken. But none of those things determine your worth. Your value was established by God long before your struggles began. The same God who created you has not abandoned you. His image is still within you. His purpose for your life still exists. His grace is greater than your past. Today, choose to see yourself through God''s eyes rather than through the lens of addiction. Memory Verse: Psalm 139:14 - \"I will praise You, for I am fearfully and wonderfully made; marvelous are Your works, and that my soul knows very well.\""}}, {"type": "quiz", "content": {"question": "According to Genesis, humanity was created in whose image?", "options": [{"text": "Society''s image", "is_correct": false}, {"text": "Nature''s image", "is_correct": false}, {"text": "God''s image", "is_correct": true}, {"text": "The world''s image", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction can completely remove the image of God from a person?", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Which of the following reflects God''s design for humanity?", "options": [{"text": "Hopelessness", "is_correct": false}, {"text": "Bondage", "is_correct": false}, {"text": "Purpose", "is_correct": true}, {"text": "Isolation", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that your value is not determined by your addiction, your past, or the opinions of others. You were created in God''s image and carry a God-given purpose that no mistake can erase. In the next lesson, we will explore God''s purpose for life and how understanding that purpose helps us find direction, meaning, and hope in recovery."}}]}, {"number": 3, "title": "The Purpose of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Why Am I Here?", "message": "One of the most common questions people ask is: \"Why am I here?\" Many people struggling with addiction feel lost, confused, and disconnected from any sense of purpose. Life can begin to feel like an endless cycle of surviving one day at a time. But God did not create humanity without direction. The Bible teaches that every person was created intentionally and for a purpose. Today we will explore God''s purpose for human life and how discovering that purpose can become a powerful part of recovery."}}, {"type": "reading", "content": {"title": "Created for More Than Survival", "body": "When God created Adam and Eve, He did not simply place them on the earth without responsibility or meaning. Genesis shows us that God gave humanity purpose from the very beginning. God instructed mankind to be fruitful, multiply, fill the earth, care for creation, exercise stewardship and responsibility, and live in relationship with Him. The author explains that mankind was created in God''s image and entrusted with responsibility over creation. Humanity was not created to wander aimlessly, but to participate in God''s design and purpose for the world. Purpose gives direction. Direction gives meaning. Meaning gives hope. One of the devastating effects of addiction is that it gradually replaces purpose with survival. Instead of asking, \"What was I created for?\" a person begins asking, \"How do I get through today?\" Instead of building a future, they become trapped managing consequences. Instead of pursuing purpose, they pursue relief. But God''s design for your life is greater than simply surviving. God desires that you know Him, grow spiritually, develop healthy relationships, serve others, use your gifts and abilities, and live a life that reflects His goodness. Recovery becomes stronger when it is connected to purpose. When a person discovers something worth living for, they become more willing to fight for their freedom. Purpose becomes fuel for recovery. Key Scripture: Jeremiah 29:11. \"For I know the plans I have for you, says the Lord, plans for peace and not for evil, to give you a future and a hope.\""}}, {"type": "mentor_note", "content": {"note": "Addiction often narrows life down to immediate needs and temporary relief. Recovery expands life by reconnecting us to God''s greater purpose."}}, {"type": "video", "content": {"title": "Discovering God''s Purpose for Your Life", "description": "Discuss how addiction can distract people from God''s purpose and how recovery involves rediscovering the gifts, calling, and opportunities God has placed before them. Encourage viewers to see recovery as part of a bigger journey rather than merely quitting a harmful habit."}}, {"type": "pause_reflect", "content": {"question": "When was the last time you felt your life had purpose?", "context": "Keep reflecting as you answer: How has addiction affected your goals, dreams, or ambitions? What gifts, talents, or strengths do you believe God has given you? What kind of person would you like to become in the future? If addiction was no longer controlling your life, what would you pursue?"}}, {"type": "journal_prompt", "content": {"prompt": "Take a notebook and write down three dreams or goals you once had before addiction became a major part of your life, three strengths or positive qualities you believe God has placed within you, and one small step you can take this week toward a healthier future."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to God''s purpose for your life today?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Finish by praying and asking God to reveal more of His purpose for your life as you take one small step toward a healthier future."}}, {"type": "mentor_note", "content": {"note": "Your life is not an accident. You are not here by chance. God created you intentionally and lovingly. Even if addiction has stolen years of your life, it cannot steal the purpose God has placed within you. Many people in Scripture experienced failure, brokenness, and hardship before stepping into God''s calling. Your story is still being written. Your future does not have to look like your past. God''s purpose for your life remains alive, and each step of recovery brings you closer to it. Memory Verse: Jeremiah 29:11 - \"For I know the plans I have for you, says the Lord, plans for peace and not for evil, to give you a future and a hope.\""}}, {"type": "quiz", "content": {"question": "Did God create humanity with purpose?", "options": [{"text": "Yes", "is_correct": true}, {"text": "No", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Which of the following is one of God''s original instructions to humanity?", "options": [{"text": "Live in fear", "is_correct": false}, {"text": "Hide from responsibility", "is_correct": false}, {"text": "Be fruitful", "is_correct": true}, {"text": "Remain isolated", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often causes people to focus only on survival rather than purpose.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you discovered that God created you with purpose, direction, and hope. Recovery is not only about leaving something behind. It is also about moving toward the life God intended for you. In the next lesson, we will enter the Garden of Eden and begin exploring the environment God created for humanity before the fall."}}]}, {"number": 4, "title": "The Garden of Eden", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Eden was a place of order, relationship, and trust.", "message": "Before brokenness entered the world, humanity lived in a place where God''s presence was near and His boundaries were good. The garden shows us that God never designed life to be chaotic, empty, or ruled by craving. He designed people for fellowship, stewardship, and peace."}}, {"type": "reading", "content": {"title": "You were created for fellowship with God and others, not isolation.", "body": "This is probably the most beautiful view and platform a person can take, from a place of relationship first with God and then with our earthly neighbor. The relationship with God must be perfected, full of love, thoughtful and humble. When we have such a connection with God, our relationship with one another will bear beautiful spiritual fruit devoid of destruction.\n\nKey Scripture: Matthew 22:37.  \"Love the Lord your God with all your heart and with all your soul and with all your mind.  Love your neighbor as yourself.  On these two commandments hang all the Law and the Prophets.\""}}, {"type": "mentor_note", "content": {"note": "God prepared a good place for people to live with Him."}}, {"type": "video", "content": {"title": "The Garden of Eden", "description": "A mentor-led explanation of how Eden reflects God''s original design of order, closeness, stewardship, and peace."}}, {"type": "pause_reflect", "content": {"question": "What healthy boundaries or rhythms could help you return to God''s design?", "context": "Think about the places where life feels chaotic, isolated, or unguarded, and identify where God''s order and peace need to be restored."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one area where you want God''s order restored this week."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to return to God''s design today?"}}, {"type": "daily_action", "content": {"title": "Return to God''s design", "action": "Pray today about one place where you need God''s peace and order."}}, {"type": "mentor_note", "content": {"note": "Your story started with God''s goodness, not your brokenness. The garden reminds us that God''s heart is restoration, not ruin."}}, {"type": "quiz", "content": {"question": "What did the garden reflect before the fall?", "options": [{"text": "Chaos", "is_correct": false}, {"text": "Order and trust", "is_correct": true}, {"text": "Isolation", "is_correct": false}, {"text": "Shame", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: God designed people to be ruled by craving.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does recovery begin by returning to?", "options": [{"text": "God''s design", "is_correct": true}, {"text": "Secrecy", "is_correct": false}, {"text": "Fear", "is_correct": false}, {"text": "Self-hatred", "is_correct": false}]}}, {"type": "complete", "content": {"message": "The garden reminds us that God''s heart is restoration, not ruin.", "encouragement": "The next lesson will show that freedom includes choice, and choice always carries responsibility."}}]}, {"number": 5, "title": "Freedom, Choice, and Responsibility", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Freedom is not doing anything we want; it is the ability to choose what is right.", "message": "The Bible shows that God gave human beings real choice from the beginning. That choice made love, obedience, and trust meaningful. It also means people are responsible for the choices they make. Recovery grows when we stop blaming everybody else and begin choosing life purposefully."}}, {"type": "reading", "content": {"title": "Responsibility is not shame; it is the doorway to change.", "body": "What choices have shaped your life the most, for good or for harm?"}}, {"type": "mentor_note", "content": {"note": "God gave people real freedom, and freedom always carries responsibility."}}, {"type": "video", "content": {"title": "Freedom, Choice, and Responsibility", "description": "A mentor-led explanation of how freedom and responsibility work together, and why wise choices protect healing."}}, {"type": "pause_reflect", "content": {"question": "Where do you need to take responsibility without carrying shame?", "context": "Reflect on the difference between honest responsibility and destructive shame, and identify where you need to choose life purposefully."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one choice you can make today that supports healing."}}, {"type": "mood_checkin", "content": {"question": "How prepared do you feel to choose life today?"}}, {"type": "daily_action", "content": {"title": "Choose life today", "action": "Ask God to help you make one wise choice before the day ends."}}, {"type": "mentor_note", "content": {"note": "Wise choices protect the life God wants to build in you. Freedom becomes powerful when it is guided by truth."}}, {"type": "quiz", "content": {"question": "What gives freedom its true direction?", "options": [{"text": "Impulse", "is_correct": false}, {"text": "Truth", "is_correct": true}, {"text": "Fear", "is_correct": false}, {"text": "Confusion", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Responsibility and shame are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens recovery according to this lesson?", "options": [{"text": "Blaming everything else", "is_correct": false}, {"text": "Choosing life purposefully", "is_correct": true}, {"text": "Avoiding responsibility", "is_correct": false}, {"text": "Giving up", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Freedom becomes powerful when it is guided by truth.", "encouragement": "The next lesson will show how temptation begins by attacking truth."}}]}, {"number": 6, "title": "The First Temptation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The enemy first attacked God''s Word before he ever attacked humanity.", "message": "The first temptation in Scripture was not only about fruit; it was about trust. The serpent questioned God''s goodness and twisted His words. Addiction often works the same way by making a false promise appear like truth, comforting, or harmless. The battle for recovery truly begins when we learn to recognize the lie."}}, {"type": "reading", "content": {"title": "A lie loses power when it is brought into the light.", "body": "What lies have tried to sound true in your own life?"}}, {"type": "mentor_note", "content": {"note": "Temptation often starts with a lie that sounds reasonable."}}, {"type": "video", "content": {"title": "The First Temptation", "description": "A mentor-led explanation of how temptation begins with deception, twisted truth, and misplaced trust."}}, {"type": "pause_reflect", "content": {"question": "What truth from God''s Word can answer those lies today?", "context": "Name the lies that have sounded convincing in your struggle and consider which truth from God confronts them directly."}}, {"type": "journal_prompt", "content": {"prompt": "Write one lie and one scripture truth beside it."}}, {"type": "mood_checkin", "content": {"question": "How alert do you feel to deception and false promises today?"}}, {"type": "daily_action", "content": {"title": "Replace the lie with truth", "action": "Speak one truth from Scripture out loud when temptation rises."}}, {"type": "mentor_note", "content": {"note": "God gives you strength to notice deception early. Temptation is real, but truth is stronger."}}, {"type": "quiz", "content": {"question": "What did the serpent challenge first?", "options": [{"text": "God''s word", "is_correct": true}, {"text": "Human strength", "is_correct": false}, {"text": "Nature", "is_correct": false}, {"text": "The future", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Temptation often sounds harmless at first.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What weakens a lie?", "options": [{"text": "Keeping it hidden", "is_correct": false}, {"text": "Bringing it into the light", "is_correct": true}, {"text": "Following feelings", "is_correct": false}, {"text": "Avoiding scripture", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Temptation is real, but truth is stronger.", "encouragement": "The next lesson will show what happened when temptation was accepted."}}]}, {"number": 7, "title": "The Fall of Man", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The fall changed human experience and introduced separation, shame, and fear.", "message": "Genesis shows that one act of disobedience had lasting consequences. People began hiding from God and from one another. Addiction often repeats that pattern by pushing people into secrecy and distance. The fall teaches us that broken choices create broken outcomes, but it also reminds us that God comes looking for the lost."}}, {"type": "reading", "content": {"title": "Shame hides, but grace calls you forward.", "body": "Where do you tend to hide when you feel exposed or afraid?"}}, {"type": "mentor_note", "content": {"note": "When disobedience entered, shame and hiding followed."}}, {"type": "video", "content": {"title": "The Fall of Man", "description": "A mentor-led explanation of how the fall produced shame, fear, and hiding, and why grace still pursues people."}}, {"type": "pause_reflect", "content": {"question": "What would honesty look like in the presence of God today?", "context": "Consider the places where shame has driven you into secrecy, and what it would mean to stop hiding and come into the light."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you need to stop hiding."}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to bring hidden things into the light today?"}}, {"type": "daily_action", "content": {"title": "Come into the light", "action": "Tell God one honest truth you have been avoiding."}}, {"type": "mentor_note", "content": {"note": "God still seeks people even after failure. God did not stop loving people after the fall."}}, {"type": "quiz", "content": {"question": "What followed disobedience in Genesis?", "options": [{"text": "Peace", "is_correct": false}, {"text": "Shame and hiding", "is_correct": true}, {"text": "Clarity", "is_correct": false}, {"text": "Freedom", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often pushes people into secrecy and distance.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does grace do when shame tells you to hide?", "options": [{"text": "Calls you forward", "is_correct": true}, {"text": "Leaves you alone", "is_correct": false}, {"text": "Confirms your fear", "is_correct": false}, {"text": "Condemns you first", "is_correct": false}]}}, {"type": "complete", "content": {"message": "God did not stop loving people after the fall.", "encouragement": "The next lesson will show how disobedience continues to produce consequences."}}]}, {"number": 8, "title": "The Consequences of Disobedience", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sin produces consequences in the heart, the home, and the future.", "message": "The Bible never hides the cost of disobedience. Pain enters relationships, work becomes harder, fear grows stronger, and the human heart becomes more fractured. Addiction reflects that reality in modern life. It takes what seems private and turns it into consequences that spread outward. Still, God is not shocked by brokenness, and He is able to restore what sin has damaged."}}, {"type": "reading", "content": {"title": "Consequences can teach us, but grace can transform us.", "body": "What consequences of destructive choices have you seen in your life?"}}, {"type": "mentor_note", "content": {"note": "Disobedience always leaves a mark, but it does not have the final word."}}, {"type": "video", "content": {"title": "The Consequences of Disobedience", "description": "A mentor-led explanation of how destructive choices spread consequences and how grace can meet people in the aftermath."}}, {"type": "pause_reflect", "content": {"question": "How can honesty help you respond instead of repeat?", "context": "Think about the consequences you are facing now and how truth, responsibility, and grace can interrupt the cycle."}}, {"type": "journal_prompt", "content": {"prompt": "Write one consequence you are ready to face with God''s help."}}, {"type": "mood_checkin", "content": {"question": "How ready are you to face reality with God today?"}}, {"type": "daily_action", "content": {"title": "Face reality with God", "action": "Take one step today that shows you are no longer avoiding truth."}}, {"type": "mentor_note", "content": {"note": "God can heal damage and rebuild what was broken. Consequences are painful, but they can also become turning points."}}, {"type": "quiz", "content": {"question": "What do consequences often reveal?", "options": [{"text": "That choices do not matter", "is_correct": false}, {"text": "That sin spreads damage", "is_correct": true}, {"text": "That hiding solves things", "is_correct": false}, {"text": "That pain has no meaning", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: God is shocked by brokenness.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What can grace do in the middle of consequences?", "options": [{"text": "Transform and restore", "is_correct": true}, {"text": "Ignore the damage", "is_correct": false}, {"text": "Remove responsibility", "is_correct": false}, {"text": "Encourage denial", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Consequences are painful, but they can also become turning points.", "encouragement": "The next lesson will show why God created the plant kingdom and how wisdom matters."}}]}, {"number": 9, "title": "God''s Creation and the Plant Kingdom", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "God created plants to serve life, not destruction.", "message": "From the beginning, creation was good and useful. Scripture shows that plants were part of God''s provision, but human beings were never meant to worship, abuse, or misuse creation. This lesson helps us see that the problem is not only what exists in creation, but how the human heart chooses to use it. Wisdom protects us from turning a gift into a trap."}}, {"type": "reading", "content": {"title": "A gift becomes harmful when it is used outside God''s wisdom.", "body": "How have you seen good things become harmful when they are misused?"}}, {"type": "mentor_note", "content": {"note": "God made creation good, including the plant kingdom."}}, {"type": "video", "content": {"title": "God''s Creation and the Plant Kingdom", "description": "A mentor-led explanation of why creation is good, and how misuse turns a gift into a trap."}}, {"type": "pause_reflect", "content": {"question": "What does wise stewardship look like in your everyday choices?", "context": "Reflect on the difference between receiving God''s gifts with gratitude and misusing them in ways that bring harm."}}, {"type": "journal_prompt", "content": {"prompt": "Write one way you want to use God''s gifts more wisely."}}, {"type": "mood_checkin", "content": {"question": "How mindful do you feel about using God''s gifts wisely today?"}}, {"type": "daily_action", "content": {"title": "Honor creation with wisdom", "action": "Thank God for one good gift and ask Him to help you use it well."}}, {"type": "mentor_note", "content": {"note": "The gift of creation is meant to be handled with wisdom and purpose. God''s gifts are best received with reverence and proper use."}}, {"type": "quiz", "content": {"question": "What makes a good gift harmful?", "options": [{"text": "Using it outside God''s wisdom", "is_correct": true}, {"text": "Owning it", "is_correct": false}, {"text": "Enjoying it with gratitude", "is_correct": false}, {"text": "Seeing it as provision", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The problem is only what exists in creation, not how people use it.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What protects us from turning a gift into a trap?", "options": [{"text": "Wisdom", "is_correct": true}, {"text": "Impulse", "is_correct": false}, {"text": "Silence", "is_correct": false}, {"text": "Isolation", "is_correct": false}]}}, {"type": "complete", "content": {"message": "God''s gifts are best received with reverence and restraint.", "encouragement": "The final lesson of this chapter will connect these truths to the origins of drug abuse."}}]}, {"number": 10, "title": "Understanding the Origins of Drug Abuse", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Drug abuse is never just about a substance; it is about what the heart is seeking.", "message": "This lesson brings the chapter together. The origins of drug abuse can be seen in temptation, disobedience, pain, shame, and the desire to escape. People often reach for substances because they want relief, comfort, control, or silence. But the root problem goes deeper than chemistry. Healing begins when a person is willing to face the heart honestly and let God begin His work of restoration."}}, {"type": "reading", "content": {"title": "Your pain is real, and God is able to meet it with truth and healing.", "body": "What do you think your heart has been searching for through destructive choices?"}}, {"type": "mentor_note", "content": {"note": "Addiction grows from a mixture of pain, deception, choices, and spiritual brokenness."}}, {"type": "video", "content": {"title": "Understanding the Origins of Drug Abuse", "description": "A mentor-led explanation of how pain, deception, shame, and the desire to escape feed addiction, and why healing has to reach the heart."}}, {"type": "pause_reflect", "content": {"question": "How can honesty with God become the start of real change?", "context": "Consider the deeper needs beneath destructive habits and what it would mean to let God meet them with truth rather than escape."}}, {"type": "journal_prompt", "content": {"prompt": "Write one root issue you want God to help you face directly."}}, {"type": "mood_checkin", "content": {"question": "How ready are you to name the real need behind your struggle today?"}}, {"type": "daily_action", "content": {"title": "Name the real need", "action": "Pray and ask God to show you the deeper need behind your struggle."}}, {"type": "mentor_note", "content": {"note": "When you understand the roots, you can begin to walk toward freedom. Understanding the root is the first step toward lasting freedom."}}, {"type": "quiz", "content": {"question": "What often sits beneath drug abuse?", "options": [{"text": "Only chemistry", "is_correct": false}, {"text": "Pain, deception, and brokenness", "is_correct": true}, {"text": "Lack of intelligence", "is_correct": false}, {"text": "Nothing at all", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Healing begins when a person faces the heart honestly.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What can become the start of real change?", "options": [{"text": "Honesty with God", "is_correct": true}, {"text": "More hiding", "is_correct": false}, {"text": "Denial", "is_correct": false}, {"text": "Numbing pain", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Understanding the root is the first step toward lasting freedom.", "encouragement": "This chapter has traced the path from God''s original design to the heart-level roots of addiction. Carry these truths with you as you move into the next chapter."}}]}]}, {"number": 2, "title": "The Tree of Knowledge of Good and Evil", "description": "Chapter 2 examines how brokenness entered human experience and how it continues shaping desire, behavior, identity, and addiction. It moves from the meaning of the forbidden tree into the entrance of sin, the corruption of human nature, spiritual death, inherited brokenness, addictive patterns, destructive fruit, and God''s restoring answer.\n\nThe goal of this chapter is to help the learner understand that drug abuse and addiction is connected to deeper spiritual and human realities, and that restoration becomes possible when lies are exposed, the bad fruit is faced truthfully, and God''s way back is embraced.", "lessons": [{"number": 1, "title": "Understanding the Forbidden Tree", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This chapter begins where trust was tested.", "message": "The tree of the knowledge of good and evil was not a random object in the garden. It became the place where trust, obedience, and desire were confronted. To understand what drug abuse is all about, we have to understand how forbidden desire works and how the heart responds when boundaries are questioned."}}, {"type": "reading", "content": {"title": "A boundary reveals the condition of the heart.", "body": "God placed the tree in the garden with a clear instruction. The command created a real opportunity for trust and obedience. The issue was not necessarily that the tree itself was evil, but that it represented a boundary that human beings were not meant to cross. Drug abuse often follows a similar pattern. A person sees a limit, questions it, then begins to imagine that what is forbidden might actually offer something good, necessary, or freeing. The forbidden tree helps us see that broken behavior usually starts before the action itself. It starts when the heart begins negotiating with truth. Recovery requires learning to respect life-giving boundaries instead of resenting them. But God told them not to eat from the tree.\n\nGen 3:6 And when the woman saw that the tree was good for food, and that it was pleasant to the eyes, and the tree to be desired to make one wise…"}}, {"type": "mentor_note", "content": {"note": "What we do with a boundary often reveals what we believe about God."}}, {"type": "video", "content": {"title": "Understanding the Forbidden Tree", "description": "A mentor-led explanation of why the forbidden tree mattered, what it revealed about trust, and how temptation often begins by reframing a boundary as a loss instead of protection."}}, {"type": "pause_reflect", "content": {"question": "Which healthy boundaries do you most struggle to respect when desire becomes strong?", "context": "Think about what happens inside you when a limit feels frustrating, unfair, or restrictive. Consider whether the issue is the boundary itself or your response to it."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one boundary you now know is necessary for your healing, and why you have struggled to keep it."}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to accept healthy boundaries today?"}}, {"type": "daily_action", "content": {"title": "Honor one boundary today", "action": "Choose one boundary that protects your recovery and keep it intentionally today without negotiating with it."}}, {"type": "mentor_note", "content": {"note": "A Godly boundary is not there to shrink your life. It is there to protect what God wants to preserve in you."}}, {"type": "quiz", "content": {"question": "What did the forbidden tree primarily represent in this lesson?", "options": [{"text": "Random punishment", "is_correct": false}, {"text": "A test of trust and obedience to God''s Word", "is_correct": true}, {"text": "A meaningless symbol", "is_correct": false}, {"text": "An excuse for failure", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The desire for drug abuse often develops in the heart before it reaches behavior.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does recovery require regarding boundaries?", "options": [{"text": "Resenting them", "is_correct": false}, {"text": "Ignoring them", "is_correct": false}, {"text": "Respecting everyday boundaries", "is_correct": true}, {"text": "Replacing them with impulse", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "This lesson showed that temptation often begins with how we interpret a boundary. In the next lesson, we will look at the entrance of sin and how brokenness moved from desire into action."}}]}, {"number": 2, "title": "The Entrance of Sin", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sin entered when desire agreed with deception.", "message": "Brokenness did not begin the moment the fruit was seen. It entered when the lie was welcomed and acted upon. This matters because abuse like drug abuse also grows when lies move from suggestion into agreement. We need to understand that process clearly if we want lasting freedom."}}, {"type": "reading", "content": {"title": "Sin moves from temptation into action through agreement.", "body": "Genesis shows that Eve saw, desired, and took. That sequence is important. Temptation presents an idea, but sin enters when the heart agrees with the lie and acts on it. Abuse often follows this same progression. First there is a thought, then a justification, then a choice, then a consequence. People often focus only on the visible act, but Scripture shows that the deeper battle is in the moment of agreement. When a lie is believed, what was once resisted starts to feel reasonable. This is why truth matters so much in recovery. People do not only need stronger willpower. They need to break agreement with what is false. But watch how desirable the forbidden fruit became and the disobedience of the woman and the man.\n\nGen 3:6 And when the woman saw that the tree was good for food, and that it was pleasant to the eyes, and the tree to be desired to make one wise, she took of the fruit thereof, and did eat, and gave also unto her husband with her; and he did eat"}}, {"type": "mentor_note", "content": {"note": "The moment of agreement is often the doorway into destructive action."}}, {"type": "video", "content": {"title": "The Entrance of Sin", "description": "A mentor-led explanation of how deception, desire, agreement, and action connect, and why breaking agreement with lies is central to recovery."}}, {"type": "pause_reflect", "content": {"question": "What lies have you agreed with in moments of weakness?", "context": "Look beneath the behavior and identify the belief that made the behavior feel acceptable, necessary, or unavoidable."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one destructive behavior pattern and the lie that usually comes just before it."}}, {"type": "mood_checkin", "content": {"question": "How aware do you feel of the lies that influence your choices today?"}}, {"type": "daily_action", "content": {"title": "Break agreement with one lie", "action": "Name one lie out loud today and replace it with a truth you choose to stand on."}}, {"type": "mentor_note", "content": {"note": "Freedom grows when you stop treating lies like options and start exposing them as enemies."}}, {"type": "quiz", "content": {"question": "When did sin enter according to this lesson?", "options": [{"text": "When temptation appeared", "is_correct": false}, {"text": "When desire agreed and acted", "is_correct": true}, {"text": "When the tree was created", "is_correct": false}, {"text": "When fear showed up", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Will power alone is enough if a lie is still believed.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What must be broken in recovery according to this lesson?", "options": [{"text": "All emotion", "is_correct": false}, {"text": "Agreement with lies", "is_correct": true}, {"text": "Every desire", "is_correct": false}, {"text": "Every boundary", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have seen how sin enters through agreement with deception. In the next lesson, we will look at how sin changed human nature and why that matters for addiction recovery."}}]}, {"number": 3, "title": "How Sin Changed Human Nature", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The fall of mankind did not only affect behavior. It affected human nature.", "message": "After sin entered, people did not remain neutral on the inside. Shame, fear, self-protection, and disorder became part of human experience. Drug abuse makes more sense as a reason when we understand that brokenness reaches deep into the inner person."}}, {"type": "reading", "content": {"title": "Brokenness distorts the heart from the inside out.", "body": "Sin changed how people related to God, to each other, and to themselves. Before the fall there was openness, trust, and peace. After the fall there was hiding, blame, fear, and confusion. This helps explain why abusive behavior is never just a surface problem. People often reach for drugs and abusive substances while already carrying inner disorder. The heart wants comfort, control, escape, or relief because something inside has been disrupted. Scripture does not describe people as permanently hopeless, but it does describe a fallen nature that cannot heal itself apart from God. This is why recovery must be deeper than behavior management and psychology. A person needs renewal at the level of identity, belief, and faith. Romans 3:23 ‘For all have sinned and fall short of the glory of God’.  Romans 5:12 ‘Therefore, just as sin entered the world through on man, and death through sin, and in this way death came to all people, because all sinned.’  Romans 7:18-19 ‘For I have the desire to do what is good, but I cannot carry it out. For I do not do the good I want to do but the evil I do not want to do-this i keep on doing’."}}, {"type": "mentor_note", "content": {"note": "When the inner life is disordered, outward choices and actions have flawed outcomes."}}, {"type": "video", "content": {"title": "How Sin Changed Human Nature", "description": "A mentor-led explanation of how the fall affected the inner person and why addiction often reflects deeper spiritual and emotional disorder."}}, {"type": "pause_reflect", "content": {"question": "Where do you see inner disorder showing up in your life right now?", "context": "Think about fear, blame, shame, confusion, or self-protection, and how those inner patterns may be shaping your choices."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one inward struggle that keeps showing up beneath your outward behavior."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you recognize your inner struggles today?"}}, {"type": "daily_action", "content": {"title": "Bring one inward struggle to God", "action": "Take one inner pattern you usually hide and bring it honestly to God in prayer today."}}, {"type": "mentor_note", "content": {"note": "Real healing reaches deeper than outward behavior. God wants to restore the inner life that behavior reveals."}}, {"type": "quiz", "content": {"question": "What changed after sin entered according to this lesson?", "options": [{"text": "Only external rules", "is_correct": false}, {"text": "Human nature and inner life", "is_correct": true}, {"text": "Nothing significant", "is_correct": false}, {"text": "Only physical work", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is only a surface habit problem.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does recovery need to include?", "options": [{"text": "Only behavior management", "is_correct": false}, {"text": "Renewal of identity, belief, and desire", "is_correct": true}, {"text": "Only discipline", "is_correct": false}, {"text": "Only avoiding consequences", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "This lesson showed why drug abuse and addiction cannot be reduced to outward behavior alone. In the next lesson, we will look more closely at spiritual death and what separation from God means."}}]}, {"number": 4, "title": "Spiritual Death Explained", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Spiritual death means separation from the life of God.", "message": "When God warned that disobedience would bring death, the result was deeper than the body alone. Spiritual death meant separation, alienation, and disconnection from the source of life. This helps explain the emptiness many people try to numb through drug abuse."}}, {"type": "reading", "content": {"title": "Separation creates emptiness that broken solutions cannot satisfy.", "body": "Spiritual death is not merely a dramatic phrase. It describes a real condition of separation from God, who is the source of life, truth, peace, and wholeness. When that separation enters human experience, people feel the absence in many ways: emptiness, restlessness, confusion, fear, and deep dissatisfaction. Drug abuse and addiction often grows in that space. People try to fill spiritual emptiness with substances, stimulation, control, or escape. But separation from God cannot be healed by temporary relief. That is why abusive and addictive cycles keep returning when specific inner issues stay unresolved. What the spirit with the soul needs and what the substance offers are never the same thing. Understanding how spiritual death occur helps us see why recovery must move toward restored connection with God rather than only reduced behavior."}}, {"type": "mentor_note", "content": {"note": "What is spiritually empty will eventually search for something to fill it."}}, {"type": "video", "content": {"title": "Spiritual Death Explained", "description": "A mentor-led explanation of spiritual separation, inner emptiness, and why temporary fixes cannot restore what only God gives."}}, {"type": "pause_reflect", "content": {"question": "Where have you tried to fill emptiness with something that could never truly satisfy?", "context": "Consider whether your coping patterns have been attempts to quiet deeper separation, loneliness, or restlessness."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one kind of emptiness you have tried to manage with escape instead of healing."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of spiritual emptiness in your life today?"}}, {"type": "daily_action", "content": {"title": "Turn emptiness toward God", "action": "When emptiness rises today, pause before reacting and ask God what your soul truly needs."}}, {"type": "mentor_note", "content": {"note": "What feels like a craving is often a deeper cry for life, peace, and reconnection with God."}}, {"type": "quiz", "content": {"question": "What does spiritual death mean in this lesson?", "options": [{"text": "Only physical death", "is_correct": false}, {"text": "Separation from the life of God", "is_correct": true}, {"text": "Loss of intelligence", "is_correct": false}, {"text": "Permanent rejection with no hope", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A temporary fix can fully heal spiritual emptiness.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does abuse and addiction often return according to this lesson?", "options": [{"text": "Because emptiness remains unhealed", "is_correct": true}, {"text": "Because consequences do not exist", "is_correct": false}, {"text": "Because truth does not matter", "is_correct": false}, {"text": "Because people never change", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You now have a clearer picture of why spiritual emptiness is evident in matters of drug abuse and addiction. In the next lesson, we will look at the inheritance of a fallen nature and how broken patterns pass forward."}}]}, {"number": 5, "title": "The Inheritance of a Fallen Nature", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Broken patterns do not begin from nowhere.", "message": "People are born into a world already shaped by the fallen nature of mankind. This does not remove responsibility for any one single person, but it does explain why broken desires, distorted thinking, and unhealthy impulses appear so naturally. Understanding this helps recovery become honest without becoming fatalistic."}}, {"type": "reading", "content": {"title": "Inherited brokenness explains the struggle, but does not excuse surrender.", "body": "The fallen nature means people inherit a condition of brokenness, and most likely get carried over from generation to generation. These are not merely isolated bad moments. This affects thoughts, desires, habits, and reactions. Drug abuse often finds fertile ground in that condition because the heart is already vulnerable to deception, self-centeredness, avoidance, and false comfort. Still, inherited brokenness is not the end of the story. It explains why the struggle can feel intense and persistent, but it does not prove that freedom is impossible. Scripture calls people to truth, repentance, renewal, and transformation because God is not powerless before the fallen nature. Recovery becomes stronger when a person stops denying the reality of inner brokenness but also refuses to treat it as their final identity."}}, {"type": "mentor_note", "content": {"note": "Understanding the struggle should lead to humility, not hopelessness."}}, {"type": "video", "content": {"title": "The Inheritance of a Fallen Nature", "description": "A mentor-led explanation of inherited brokenness, personal responsibility, and why understanding the fallen nature should produce honesty instead of despair."}}, {"type": "pause_reflect", "content": {"question": "Where do you see recurring broken patterns that feel older than your current habits?", "context": "Think about patterns in thought, emotion, reaction, or desire that seem deeply rooted and difficult to interrupt."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one recurring pattern you are ready to confront with humility and hope."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about change in your deeper patterns today?"}}, {"type": "daily_action", "content": {"title": "Name the pattern without surrendering to it", "action": "Identify one deeply rooted pattern today and write one truthful response to it instead of simply accepting it."}}, {"type": "mentor_note", "content": {"note": "Brokenness may explain the battle, but it does not own your future when truth and grace are allowed to work."}}, {"type": "quiz", "content": {"question": "What does the fallen nature explain in this lesson?", "options": [{"text": "Why struggle feels real and persistent", "is_correct": true}, {"text": "Why change is impossible", "is_correct": false}, {"text": "Why people have no responsibility", "is_correct": false}, {"text": "Why truth no longer matters", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Understanding inherited brokenness should make a person hopeless.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens recovery according to this lesson?", "options": [{"text": "Denial", "is_correct": false}, {"text": "Fatalism", "is_correct": false}, {"text": "Honest confrontation with hope", "is_correct": true}, {"text": "Self-condemnation", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have seen that deep patterns can be understood without being excused. In the next lesson, we will connect the human condition directly to addiction and the deeper reasons it grips people."}}]}, {"number": 6, "title": "Drug abuse and the Human Condition", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Drug abuse and addiction is not separate from the human condition. It is one of its clearest expressions of sin.", "message": "Abuse and addiction reveals what happens when human brokenness, desire, pain, and false solutions meet. It is not a strange problem belonging only to certain people. It is a concentrated picture of what happens when the heart looks away from God and Truth. When human beings reach out and explore false sources to fulfil life."}}, {"type": "reading", "content": {"title": "Drug abuse and addiction magnifies what is already broken in the human condition.", "body": "The human condition after the fall includes vulnerability to deception, inner conflict, pain, shame, fear, and self-centered desire. Drug abuse and addiction gathers many of those realities into one destructive cycle. A person feels pain, seeks relief, believes a false promise, acts on it, then suffers deeper consequences and stronger cravings. This is why addiction often feels both deeply personal and strangely repetitive. It is not just about substance access. It is about the way fallen people often try to medicate what only truth, healing, and restored life can address and clarify. Understanding addiction through the human condition helps us move away from shallow labels and toward deeper intervention. We stop asking only, What substance is the issue? and begin asking, What is the heart trying to solve or gain?"}}, {"type": "mentor_note", "content": {"note": "When the heart seeks life in the wrong place, bondage follows."}}, {"type": "video", "content": {"title": "Addiction and the Human Condition", "description": "A mentor-led explanation of how pain, desire, deception, and false relief combine to form addictive cycles."}}, {"type": "pause_reflect", "content": {"question": "What has your heart most often been trying to solve through destructive behavior?", "context": "Look beneath the surface problem and consider whether you have been seeking relief, belonging, control, numbness, comfort, or escape."}}, {"type": "journal_prompt", "content": {"prompt": "Write down the deeper need you think has most often driven your struggle."}}, {"type": "mood_checkin", "content": {"question": "How honestly do you feel you are facing the deeper issue today?"}}, {"type": "daily_action", "content": {"title": "Look beneath the substance", "action": "Before the day ends, write one sentence that starts with: My struggle is often reaching for..."}}, {"type": "mentor_note", "content": {"note": "The more clearly you understand the deeper need, the less power the counterfeit solution keeps."}}, {"type": "quiz", "content": {"question": "What does this lesson say addiction often magnifies?", "options": [{"text": "Only poor discipline", "is_correct": false}, {"text": "The broken human condition", "is_correct": true}, {"text": "Only outside pressure", "is_correct": false}, {"text": "Only curiosity", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is only about substance access.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What deeper question helps recovery according to this lesson?", "options": [{"text": "How can I hide it better?", "is_correct": false}, {"text": "What is my heart trying to solve?", "is_correct": true}, {"text": "How can I avoid all feeling?", "is_correct": false}, {"text": "Why does truth matter?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "This lesson connected addiction to the deeper human condition. In the next lesson, we will look at the fruit of destructive choices and how to recognize what they are producing."}}]}, {"number": 7, "title": "Recognizing the Fruit of Destructive Choices", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Every choice produces fruit, even when the fruit takes time to appear.", "message": "Destructive choices often promise immediate relief while hiding the long-term bad effects of the fruit. Scripture teaches that what is planted eventually grows. Recovery becomes clearer when a person learns to recognize the real fruit their choices have been producing."}}, {"type": "reading", "content": {"title": "If the fruit is destructive, the root and pattern must be examined.", "body": "Destructive choices leave evidence. They produce patterns in relationships, finances, health, emotions, thinking, and spiritual life. Many people stay stuck because they keep focusing on the momentary effect of a choice instead of its full fruit. Addiction especially works this way. It may offer short-term comfort, but its fruit includes secrecy, instability, shame, broken trust, disconnection, and bondage. Recognizing bad fruit is not about condemnation. It is about clarity. When the fruit is finally named honestly, a person can stop pretending the pattern is harmless. Recovery gains traction when the full outcome of destructive choices is no longer minimized. Luke 6:43 “For a good tree does not bear bad fruit, nor does a bad tree bear good fruit.”"}}, {"type": "mentor_note", "content": {"note": "What you keep choosing will keep producing."}}, {"type": "video", "content": {"title": "Recognizing the Fruit of Destructive Choices", "description": "A mentor-led explanation of how destructive fruit appears over time and why honesty about outcomes is essential for change."}}, {"type": "pause_reflect", "content": {"question": "What fruit have your destructive choices been producing in your life?", "context": "Think across areas like relationships, trust, peace, health, stability, focus, and closeness with God."}}, {"type": "journal_prompt", "content": {"prompt": "List three visible outcomes that show your current pattern cannot keep leading you where you want to go."}}, {"type": "mood_checkin", "content": {"question": "How ready are you to face the real fruit of your choices today?"}}, {"type": "daily_action", "content": {"title": "Name the fruit clearly", "action": "Write down one destructive outcome you will no longer minimize or excuse."}}, {"type": "mentor_note", "content": {"note": "Clarity is often painful at first, but it becomes one of the strongest allies in recovery."}}, {"type": "quiz", "content": {"question": "What does this lesson say choices produce?", "options": [{"text": "Only feelings", "is_correct": false}, {"text": "Fruit over time", "is_correct": true}, {"text": "Nothing lasting", "is_correct": false}, {"text": "Only temporary problems", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recognizing destructive fruit is mainly about condemnation.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why is naming the fruit important in recovery?", "options": [{"text": "It creates honest clarity", "is_correct": true}, {"text": "It removes all consequences", "is_correct": false}, {"text": "It avoids pain", "is_correct": false}, {"text": "It excuses the behavior", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You have identified why destructive fruit matters. In the final lesson of this chapter, we will focus on God''s plan for restoration and the path back toward life."}}]}, {"number": 8, "title": "God''s Plan for Restoration", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "God did not expose brokenness to leave people trapped in it.", "message": "This chapter has traced how brokenness entered and spread, but the Truth led story does not end with the fall. God''s plan is restoration. Recovery is possible because God repairs what is broken with truth, grace, and a path back to life."}}, {"type": "reading", "content": {"title": "Restoration is God''s answer to what sin and drug abuse have damaged.", "body": "Restoration means more than behavior improvement. It means a return toward truth, connection, healing, responsibility, and renewed life. God''s plan for restoration does not ignore sin, pain, or consequence. It confronts them honestly while opening a way forward. For addiction recovery, restoration involves repentance, renewed thinking, truthful self-examination, healthy boundaries, wise support, and a growing relationship with God. The person who understands restoration stops viewing recovery as mere survival and begins to see it as rebuilding. God does not only call people out of bondage. He leads them into a different way of living. This is why hope matters. Restoration gives meaning to the hard work of recovery, healing and transformation."}}, {"type": "mentor_note", "content": {"note": "God''s restoration is not denial of damage. It is His answer to it."}}, {"type": "video", "content": {"title": "God''s Plan for Restoration", "description": "A mentor-led explanation of restoration as truth plus grace, and how recovery becomes rebuilding rather than simple damage control."}}, {"type": "pause_reflect", "content": {"question": "What part of restoration do you most need from God right now?", "context": "Consider whether you need truth, healing, courage, repentance, accountability, hope, or renewed desire."}}, {"type": "journal_prompt", "content": {"prompt": "Write one paragraph describing what restoration would look like in your life if you kept moving forward honestly with God."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about restoration today?"}}, {"type": "daily_action", "content": {"title": "Take one restoring step", "action": "Choose one practical step today that aligns with rebuilding rather than repeating old damage."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes stronger when you stop asking only how to avoid collapse and start asking how to rebuild your life with God."}}, {"type": "quiz", "content": {"question": "What does restoration mean in this lesson?", "options": [{"text": "Pretending nothing happened", "is_correct": false}, {"text": "Returning toward truth, healing, and renewed life", "is_correct": true}, {"text": "Avoiding all responsibility", "is_correct": false}, {"text": "Only feeling better emotionally", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: God''s restoration ignores damage and consequence.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What changes when a person understands restoration?", "options": [{"text": "Recovery becomes rebuilding", "is_correct": true}, {"text": "Recovery becomes easier than truth", "is_correct": false}, {"text": "Responsibility disappears", "is_correct": false}, {"text": "Hope becomes unnecessary", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "Chapter 2 has shown how brokenness entered, spread, and shaped the human condition. It has also shown that God''s answer is restoration. You are now ready to continue into Chapter 3 with a clearer understanding of abuse, drug abuse, strongholds, and what responsibility means."}}]}]}, {"number": 3, "title": "The Concept of Abuse", "description": "Chapter 3 defines abuse more precisely and shows how it appears not only in substances, but also in thoughts, motives, relationships, coping patterns, and the inner life. It traces the line from misuse into abuse, exposes the abusive nature of sin, examines self-destruction, hidden heart issues, thought patterns, strongholds, and personal responsibility.\n\nThe goal of this chapter is to help the learner stop minimizing harm, recognize where abusive patterns have taken hold, and embrace responsibility as part of Christ-centered change and recovery.", "lessons": [{"number": 1, "title": "What Is Abuse?", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Abuse is any pattern that uses what was meant for life in a way that causes harm.", "message": "Many people think abuse only refers to extreme acts or visible violence. In reality, abuse is broader. It includes any repeated misuse that damages the body, mind, spirit, relationships, or purpose of a person. This chapter begins by defining abuse clearly so recovery can deal with it honestly."}}, {"type": "reading", "content": {"title": "Abuse is the misuse of something that could be good in a destructive way.", "body": "In Scripture, human beings are called to steward life well. Abuse happens when that stewardship is replaced by harmful behavior, exploitation, excess, manipulation, or destruction. Substance abuse is one example, but abuse can also appear in words, attitudes, thought life, sexuality, power, control, and how a person treats themselves and others. The key issue is not only what is being used, but whether its use honors life or damages it. Many addictive patterns feel normal over time because the mind adjusts to them. That is why clear definition matters. When abuse is named accurately, a person can stop taking lightly what is harmful."}}, {"type": "mentor_note", "content": {"note": "What struggles that are often unidentified are often unchallenged."}}, {"type": "video", "content": {"title": "What Is Abuse?", "description": "A mentor-led explanation of abuse as destructive misuse, and why accurate definition is the first step toward honest recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you minimized patterns that were actually harmful?", "context": "Think about habits, words, reactions, or coping patterns that caused damage even if you did not label them as abuse at the time."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one pattern you now recognize as abusive and describe what damage it has caused."}}, {"type": "mood_checkin", "content": {"question": "How honest do you feel about naming harmful patterns today?"}}, {"type": "daily_action", "content": {"title": "Name one harmful pattern clearly", "action": "Before the day ends, write one sentence that defines a harmful pattern in your life without softening the language."}}, {"type": "mentor_note", "content": {"note": "Truth begins to break denial the moment harm is called what it is."}}, {"type": "quiz", "content": {"question": "How does this lesson define abuse?", "options": [{"text": "Only physical violence", "is_correct": false}, {"text": "Any destructive misuse that causes harm", "is_correct": true}, {"text": "Any mistake at all", "is_correct": false}, {"text": "Only criminal behavior", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Abuse can include how a person treats themselves.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is definition important in recovery?", "options": [{"text": "It helps people minimize patterns", "is_correct": false}, {"text": "It helps harmful behavior stay hidden", "is_correct": false}, {"text": "It brings clarity that challenges denial", "is_correct": true}, {"text": "It removes responsibility", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have a working definition of abuse. In the next lesson, we will separate ordinary use from abuse so the difference becomes clearer."}}]}, {"number": 2, "title": "The Difference Between Use and Abuse", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not everything used becomes abuse, but every abusive pattern involves misuse.", "message": "This lesson draws a line between proper use and destructive use. Recovery gets stronger when a person learns to evaluate not only what they are doing, but how, why, and with what intention they are doing it."}}, {"type": "reading", "content": {"title": "The difference is seen in purpose, control, and outcome.", "body": "Use becomes abuse when something meant to serve life starts ruling or destroys life, distorting it, or damaging it. The difference is often revealed through motive and outcome. Is the thing being used with wisdom, restraint, and gratitude, or with compulsion, secrecy, excess, and harm? Is it serving life, or is it slowly taking over? What leads to addiction, this line gets blurred because abuse is often defended as normal use or ignorance. That is why people need honest questions. Does this pattern weaken my peace, clarity, relationships, health, or spiritual life? If so, the issue is no longer simple use. It has moved into misuse."}}, {"type": "mentor_note", "content": {"note": "What serves you in wisdom should not become what rules you in bondage."}}, {"type": "video", "content": {"title": "The Difference Between Use and Abuse", "description": "A mentor-led explanation of how to distinguish wise use from destructive misuse by looking at motive, control, and outcome."}}, {"type": "pause_reflect", "content": {"question": "What signs show that a pattern in your life has crossed the line from use into abuse?", "context": "Consider secrecy, loss of control, compulsion, shame, damaged peace, broken trust, or physical and emotional consequences."}}, {"type": "journal_prompt", "content": {"prompt": "List three signs that reveal when a pattern has moved from acceptable use into abuse."}}, {"type": "mood_checkin", "content": {"question": "How clearly can you tell the difference between use and abuse today?"}}, {"type": "daily_action", "content": {"title": "Measure one pattern honestly", "action": "Take one habit today and evaluate it by its fruit instead of by your excuses for it."}}, {"type": "mentor_note", "content": {"note": "If the fruit is destructive, the pattern needs to be questioned no matter how normal it feels."}}, {"type": "quiz", "content": {"question": "What helps distinguish use from abuse in this lesson?", "options": [{"text": "Only whether other people approve", "is_correct": false}, {"text": "Purpose, control, and outcome", "is_correct": true}, {"text": "Only how often it happens", "is_correct": false}, {"text": "Only whether it feels good", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often defends abuse as if it were normal use.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What should a person evaluate honestly?", "options": [{"text": "Only intentions", "is_correct": false}, {"text": "Only frequency", "is_correct": false}, {"text": "The fruit of the pattern", "is_correct": true}, {"text": "Only public opinion", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You can now separate use from abuse more clearly. In the next lesson, we will examine the abusive nature of sin itself."}}]}, {"number": 3, "title": "The Abusive Nature of Sin", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sin always takes more than it promises.", "message": "Sin itself is deceptive in nature and can also pose in the form of freedom, positivity, good character, or even truth in the world. But the true nature of sin is abusive, dangerous and destructive. It uses people, distorts desire, damages relationships, and leaves loss behind. Drug abuse and addiction is one of the clearest examples of this abusive pattern."}}, {"type": "reading", "content": {"title": "Sin abuses by promising life while producing destructiveness.", "body": "The nature of sin is deceptive and consuming. It invites a person to believe that something pleasurable will satisfy, there is protection, personal empowerment, or even spiritual growth. Yet the result is always a deeper form of loss. Sin abuses trust, identity, time, relationships, peace, and purpose. That is why addictive behavior cannot be understood merely as poor discipline. It reflects the larger abusive nature of sin itself. Sin does not serve people faithfully. It extracts from them. It leaves shame where it promised comfort and bondage where it promised freedom. This lesson matters because people often stay attached to what is harming them until they see its true nature clearly."}}, {"type": "mentor_note", "content": {"note": "Anything that keeps taking life from you is not your friend."}}, {"type": "video", "content": {"title": "The Abusive Nature of Sin", "description": "A mentor-led explanation of how sin operates abusively by deceiving, consuming, and leaving damage behind."}}, {"type": "pause_reflect", "content": {"question": "What has destructive behavior promised you, and what has it actually delivered?", "context": "Compare the promise with the fruit. Notice where comfort became shame, where relief became bondage, or where control became loss."}}, {"type": "journal_prompt", "content": {"prompt": "Write two columns: what the pattern promised, and what it actually produced."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you see the destructive pattern for what it really is today?"}}, {"type": "daily_action", "content": {"title": "Expose the false promise", "action": "Choose one false promise you have believed and write the damage it actually caused."}}, {"type": "mentor_note", "content": {"note": "Freedom grows when the lie loses its glamour and the damage is finally seen without disguise."}}, {"type": "quiz", "content": {"question": "How does this lesson describe sin?", "options": [{"text": "Neutral", "is_correct": false}, {"text": "Abusive and consuming", "is_correct": true}, {"text": "Harmless if hidden", "is_correct": false}, {"text": "Only emotional", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Sin leaves bondage where it promised freedom.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps a person detach from what is harming them?", "options": [{"text": "Seeing its true nature clearly", "is_correct": true}, {"text": "Defending it more strongly", "is_correct": false}, {"text": "Avoiding the fruit", "is_correct": false}, {"text": "Calling it normal", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "This lesson exposed the abusive character of sin. In the next lesson, we will look at self-destruction and addiction more directly."}}]}, {"number": 4, "title": "Self-Destruction and Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Drug abuse and addiction often turns pain inward, increasing the pain over time, causing self hurt, instead of healing the inner wound.", "message": "Self-destruction is not always loud or immediate. Sometimes it appears through repeated choices that quietly damage health, dignity, peace, relationships, and purpose. Addiction is one of the strongest expressions of this pattern."}}, {"type": "reading", "content": {"title": "Self-destruction happens when pain and deception turn against the self.", "body": "Many people do begin drug abusive behavior because they consciously want to destroy themselves. They begin because they are searching for something, perhaps relief, spirituality, for relief of inner pain, whichever way their reason presents itself at these times. Yet the pattern becomes self-destructive because the method chosen keeps inflicting damage. Over time, a person may feel trapped between wanting change and repeating what hurts them. This is why addiction often carries both shame and confusion. The person is not only fighting the substance or habit. They are fighting a pattern that has learned to move against their own well-being. Recovery deepens when a person begins seeing self-destruction not as their identity, but as a harmful pattern that must be interrupted."}}, {"type": "mentor_note", "content": {"note": "What feels like relief in the moment may be helping destroy you over time."}}, {"type": "video", "content": {"title": "Self-Destruction and Addiction", "description": "A mentor-led explanation of how addictive coping becomes self-destructive and why recovery requires interrupting the pattern with truth and care."}}, {"type": "pause_reflect", "content": {"question": "Where have you been cooperating with what is hurting you?", "context": "Think about behaviors, thoughts, or routines that seem to promise relief but consistently weaken your health, peace, trust, or future."}}, {"type": "journal_prompt", "content": {"prompt": "Describe one self-destructive pattern and one way it has been working against your healing."}}, {"type": "mood_checkin", "content": {"question": "How ready are you to stop cooperating with what harms you?"}}, {"type": "daily_action", "content": {"title": "Interrupt one self-destructive move", "action": "Catch one harmful impulse today and replace it with a single life-giving response."}}, {"type": "mentor_note", "content": {"note": "The pattern may be strong, but it is not the final truth about who you are or where you must end up."}}, {"type": "quiz", "content": {"question": "How does self-destruction often begin according to this lesson?", "options": [{"text": "Through a clear desire for ruin", "is_correct": false}, {"text": "Through attempts at relief that become damaging", "is_correct": true}, {"text": "Only through violence", "is_correct": false}, {"text": "Only through public failure", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Self-destructive patterns should be treated as a persons final identity.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens recovery here?", "options": [{"text": "Interrupting harmful patterns with truth", "is_correct": true}, {"text": "Ignoring the damage", "is_correct": false}, {"text": "Keeping it private forever", "is_correct": false}, {"text": "Accepting the pattern as permanent", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have traced how addiction can become self-destructive. In the next lesson, we will look at hidden abuse in the heart."}}]}, {"number": 5, "title": "Hidden Abuse of the Heart", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not all abuse is visible. Some of it lives in motives, attitudes, and private agreements.", "message": "The heart can practice abuse long before actions become obvious to others. Bitterness, self-hatred, pride, lust, envy, manipulation, and secret contempt all shape how a person treats God, others, and themselves. Recovery and healing has to reach this hidden territory."}}, {"type": "reading", "content": {"title": "The hidden life always influences the visible life.", "body": "Scripture consistently treats the heart as central because what rules the heart eventually shapes speech, reactions, and choices. Hidden abuse of the heart may include harsh self-talk, chronic resentment, secret fantasies, deception, selfish manipulation, or a pattern of using people emotionally for comfort or control. These things may remain unseen for a long time, but they still produce fruit. Drug abuse and other forms of abuse often grow more easily where the hidden heart is already disordered. That is why healing cannot stop at visible conduct. A person must also let God examine the inward places that keep feeding the outer pattern.  Jeremiah 17:9-10 “The heart is deceitful above all things, And desperately wicked, Who can know it? I, the Lord, search the heart, I test the mind, Even to give every man according to his ways, According to the fruit of his doings.”"}}, {"type": "mentor_note", "content": {"note": "What stays hidden in the heart that hurts the person must be brought to the surface for proper judgement."}}, {"type": "video", "content": {"title": "Hidden Abuse of the Heart", "description": "A mentor-led explanation of how inward patterns shape outward behavior, and why hidden heart issues must be brought into the light."}}, {"type": "pause_reflect", "content": {"question": "What hidden attitudes or agreements in your heart need honest attention right now?", "context": "Think about what you rehearse privately, resent inwardly, excuse secretly, or use emotionally for comfort or control."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one hidden heart pattern you do not want to keep protecting."}}, {"type": "mood_checkin", "content": {"question": "How willing are you to let God expose hidden heart issues today?"}}, {"type": "daily_action", "content": {"title": "Bring one hidden issue into the light", "action": "Name one hidden heart pattern in prayer today without defending or softening it."}}, {"type": "mentor_note", "content": {"note": "The heart does not heal by concealment. It heals when truth is welcomed into the places we kept closed."}}, {"type": "quiz", "content": {"question": "What does this lesson say about hidden heart issues?", "options": [{"text": "They stay harmless if unseen", "is_correct": false}, {"text": "They influence the visible life", "is_correct": true}, {"text": "They do not matter in recovery", "is_correct": false}, {"text": "They only affect emotions", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Healing can stop at visible conduct alone.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What should a person do with hidden heart patterns?", "options": [{"text": "Protect them", "is_correct": false}, {"text": "Ignore them", "is_correct": false}, {"text": "Bring them into the light", "is_correct": true}, {"text": "Rename them", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have now looked beneath visible behavior into the heart. In the next lesson, we will focus on thoughts that lead to bondage."}}]}, {"number": 6, "title": "Thoughts That Lead to Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Bondage often starts with repeated thoughts before it appears as repeated behavior.", "message": "The mind is one of the first places where bondage gains momentum. What is rehearsed repeatedly, believed deeply, or defended stubbornly can shape desires, emotions, and actions. This lesson focuses on the thought patterns that prepare the way for addictive cycles."}}, {"type": "reading", "content": {"title": "What the mind processes daily, creates thoughtful patterns.", "body": "Thoughts that lead to bondage do not sound familiar to us in our everyday life. And this could be the unconscious reasons why people do what they do, even if it''s harmful. They may say, I need to feel good or better, doing just a little drugs to cope. I don''t see  how this is harmful. One more time will not matter. Nobody understands me. I deserve relief. These thoughts build internal permission for destructive choices. Over time they become strong pathways, not because they are true, but because they have been repeated and believed. Drug abuse and addiction thrives where the mind keeps offering false permission, distorted interpretation, and hopeless conclusions. Recovery requires challenging those thoughts directly. People need more than motivation. They need a renewed way of thinking that refuses to keep preparing the ground for bondage.  Romans 12:2 “And do not be conformed to this world, but be transformed by the renewing of your mind, that you may prove what is that good and acceptable and perfect will of God…"}}, {"type": "mentor_note", "content": {"note": "A repeated lie can start sounding like your own voice if it is left unchallenged."}}, {"type": "video", "content": {"title": "Thoughts That Lead to Bondage", "description": "A mentor-led explanation of how repeated thoughts become internal permission for destructive choices, and how renewed thinking breaks that cycle."}}, {"type": "pause_reflect", "content": {"question": "Which repeated thought has been giving destructive behavior too much space in your life?", "context": "Identify the sentence or inner script that keeps showing up before the choice is made."}}, {"type": "journal_prompt", "content": {"prompt": "Write one repeated thought that leads you toward bondage and one truth that directly challenges it."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your internal thought patterns today?"}}, {"type": "daily_action", "content": {"title": "Interrupt a repeated lie", "action": "Catch one repeated false thought today and answer it immediately with a written truth."}}, {"type": "mentor_note", "content": {"note": "What the mind stops feeding begins to lose its power over time."}}, {"type": "quiz", "content": {"question": "What do repeated false thoughts often become?", "options": [{"text": "Harmless noise", "is_correct": false}, {"text": "Internal permission for destructive choices", "is_correct": true}, {"text": "Proof of truth", "is_correct": false}, {"text": "A substitute for action", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery needs renewed thinking, not motivation alone.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What should a person do with a repeated lie?", "options": [{"text": "Accept it as normal", "is_correct": false}, {"text": "Challenge it with truth", "is_correct": true}, {"text": "Hide it", "is_correct": false}, {"text": "Let it grow stronger", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "This lesson exposed the thoughts that prepare the ground for bondage. In the next lesson, we will identify personal strongholds more directly."}}]}, {"number": 7, "title": "Identifying Personal Strongholds", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "A stronghold is a place where falsehood has gained influence and resistance becomes difficult.", "message": "Strongholds are not only dramatic spiritual terms. In daily life, they often appear as entrenched patterns of thought, feelings, reactions, and behavior that seem to hold a person in place. Drug addiction is such a stronghold, that it is very difficult to overcome and the person could struggle for years. Recovery moves in the right direction when those strongholds are identified without fear or denial."}}, {"type": "reading", "content": {"title": "What is entrenched must be exposed before it can be dismantled.", "body": "A personal stronghold is usually built over time through repeated lies, repeated choices, unresolved wounds, and deeply rehearsed responses. It may involve addiction itself, but it can also involve shame, fear, self-hatred, bitterness, lust, hopelessness, or control. Strongholds often feel normal because they have been present for so long. Yet they keep limiting truth, freedom, and growth. The purpose of identifying a stronghold is not to glorify it, but to stop pretending it does not exist. Once it is named clearly, a person can begin confronting it with truth, boundaries, support, and spiritual discipline.  2 Corinthians 10:4-5  “For the weapons of our warfare are not carnal but mighty in God for pulling down strongholds,  Casting down arguments and every high thing that exalts itself against the knowledge of God bringing every thought into captivity to the obedience of Christ.”"}}, {"type": "mentor_note", "content": {"note": "What remains unidentified often remains unchallenged and fortified."}}, {"type": "video", "content": {"title": "Identifying Personal Strongholds", "description": "A mentor-led explanation of how strongholds are formed and why identifying them clearly is essential for lasting change."}}, {"type": "pause_reflect", "content": {"question": "What pattern in your life feels most entrenched or hardest to challenge right now?", "context": "Think about what feels automatic, deeply rooted, or especially resistant to change."}}, {"type": "journal_prompt", "content": {"prompt": "Name one personal stronghold and list the lies, feelings, or behaviors that keep reinforcing it."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to confront entrenched patterns honestly today?"}}, {"type": "daily_action", "content": {"title": "Name the stronghold directly", "action": "Write the name of one stronghold clearly today and one boundary or truth that weakens it."}}, {"type": "mentor_note", "content": {"note": "A stronghold loses some of its power the moment it is seen clearly and no longer protected."}}, {"type": "quiz", "content": {"question": "How does this lesson describe a stronghold?", "options": [{"text": "A random bad day", "is_correct": false}, {"text": "An entrenched pattern shaped by lies and repetition", "is_correct": true}, {"text": "Only a public failure", "is_correct": false}, {"text": "Only a physical craving", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Strongholds should be ignored so they do not feel real.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why identify a stronghold clearly?", "options": [{"text": "To glorify it", "is_correct": false}, {"text": "To confront it with truth and boundaries", "is_correct": true}, {"text": "To excuse it", "is_correct": false}, {"text": "To deny it better", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You now have language for personal strongholds. In the final lesson of this chapter, we will focus on responsibility and change."}}]}, {"number": 8, "title": "Taking Responsibility for Change", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing grows when responsibility is embraced objectively.", "message": "This chapter ends by bringing everything back to personal responsibility. Abuse, strongholds, and destructive thoughts may be real, but change still requires ownership. Responsibility is not self-condemnation. It is the courageous choice to stop excusing what needs to change."}}, {"type": "reading", "content": {"title": "Responsibility opens the door that excuses keep shut.", "body": "Real change requires a person to face the truth about their sins and vices and accept that healing will involve wise decisions, discipline, honesty, support, and faithful surrender to God. Responsibility does not mean carrying everything alone, we are  not alone in this world. Responsible for refusing drug abuse, or shifting blame, being passive, or endless postponement. Many people stay stuck because they want change while still protecting the pattern. Responsibility breaks that contradiction. It says: this is real, this is harmful, and I need to live and do things differently. In recovery, responsibility is one of the clearest signs that a person is moving from helpless repetition into intentional change."}}, {"type": "mentor_note", "content": {"note": "Excuses protect the pattern. Taking responsibility begins to break it."}}, {"type": "video", "content": {"title": "Taking Responsibility for Change", "description": "A mentor-led explanation of responsibility as honest ownership, and why change grows when excuses lose their place."}}, {"type": "pause_reflect", "content": {"question": "Where do you need to stop explaining the pattern and start responding to it differently?", "context": "Look at the areas where blame, delay, fear, or passivity have kept change from taking shape."}}, {"type": "journal_prompt", "content": {"prompt": "Write one area where you are ready to take clearer responsibility, and what that will look like this week."}}, {"type": "mood_checkin", "content": {"question": "How willing are you to take ownership of change today?"}}, {"type": "daily_action", "content": {"title": "Choose one responsible response", "action": "Take one small action today that proves you are no longer waiting passively for change."}}, {"type": "mentor_note", "content": {"note": "Responsibility is not punishment. It is participation in the healing God wants to build."}}, {"type": "quiz", "content": {"question": "What does responsibility do according to this lesson?", "options": [{"text": "Opens the door to change", "is_correct": true}, {"text": "Removes all struggle instantly", "is_correct": false}, {"text": "Creates shame by default", "is_correct": false}, {"text": "Excuses destructive patterns", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Taking responsibility means doing everything alone.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What often keeps change from taking shape?", "options": [{"text": "Honest ownership", "is_correct": false}, {"text": "Excuses, blame, and passivity", "is_correct": true}, {"text": "Clear boundaries", "is_correct": false}, {"text": "Truth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "Chapter 3 has defined abuse, exposed strongholds, and brought responsibility back to the center of change. You are ready to continue into Chapter 4 with a clearer understanding of what the heart has been seeking through drugs."}}]}]}, {"number": 4, "title": "The Real Reason People Do Drugs", "description": "Chapter 4 looks beneath drug abuse itself and examines the deeper reasons people reach for destructive substances. It explores escape, pain, trauma, spiritual emptiness, belonging, false comfort, deception, and the deeper needs of the heart that keep driving repeated use.\n\nThe goal of this chapter is to help the learner stop reducing addiction to the substance alone and begin understanding the real needs, wounds, lies, and longings that have been seeking relief through it.", "lessons": [{"number": 1, "title": "Looking Beyond the Substance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The substance is often the surface. The deeper intentions are what the heart desires.", "message": "People often ask why someone misuse or abuse drugs as if the answer is only the drug itself. This chapter begins by looking deeper. Substances matter, but they usually become attractive because they seem to offer something the person feels they need to feel satisfied."}}, {"type": "reading", "content": {"title": "The real question is not only what was abused, but what was really desired.", "body": "Drug abuse and addiction is often misunderstood when people focus only on the substance. The drug may be the visible object, but behind it is usually a deeper pursuit. A person may be seeking some sort of satisfaction, desire, act of belonging, sense of power, escape, comfort, confidence, whatever is personal for the individual. If recovery addresses only the substance while ignoring the deeper reasons, the desire for fulfillment will remain unfound. This is why looking beyond the substance matters. It helps people stop reducing addiction to chemistry or psychology alone and begin asking what the heart has been trying to find, or solve."}}, {"type": "mentor_note", "content": {"note": "The drug may be the tool, but the deeper pursuit reveals more reasons and answers."}}, {"type": "video", "content": {"title": "Looking Beyond the Substance", "description": "A mentor-led explanation of why addiction cannot be understood by examining only the substance, and how deeper motives shape repeated use."}}, {"type": "pause_reflect", "content": {"question": "What do you think you were really looking for through destructive use?", "context": "Look beneath the object itself and think about the emotional or spiritual effect you hoped it would give you."}}, {"type": "journal_prompt", "content": {"prompt": "Write one paragraph answering this question: What was I truly seeking when I reached for the substance?"}}, {"type": "mood_checkin", "content": {"question": "How open do you feel to looking beneath the surface today?"}}, {"type": "daily_action", "content": {"title": "Look beneath the surface", "action": "Before the day ends, name one deeper need that has been hiding behind destructive use."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes clearer when the heart is understood, not only the habit."}}, {"type": "quiz", "content": {"question": "What is the key shift in this lesson?", "options": [{"text": "Focus only on chemistry", "is_correct": false}, {"text": "Look beyond the substance to the deeper pursuit", "is_correct": true}, {"text": "Ignore motives", "is_correct": false}, {"text": "Blame only environment", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The visible substance is usually the whole explanation.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does this deeper view matter for recovery?", "options": [{"text": "Because it addresses the real hunger underneath", "is_correct": true}, {"text": "Because it removes all responsibility", "is_correct": false}, {"text": "Because it makes the substance irrelevant", "is_correct": false}, {"text": "Because it avoids truth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the right lens for this chapter. In the next lesson, we will look specifically at the search for escape."}}]}, {"number": 2, "title": "The Search for Escape", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Many people do not begin with a desire to be harmed. They begin with a desire to get away.", "message": "Escape can feel like relief when pain, pressure, shame, or exhaustion become overwhelming. This lesson focuses on how the search for escape can quietly become the doorway into drug abuse and addiction."}}, {"type": "reading", "content": {"title": "Escape promises distance from pain, but often multiplies it later.", "body": "The desire to escape is deeply human, especially when someone feels trapped by emotional pain, trauma, fear, guilt, loneliness, or failure. Drugs may seem to offer a short road out of what feels unbearable. For a moment, the mind quiets, the body relaxes, or the pain dulls. But escape is not healing. It avoids the pain without resolving it. Over time, the person not only returns to the original burden, but now carries the added weight of dependency, shame, consequence and addiction. Recovery strengthens when people stop confusing escape with forgetting the hurt of the inner life."}}, {"type": "mentor_note", "content": {"note": "What helps you disappear for a moment may cost you more than it gives."}}, {"type": "video", "content": {"title": "The Search for Escape", "description": "A mentor-led explanation of why escape feels powerful in the short term and destructive in the long term."}}, {"type": "pause_reflect", "content": {"question": "What have you most wanted to escape from?", "context": "Think honestly about pressure, pain, memory, fear, disappointment, shame, or inner unrest."}}, {"type": "journal_prompt", "content": {"prompt": "Write down what you were trying to get away from, and what happened after the escape wore off."}}, {"type": "mood_checkin", "content": {"question": "How strong is the desire to escape today?"}}, {"type": "daily_action", "content": {"title": "Name the real pressure", "action": "When the urge to escape rises, pause and identify the exact pain or pressure underneath it."}}, {"type": "mentor_note", "content": {"note": "Escape numbs the symptom for a moment, but healing faces the wound and brings it into truth."}}, {"type": "quiz", "content": {"question": "What does escape often offer at first?", "options": [{"text": "Immediate healing", "is_correct": false}, {"text": "Short-term relief", "is_correct": true}, {"text": "Permanent freedom", "is_correct": false}, {"text": "Clear purpose", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Escape and healing are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps recovery according to this lesson?", "options": [{"text": "Confusing relief with healing", "is_correct": false}, {"text": "Naming the real pressure underneath", "is_correct": true}, {"text": "Avoiding the wound", "is_correct": false}, {"text": "Silencing all emotion", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have looked at escape honestly. In the next lesson, we will go deeper into pain, trauma, and brokenness."}}]}, {"number": 3, "title": "Pain, Trauma, and Brokenness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Unhealed pain often keeps searching for a way to be carried.", "message": "Not every person who experiences pain turns to drug abuse, but many addictive patterns are connected to wounds that were never processed consciously or healed well. This lesson takes that pain seriously without turning it into an excuse."}}, {"type": "reading", "content": {"title": "Pain that stays buried often keeps influencing behavior.", "body": "Pain and trauma can leave a person feeling unsafe, numb, reactive, detached, ashamed, or constantly overwhelmed. When brokenness is not faced with support, truth, and healing, it can begin shaping the way a person copes. Drugs may appear attractive because they seem to soften memory, quiet fear, or interrupt emotional overload. Yet the wound remains. Trauma-aware honesty is important in recovery because it keeps people from treating themselves as random failures when deeper pain has clearly been involved. At the same time, pain must not become permission to keep repeating destruction. Healing honors the wound without surrendering to it.  Psalm 34:18  “The Lord is near to those who have a broken heart, And saves such as have a contrite spirit.”"}}, {"type": "mentor_note", "content": {"note": "A wound that is hidden can still keep directing behavior."}}, {"type": "video", "content": {"title": "Pain, Trauma, and Brokenness", "description": "A mentor-led explanation of the link between unhealed pain and addictive coping, with emphasis on truth, compassion, and responsibility."}}, {"type": "pause_reflect", "content": {"question": "What pain or wound do you think has influenced your choices the most?", "context": "Focus on what has felt unresolved, repeated, or too heavy to carry well."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one wound you believe needs more truth, support, or healing in your recovery journey."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of deeper pain affecting you today?"}}, {"type": "daily_action", "content": {"title": "Acknowledge the wound honestly", "action": "Take one quiet moment today to name the wound without hiding it or using it as an excuse."}}, {"type": "mentor_note", "content": {"note": "Compassion tells the truth about pain, and truth keeps pain from becoming a lifelong ruler."}}, {"type": "quiz", "content": {"question": "What can buried pain do according to this lesson?", "options": [{"text": "Disappear completely", "is_correct": false}, {"text": "Keep influencing behavior", "is_correct": true}, {"text": "Guarantee addiction", "is_correct": false}, {"text": "Remove all responsibility", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Pain should be ignored so recovery can move faster.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What is the balanced response to pain in recovery?", "options": [{"text": "Use it as permission", "is_correct": false}, {"text": "Honor it honestly without surrendering to it", "is_correct": true}, {"text": "Deny it completely", "is_correct": false}, {"text": "Let it define identity", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "This lesson connected addiction to pain and brokenness honestly. In the next lesson, we will focus on spiritual emptiness."}}]}, {"number": 4, "title": "Spiritual Emptiness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sometimes the craving is not only physical or emotional. It is spiritual.", "message": "There are forms of emptiness that no pleasure, success, relationship, or substance can satisfy. This lesson looks at the spiritual void that often sits beneath repeated destructive searching."}}, {"type": "reading", "content": {"title": "What is empty at the soul level cannot be filled by temporary substitutes.", "body": "Spiritual emptiness may show up as restlessness, disconnection, meaninglessness, hollowness, or a constant sense that something is missing. A person may not always use spiritual language for it, but they often feel it. With drug abuse, substances can start functioning like counterfeit answers to this emptiness. They create intensity, relief, mood change, or altered awareness, but they do not restore the soul. The emptiness returns, often stronger than before. Recovery deepens when a person stops asking only how to feel better and starts asking what the soul was created to receive from God."}}, {"type": "mentor_note", "content": {"note": "Temporary intensity is not the same as lasting fulfillment."}}, {"type": "video", "content": {"title": "Spiritual Emptiness", "description": "A mentor-led explanation of spiritual emptiness and why counterfeit forms of relief cannot satisfy what the soul truly needs."}}, {"type": "pause_reflect", "content": {"question": "Where do you notice emptiness, hollowness, or disconnection most in your life?", "context": "Think about your sense of meaning, closeness with God, inner peace, and how you respond when that emptiness rises."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one form of emptiness you have tried to fill with the wrong thing."}}, {"type": "mood_checkin", "content": {"question": "How empty or full do you feel at the soul level today?"}}, {"type": "daily_action", "content": {"title": "Turn the emptiness into prayer", "action": "When emptiness surfaces today, respond with one honest prayer instead of one automatic escape."}}, {"type": "mentor_note", "content": {"note": "What the soul longs for cannot be replaced by something that only changes the moment."}}, {"type": "quiz", "content": {"question": "What does this lesson say about spiritual emptiness?", "options": [{"text": "It can be fully solved by intensity", "is_correct": false}, {"text": "It cannot be satisfied by temporary substitutes", "is_correct": true}, {"text": "It is imaginary", "is_correct": false}, {"text": "It is irrelevant to addiction", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Counterfeit relief restores the soul.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps deepen recovery here?", "options": [{"text": "Only chasing mood change", "is_correct": false}, {"text": "Asking what the soul was created to receive from God", "is_correct": true}, {"text": "Avoiding the issue", "is_correct": false}, {"text": "Silencing all longing", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have looked at spiritual emptiness more clearly. In the next lesson, we will focus on the desire to belong."}}]}, {"number": 5, "title": "The Desire to Belong", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The need for belonging can become powerful enough to shape dangerous choices.", "message": "People are made for relationships, acceptance, and connection. When belonging feels absent, threatened, or conditional, the heart may begin reaching for substitutes that seem to offer closeness or identity."}}, {"type": "reading", "content": {"title": "Belonging is a real need, but unhealthy belonging can still lead to bondage.", "body": "Many people first move toward drug abuse in a social setting. They want acceptance, identity, protection, community, or relief from feeling excluded. The desire to belong is not wrong. It is part of being human. The danger comes when belonging is sought in places that require compromise, false identity, secrecy, or self-destruction. A group may offer temporary acceptance while slowly reinforcing destructive patterns. Recovery often requires a person to grieve false belonging and learn what a healthy community actually looks like.  1 Corinthians 15:33  “Do not be deceived: ‘Evil company corrupts good habits’.”  Proverbs 13:20  “He who walks with wise men will be wise, but the companion of fools will suffer harm.”"}}, {"type": "mentor_note", "content": {"note": "A place that welcomes you into bondage is not true belonging."}}, {"type": "video", "content": {"title": "The Desire to Belong", "description": "A mentor-led explanation of how the need for acceptance shapes drug use and why false belonging must be replaced with healthy connection."}}, {"type": "pause_reflect", "content": {"question": "How has the desire to belong influenced your choices?", "context": "Consider the people, spaces, or identities that felt important enough for you to adjust yourself around them."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one place you sought belonging that did not lead you toward life."}}, {"type": "mood_checkin", "content": {"question": "How connected or disconnected do you feel today?"}}, {"type": "daily_action", "content": {"title": "Identify one healthy connection", "action": "Take one step today toward a person or environment that supports truthful, life-giving belonging."}}, {"type": "mentor_note", "content": {"note": "Real belonging does not require you to destroy yourself in order to stay accepted."}}, {"type": "quiz", "content": {"question": "What does this lesson say about belonging?", "options": [{"text": "It is irrelevant", "is_correct": false}, {"text": "It is a real need that can be sought in harmful places", "is_correct": true}, {"text": "It is always dangerous", "is_correct": false}, {"text": "It should be ignored", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Any form of acceptance is automatically healthy.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does recovery often require here?", "options": [{"text": "Protecting false belonging", "is_correct": false}, {"text": "Learning healthy community and grieving false belonging", "is_correct": true}, {"text": "Avoiding all people", "is_correct": false}, {"text": "Pretending the need does not exist", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "This lesson showed how belonging can shape destructive choices. In the next lesson, we will look at false comforts and false solutions."}}]}, {"number": 6, "title": "False Comforts and False Solutions", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some comforts soothe for a moment while quietly deepening the problem.", "message": "Not every relief is true help. Some forms of comfort postpone pain without healing it, and some solutions solve one pressure while creating ten more. This lesson exposes those counterfeits."}}, {"type": "reading", "content": {"title": "A false comfort feels helpful in the short term, but harmful in the long term.", "body": "People often turn to what works quickly, a quick fix. If something alleviates fear, minimizes the pain, boosts confidence, quiets loneliness, or creates good moods, it can start looking like a solution. But a false comfort never deals honestly with the root issue. It manages the symptoms while strengthening the cycle. False solutions also train the heart to trust the wrong things. Over time, a person stops asking what is true, healthy, and healing, and starts asking only what brings immediate relief. Recovery requires learning to test easy comforts by truth, fruit, and long-term effect."}}, {"type": "mentor_note", "content": {"note": "The thing that calms you fastest is not always the thing that heals you best."}}, {"type": "video", "content": {"title": "False Comforts and False Solutions", "description": "A mentor-led explanation of counterfeit comforts and why short-term relief must be measured against long-term fruit."}}, {"type": "pause_reflect", "content": {"question": "What have you treated as a solution that was actually making things worse?", "context": "Think about what felt helpful quickly but kept strengthening damage over time."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one false comfort and the long-term cost it has carried."}}, {"type": "mood_checkin", "content": {"question": "How strong is the pull toward quick relief today?"}}, {"type": "daily_action", "content": {"title": "Test one comfort by its fruit", "action": "Before choosing quick relief today, ask what its long-term fruit has usually been."}}, {"type": "mentor_note", "content": {"note": "Healing may feel slower than escape, but it does not leave destruction behind."}}, {"type": "quiz", "content": {"question": "What marks a false comfort in this lesson?", "options": [{"text": "It heals the root", "is_correct": false}, {"text": "It soothes briefly while deepening the issue", "is_correct": true}, {"text": "It always feels painful", "is_correct": false}, {"text": "It removes all desire", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Quick relief is always wise relief.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What should guide recovery choices here?", "options": [{"text": "Only speed of relief", "is_correct": false}, {"text": "Truth, fruit, and long-term effect", "is_correct": true}, {"text": "Habit alone", "is_correct": false}, {"text": "Intensity alone", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have identified false comforts more clearly. In the next lesson, we will focus on Satan''s deception through drug abuse and addiction."}}]}, {"number": 7, "title": "Satan''s Deception Through Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Deception is one of the enemies most effective tools because it makes bondage look easy and useful.", "message": "Drug abuse often carries a spiritual layer of deception. The lie is not only that the substance works, but that the person needs it, cannot live without it, or has no better way forward."}}, {"type": "reading", "content": {"title": "Deception keeps bondage strong by distorting what is true.", "body": "Scripture shows that the enemy works through lies, accusation, confusion, temptation, and distorted interpretation. Drug abuse and addiction becomes an ideal place for that strategy because it thrives where people feel desperate, ashamed, isolated, and exhausted. Deception may say, This is who you are. Nobody can help you. One more time does not matter. You are too far gone. You need this to survive. These lies keep people tied to what is destroying them. Recovery deepens when the spiritual battle is recognized and falsehood is answered and replaced with truth.  2 Corinthians 11:14  “And no wonder! For Satan himself transforms himself into an angel of light.”"}}, {"type": "mentor_note", "content": {"note": "A lie keeps its power as long as it sounds believable."}}, {"type": "video", "content": {"title": "Satan''s Deception Through Addiction", "description": "A mentor-led explanation of spiritual deception in addiction and why truth must confront the lies that keep bondage in place."}}, {"type": "pause_reflect", "content": {"question": "Which lie has had the most power over you in your struggle?", "context": "Name the sentence, message, or interpretation that keeps pulling you back toward defeat or repetition."}}, {"type": "journal_prompt", "content": {"prompt": "Write one lie that has shaped your struggle and one truth that directly answers it."}}, {"type": "mood_checkin", "content": {"question": "How alert do you feel to deception today?"}}, {"type": "daily_action", "content": {"title": "Answer one lie with truth", "action": "Choose one lie that often returns and prepare one clear truth statement to answer it today."}}, {"type": "mentor_note", "content": {"note": "Bondage begins to weaken when deception is no longer allowed to speak without being challenged."}}, {"type": "quiz", "content": {"question": "What does deception do in addiction according to this lesson?", "options": [{"text": "Makes bondage look useful", "is_correct": true}, {"text": "Removes confusion completely", "is_correct": false}, {"text": "Creates truth automatically", "is_correct": false}, {"text": "Ends temptation", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Spiritual lies can strengthen addictive cycles.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps break deceptionâ€™s power?", "options": [{"text": "Silence", "is_correct": false}, {"text": "Truth that directly answers the lie", "is_correct": true}, {"text": "Avoiding reflection", "is_correct": false}, {"text": "More secrecy", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You have looked at deception more directly. In the final lesson of this chapter, we will focus on discovering the real need of the heart."}}]}, {"number": 8, "title": "Discovering the Real Need of the Heart", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Until the real need is seen, the false solution often keeps returning.", "message": "This chapter ends by bringing the focus back to the heart. Drugs may have been used for many reasons, but underneath them is often a deeper need that has gone unmet, misunderstood, or misdirected."}}, {"type": "reading", "content": {"title": "The heart keeps reaching until what it truly needs is faced with honestly.", "body": "The real need of the heart may include safety, peace, comfort, healing, belonging, truth, rest, purpose, forgiveness, and closeness with God. The misuse or abuse of drugs cannot truly provide these things, even when they seem to mimic them for a short time. Recovery becomes stronger when a person identifies the deeper need instead of staying trapped in the surface behavior alone. Once the need is clearer, healing can move in a more truthful direction. This does not make the process instant, but it makes it honest. A person no longer asks only, How do I stop using? but also, What does my heart keep calling for, and where should I rightly direct my life?"}}, {"type": "mentor_note", "content": {"note": "The false solution loses strength when the true purpose is finally named."}}, {"type": "video", "content": {"title": "Discovering the Real Need of the Heart", "description": "A mentor-led explanation of deeper heart needs and how truthful recovery learns to bring those needs to God instead of to destructive substitutes."}}, {"type": "pause_reflect", "content": {"question": "What do you believe your heart has been needing most beneath the struggle?", "context": "Consider whether you have been reaching for peace, safety, rest, comfort, belonging, forgiveness, or relief from inner pain."}}, {"type": "journal_prompt", "content": {"prompt": "Write clearly: The real need beneath my struggle may be... Then describe where you want to take that real need instead."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to your deeper requirements today?"}}, {"type": "daily_action", "content": {"title": "Name the true need", "action": "Identify one deeper heart need today and bring it to God in a direct, honest prayer."}}, {"type": "mentor_note", "content": {"note": "When the deeper need is understood, recovery stops being guesswork and starts becoming truthful rebuilding."}}, {"type": "quiz", "content": {"question": "What is the central shift in this lesson?", "options": [{"text": "Focus only on stopping behavior", "is_correct": false}, {"text": "Identify the deeper need beneath the struggle", "is_correct": true}, {"text": "Ignore longing completely", "is_correct": false}, {"text": "Treat every craving as identical", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Drugs can truly provide what the heart ultimately needs.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What question does deeper recovery begin asking?", "options": [{"text": "How do I hide the struggle?", "is_correct": false}, {"text": "What does my heart keep reaching for?", "is_correct": true}, {"text": "How do I feel nothing?", "is_correct": false}, {"text": "Why does truth matter?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "Chapter 4 has traced the deeper reasons people reach for drugs and brought the focus back to the heart. You are ready to continue into Chapter 5 with a clearer understanding of how addiction progresses over time."}}]}]}, {"number": 5, "title": "The Stages of Drug Abuse", "description": "Chapter 5 traces how drug abuse progresses over time from curiosity and experimentation into repeated use, dependency, escalation, loss of control, financial loss, and the need for honest self-recognition. It ends by turning the learner toward God''s way out.\n\nThe goal of this chapter is to help the learner understand drug abuse and addiction as a progressive journey, recognize their present stage with clarity, and begin responding to the pattern with seriousness, humility, and hope.", "lessons": [{"number": 1, "title": "Understanding the Drug Addiction Journey", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction usually develops through stages, not all at once.", "message": "Many people think addiction appears suddenly, but most journeys into strongholds and bondage unfold progressively. This chapter helps trace that progression so the learner can understand where patterns begin, how they grow, and where intervention becomes urgent."}}, {"type": "reading", "content": {"title": "A journey can be tracked, and what can be tracked can be faced more honestly.", "body": "Drug abuse often develops in stages. A person moves from interest, to experimentation, to repeated use, to dependency, and then into deeper forms of bondage, uncontrollable cravings and finally full blown addiction. Seeing addiction as a continuation of drug abuse without natural restraint helps remove confusion. It shows that destructive patterns usually build momentum over time through repeated choices to abuse drugs, wanting to satisfy urgent cravings, and growing tolerance to drugs and harmful situations. This matters in recovery because people often misjudge their own position and circumstances. Some think they are fine because they have not reached the addiction stage. Others feel hopeless because they only see where they ended up. Understanding the progression from bad to worse drug abusive circumstances creates clarity and helps recovery meet the process truthfully."}}, {"type": "mentor_note", "content": {"note": "Increasing bad living circumstances related to drug abuse that grows gradually is often ignored until it becomes painful enough to notice."}}, {"type": "video", "content": {"title": "Understanding the Addiction Journey", "description": "A mentor-led overview of the progression of addiction, showing how destructive habits often deepen through stages rather than appearing all at once."}}, {"type": "pause_reflect", "content": {"question": "What stage of the journey do you think you recognize that you realize something really bad is happening?", "context": "Consider whether you relate more to the beginning stages, the middle patterns, or the later consequences and what that reveals."}}, {"type": "journal_prompt", "content": {"prompt": "Write a short summary of how your own struggle progressed over time."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you see your own journey today?"}}, {"type": "daily_action", "content": {"title": "Map the pattern honestly", "action": "List the major turning points that moved your struggle from early interest into something stronger."}}, {"type": "mentor_note", "content": {"note": "Clarity about the journey is one of the first protections against repeating it blindly."}}, {"type": "quiz", "content": {"question": "What is a key idea of this lesson?", "options": [{"text": "Addiction appears instantly", "is_correct": false}, {"text": "Addiction often unfolds progressively through stages", "is_correct": true}, {"text": "Only certain people progress", "is_correct": false}, {"text": "Stages do not matter", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Understanding the journey helps recovery respond more honestly.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is tracking the journey useful?", "options": [{"text": "It removes all responsibility", "is_correct": false}, {"text": "It creates clarity about how the pattern deepened", "is_correct": true}, {"text": "It excuses the behavior", "is_correct": false}, {"text": "It replaces healing", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the overview for this chapter. In the next lesson, we will begin with curiosity and experimentation."}}]}, {"number": 2, "title": "Curiosity and Experimentation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addictions can be the end result that started with curiosity.", "message": "The first stage often looks harmless. A person wonders, explores, tests, or tries something once. Yet what feels small in the beginning can become the doorway to something far larger if curiosity is not governed by wisdom."}}, {"type": "reading", "content": {"title": "Experimentation often seems small because its consequences have not fully appeared yet.", "body": "Curiosity can be innocent in some settings, but when it approaches destructive substances or harmful environments, it becomes dangerous quickly. Many people begin using drugs without imagining the future cost and consequences. They want the experience, the social inclusion, the thrill, the relief, or the story that comes with trying something new. Because the first step may not look harmful it is a drastic step, and it is easy to minimize it. But early experimentation matters because it forms the first agreement: I am willing to cross this line and see what it gives me. That willingness can become the seed of future bondage."}}, {"type": "mentor_note", "content": {"note": "The first small yes often matters more than people realize."}}, {"type": "video", "content": {"title": "Curiosity and Experimentation", "description": "A mentor-led explanation of how early curiosity opens the door to experimentation and why that first step should not be treated casually."}}, {"type": "pause_reflect", "content": {"question": "What made experimentation seem acceptable or attractive at the time?", "context": "Think about the setting, the people, the pressure, and the belief that made the first step feel safe enough."}}, {"type": "journal_prompt", "content": {"prompt": "Write honestly about what drew you toward the first experiment."}}, {"type": "mood_checkin", "content": {"question": "How cautious do you feel about curiosity and temptation today?"}}, {"type": "daily_action", "content": {"title": "Respect the first step", "action": "Identify one area where casual curiosity could still lead you somewhere harmful and set a boundary around it."}}, {"type": "mentor_note", "content": {"note": "A first step is never only a first step if it keeps teaching the heart to cross lines without reverence."}}, {"type": "quiz", "content": {"question": "Why is experimentation significant in this lesson?", "options": [{"text": "Because it is always harmless", "is_correct": false}, {"text": "Because it can become the seed of future bondage", "is_correct": true}, {"text": "Because it ends the journey quickly", "is_correct": false}, {"text": "Because it removes curiosity", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: People usually begin experimentation while fully expecting long-term bondage.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What should guide early choices around harmful curiosity?", "options": [{"text": "Wisdom and boundaries", "is_correct": true}, {"text": "Impulse only", "is_correct": false}, {"text": "Social approval only", "is_correct": false}, {"text": "Excitement only", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have looked at the first stage more carefully. In the next lesson, we will see how repeated use turns experimentation into habit."}}]}, {"number": 3, "title": "Repeated Use and Habit Formation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "What is repeated often becomes familiar, and what becomes familiar can start feeling normal.", "message": "This stage marks the shift from occasional use into a pattern. Repetition changes how the mind, body, and heart respond, and habit begins to take shape."}}, {"type": "reading", "content": {"title": "A pattern becomes dangerous when repetition begins training the whole person around it.", "body": "Habit formation happens through repetition. What was once experimental starts becoming expected. The person begins building routines around the substance or behavior for drug taking. Certain emotions, times of day, locations, or relationships become linked to its use. Over time, the pattern feels less like a choice and more like an automatic response. This stage is dangerous because the behavior is no longer isolated. It is becoming integrated into daily life. The more it is repeated, the more normal it feels, even when its fruit is harmful. Recovery often requires breaking not only the substance pattern, but the habits and associations built around it."}}, {"type": "mentor_note", "content": {"note": "What is practiced long enough begins to feel natural, even when it is harmful."}}, {"type": "video", "content": {"title": "Repeated Use and Habit Formation", "description": "A mentor-led explanation of how repetition forms habits and why addictive routines become stronger through repeated use and association."}}, {"type": "pause_reflect", "content": {"question": "What routines or triggers became connected to your repeated use?", "context": "Think about times, places, feelings, and people that became part of the pattern."}}, {"type": "journal_prompt", "content": {"prompt": "List the main triggers and routines that helped your pattern become habitual."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your habit cycle today?"}}, {"type": "daily_action", "content": {"title": "Identify one habit cycle within your urge to take drugs", "action": "Write down one cue, one response, and one consequence that make up a pattern you want to break."}}, {"type": "mentor_note", "content": {"note": "A habit can be unlearned, but only when it is first seen clearly enough to interrupt."}}, {"type": "quiz", "content": {"question": "What marks this stage of addiction?", "options": [{"text": "One-time use only", "is_correct": false}, {"text": "Repeated drug abuse and deep cravings", "is_correct": true}, {"text": "Instant recovery", "is_correct": false}, {"text": "No change in routine", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Habit formation often includes triggers and associations.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What must recovery often break at this stage?", "options": [{"text": "Only the label", "is_correct": false}, {"text": "The habit loops and associations around use", "is_correct": true}, {"text": "Only public consequences", "is_correct": false}, {"text": "Only curiosity", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You now see how repetition builds habit. In the next lesson, we will focus on dependency and bondage."}}]}, {"number": 4, "title": "Dependency and Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Dependency grows when the person no longer feels free to say no without distress.", "message": "At this stage, the pattern has moved beyond habit into attachment and need. The person begins feeling that the substance or behavior is required in order to cope, function, calm down, or feel normal."}}, {"type": "reading", "content": {"title": "Dependency changes the relationship from optional to necessary.", "body": "Dependency is one of the clearest markers that drug abuse is slowly deepening into bondage. The person no longer uses only by preference. They feel driven by craving, discomfort, fear, some withdrawal, or perceived inability to manage life without it. Bondage is not only physical. It is also emotional, mental, and spiritual. The substance becomes a master, and the person begins organizing life around its demands. This is why dependency is so serious. What once looked like freedom of choice now begins exposing a loss of freedom altogether."}}, {"type": "mentor_note", "content": {"note": "What begins as an option can become a master if it is fed long enough."}}, {"type": "video", "content": {"title": "Dependency and Bondage", "description": "A mentor-led explanation of how dependency forms, what bondage looks like, and why this stage reveals a real loss of freedom."}}, {"type": "pause_reflect", "content": {"question": "Where have you felt least free to say no?", "context": "Think about what happens in your mind, body, or emotions when you try to resist the pattern."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one sign that showed you the pattern had become more than a casual habit."}}, {"type": "mood_checkin", "content": {"question": "How trapped or free do you feel in your current patterns today?"}}, {"type": "daily_action", "content": {"title": "Tell the truth about the hold", "action": "Describe in one sentence what the pattern has been demanding from you lately."}}, {"type": "mentor_note", "content": {"note": "Bondage loses some of its invisibility the moment you stop pretending you are fully in control."}}, {"type": "quiz", "content": {"question": "What changes in dependency according to this lesson?", "options": [{"text": "The pattern stays optional", "is_correct": false}, {"text": "The pattern begins to feel necessary", "is_correct": true}, {"text": "The danger disappears", "is_correct": false}, {"text": "The craving becomes irrelevant", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Bondage can be emotional, mental, and spiritual, not only physical.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is dependency serious?", "options": [{"text": "Because it reveals a growing loss of freedom", "is_correct": true}, {"text": "Because it removes all feeling", "is_correct": false}, {"text": "Because it always stays hidden", "is_correct": false}, {"text": "Because it improves control", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have looked directly at dependency. In the next lesson, we will examine the progression of addiction as it keeps deepening."}}]}, {"number": 5, "title": "The Progression to Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction is like a deep hunger. What is fed usually asks for more.", "message": "As drug abuse progresses to addiction, the same behavior often stops producing the same effect. Tolerance, escalation, concealment, and risk can all increase. This lesson focuses on how the cycle and pattern deepens over time."}}, {"type": "reading", "content": {"title": "Progression happens when the pattern keeps demanding more while giving less.", "body": "Progression means drug abuse is no longer static. The person may need more of the substance, more frequent use, stronger forms of stimulation, or riskier environments to reach the same effect. At the same time, the promised relief becomes less satisfying and the consequences become heavier. The pattern demands more energy, time, money, secrecy, and compromise. This is why progression into deeper troubled waters needs to be watched. It exposes that addiction is not a stable arrangement. It is a deepening one. If left unchallenged, it will usually continue asking for more than the person expected to give."}}, {"type": "mentor_note", "content": {"note": "Addiction grows by demanding more while giving less."}}, {"type": "video", "content": {"title": "The Progression of Addiction", "description": "A mentor-led explanation of escalation, tolerance, and deepening consequences as addiction progresses."}}, {"type": "pause_reflect", "content": {"question": "In what ways did the pattern of addiction demand and crave more?", "context": "Think about time, money, secrecy, risk, emotional cost, and how much more it took to get the same result."}}, {"type": "journal_prompt", "content": {"prompt": "Write three ways the pattern became more demanding as it progressed."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you see the progression now?"}}, {"type": "daily_action", "content": {"title": "Name the escalation", "action": "Identify one way the pattern now costs more than it did at the beginning."}}, {"type": "mentor_note", "content": {"note": "What keeps progressing will keep taking unless it is interrupted with truth and action."}}, {"type": "quiz", "content": {"question": "What often increases as addiction progresses?", "options": [{"text": "Only peace", "is_correct": false}, {"text": "Tolerance, cravings, and consequence", "is_correct": true}, {"text": "Freedom only", "is_correct": false}, {"text": "Honesty only", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction usually stays stable if left alone.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why is progression important to recognize?", "options": [{"text": "It shows danger in all circumstances now", "is_correct": true}, {"text": "It removes the need for change", "is_correct": false}, {"text": "It proves there is no hope", "is_correct": false}, {"text": "It ends dependency", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You now see more clearly how addiction progresses. In the next lesson, we will focus on losing control."}}]}, {"number": 6, "title": "Losing Control", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Loss of control becomes visible when intention and behavior stop matching.", "message": "Many people promise themselves they will manage the pattern better next time. But as addiction deepens, the gap widens between what a person intends and what they actually do."}}, {"type": "reading", "content": {"title": "Loss of control is often exposed where good intentions keep failing against a strong addiction.", "body": "Lack of control does not always mean total chaos immediately. It often appears through repeated broken promises, failed limits, hidden relapse, impulsive use, and the growing realization that the pattern does not respond easily to personal resolve. The person may keep trying to negotiate with it, but the addiction keeps winning. This stage can feel humiliating because it exposes how little command the person truly has over what once seemed manageable. Yet that exposure can also become a turning point. Honest recognition of uncontrollable cravings often creates the humility needed for real help."}}, {"type": "mentor_note", "content": {"note": "Addiction is revealing lack of control when your promises keep collapsing under it."}}, {"type": "video", "content": {"title": "Losing Control", "description": "A mentor-led explanation of what loss of control looks like in addiction and why honest humility becomes essential at this stage."}}, {"type": "pause_reflect", "content": {"question": "Where have your intentions and your behavior stopped matching?", "context": "Think about promises, limits, timelines, or boundaries you set that the pattern kept overriding."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where losing control became undeniable."}}, {"type": "mood_checkin", "content": {"question": "How willing are you to be fully honest about lost control today?"}}, {"type": "daily_action", "content": {"title": "Stop negotiating with the evidence", "action": "Write one clear example that proves the pattern has been stronger than your private promises."}}, {"type": "mentor_note", "content": {"note": "Honest humility is painful, but it is often the doorway to real help."}}, {"type": "quiz", "content": {"question": "How is loss of control often exposed?", "options": [{"text": "Through perfect boundaries", "is_correct": false}, {"text": "Through the gap between intention and behavior", "is_correct": true}, {"text": "Through instant healing", "is_correct": false}, {"text": "Through silence", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Honest recognition of lost control can become a turning point.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What often grows from this honesty?", "options": [{"text": "More denial", "is_correct": false}, {"text": "Humility needed for real help", "is_correct": true}, {"text": "Total hopelessness only", "is_correct": false}, {"text": "Better excuses", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have faced the issue of control more directly. In the next lesson, we will examine the cost of sin and addiction."}}]}, {"number": 7, "title": "The Cost of Sin and Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Drug addiction carries a heavy cost, even when that cost is delayed.", "message": "Sin and addiction promise something costly, but the price to pay carries a heavy burden. This lesson focuses on how addiction robs, kills and destroys a person over time."}}, {"type": "reading", "content": {"title": "The true cost is measured not only in money or asset value, but the price paid with human life.", "body": "Addiction can cost trust, peace, health, clarity, relationships, finances, time, dignity, integrity, and spiritual wellbeing and physical death. Sometimes these losses come dramatically. At other times they accumulate quietly until the person suddenly realizes how much has been drained away. Human life and spiritual connection with God is the most important value to life. This is the very thing that needs to be shared in the world. The only direction to healing and full recovery for the person is to have the connection with God or not waste time to make the connection or re-establish relationship with God."}}, {"type": "mentor_note", "content": {"note": "What costs you your peace is already costing more than you may want to admit."}}, {"type": "video", "content": {"title": "The Cost of Sin and Addiction", "description": "A mentor-led explanation of the many forms of loss addiction creates and why counting the cost honestly matters in recovery."}}, {"type": "pause_reflect", "content": {"question": "What has drug abuse cost you most so far?", "context": "Think broadly about internal peace, relationships, trust, health, finances, time, and closeness with God."}}, {"type": "journal_prompt", "content": {"prompt": "Make a direct list of the major costs drug abuse has created in your life."}}, {"type": "mood_checkin", "content": {"question": "How do you feel about such losses in your life today?"}}, {"type": "daily_action", "content": {"title": "Count the cost honestly", "action": "Write down the top three losses you do not want to keep paying for."}}, {"type": "mentor_note", "content": {"note": "When we take stock of what we lost, what we projected to lose, is it all worth it."}}, {"type": "quiz", "content": {"question": "What does this lesson emphasize?", "options": [{"text": "Only financial cost", "is_correct": false}, {"text": "The many forms of loss addiction creates", "is_correct": true}, {"text": "Only public shame", "is_correct": false}, {"text": "No real long-term cost", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Denial survives more easily when the full cost is never counted.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why count the cost honestly?", "options": [{"text": "To romanticize the pattern", "is_correct": false}, {"text": "To remove seriousness", "is_correct": false}, {"text": "To see clearly what is being lost", "is_correct": true}, {"text": "To avoid change", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You have faced the cost more honestly. In the next lesson, we will focus on recognizing where you are in the journey right now."}}]}, {"number": 8, "title": "Recognizing Where You Are", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Clarity about your present stage helps stop vague recovery and starts serious actions.", "message": "People often stay confused because they speak generally about the struggle instead of investing their mind, soul and spirit fully into understanding. This lesson helps the learner identify their overall position in the journey."}}, {"type": "reading", "content": {"title": "You cannot respond wisely to a stage if you are not honest.", "body": "Identifying your position abusing drugs is not about labeling yourself with shame. It is about seeing clearly enough to respond truthfully. Some people are still protecting their habit by downplaying its seriousness. Others are deep in their addiction, dependency, and whatever in addition keep them bound. Some recognize the seriousness but still minimize the urgency. Recovery becomes stronger when a person stops speaking vaguely and says: this is where I am, this is the pattern in my life, and this is what must change. Clear self-identification with drug effects breaks confusion and helps the right kind of support and action."}}, {"type": "mentor_note", "content": {"note": "Honesty about where you are is not defeated. It can be the start of a new direction."}}, {"type": "video", "content": {"title": "Recognizing Where You Are", "description": "A mentor-led explanation of why self-location matters in recovery and how honest recognition breaks confusion and passivity."}}, {"type": "pause_reflect", "content": {"question": "Where do you believe you are right now in the journey?", "context": "Use the stages in this chapter to locate yourself as accurately as possible without exaggerating or minimizing."}}, {"type": "journal_prompt", "content": {"prompt": "Write a clear sentence describing the stage you believe fits your struggle most honestly right now."}}, {"type": "mood_checkin", "content": {"question": "How clear or confused do you feel about your present stage today?"}}, {"type": "daily_action", "content": {"title": "Locate yourself honestly", "action": "Describe your current stage to yourself in plain language without avoiding the truth."}}, {"type": "mentor_note", "content": {"note": "Direction becomes possible when vagueness finally gives way to truth."}}, {"type": "quiz", "content": {"question": "What is the purpose of this lesson?", "options": [{"text": "To shame the learner", "is_correct": false}, {"text": "To help the learner locate their real stage honestly", "is_correct": true}, {"text": "To avoid labels completely", "is_correct": false}, {"text": "To skip self-reflection", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Clear recognition can help the right support and action emerge.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does honest self-location break?", "options": [{"text": "Truth", "is_correct": false}, {"text": "Confusion and passivity", "is_correct": true}, {"text": "Responsibility", "is_correct": false}, {"text": "Need for help", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "You have located your current position more honestly. In the final lesson of this chapter, we will focus on God''s way out."}}]}, {"number": 9, "title": "God''s Way Out", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "No stage of addiction is beyond the reach of God''s intervention.", "message": "This chapter ends with hope. The progression is real, the bondage is serious, and the cost is high, but God''s way out is not imaginary. Recovery is possible because truth, repentance, grace, support, and a new way of living can interrupt the destructive journey and redirect it."}}, {"type": "reading", "content": {"title": "The way out begins when the addiction is faced fully and God''s truth is welcomed practically.", "body": "God''s way out is not a shortcut that avoids real acceptance. It is a path that includes confession, repentance, humility, support, wise boundaries, renewed thinking, and dependence on His Word. The person who wants the way out must stop protecting the old pattern while asking for freedom from it. They must recognize what''s the truth, accept help, and begin walking differently, completely eliminating the old ways. Scripture consistently teaches that God provides a way to stand, resist, return, and rebuild. The way out may be tough, but it leads toward life rather than deeper bondage.  John 14:6 Jesus said to him, “I am the Way, the Truth, and the Life. No one comes to the Father except through Me."}}, {"type": "mentor_note", "content": {"note": "Hope is real when it is joined to truthful surrender and action."}}, {"type": "video", "content": {"title": "God''s Way Out", "description": "A mentor-led explanation of God''s way out through truth, repentance, support, boundaries, and renewed life."}}, {"type": "pause_reflect", "content": {"question": "What part of God''s way out do you most need to embrace right now?", "context": "Consider whether you most need confession, support, truth, boundaries, humility, structure, or a new daily response."}}, {"type": "journal_prompt", "content": {"prompt": "Write one paragraph describing what the way out will require from you this week."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about taking the next truthful step today?"}}, {"type": "daily_action", "content": {"title": "Take one step toward the way out", "action": "Choose one concrete action today that aligns with freedom instead of repetition."}}, {"type": "mentor_note", "content": {"note": "The way out of drug abuse and addiction is a journey. A journey towards a new life and new existence."}}, {"type": "quiz", "content": {"question": "What does God''s way out include in this lesson?", "options": [{"text": "Avoiding honesty", "is_correct": false}, {"text": "Truth, repentance, support, and new beginnings", "is_correct": true}, {"text": "Only waiting for feelings to change", "is_correct": false}, {"text": "Hiding the struggle better", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A person can keep protecting the old pattern while fully embracing freedom.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps make hope real here?", "options": [{"text": "Truthful surrender to God", "is_correct": true}, {"text": "Passive wishing", "is_correct": false}, {"text": "More secrecy", "is_correct": false}, {"text": "Ignoring the stage", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 9.", "encouragement": "Chapter 5 has shown the stages of addiction and ended with the reality that God''s way out is the only way. You are ready to continue into Chapter 6 with a deeper understanding of perception, deception, shame, and spiritual blindness."}}]}]}, {"number": 6, "title": "Spiritual Eyes of the Evil Nature", "description": "Chapter 6 focuses on spiritual awareness, distorted perception, deception, shame, fear, condemnation, blindness, and the restoration of sight through God''s truth. It helps the learner understand how addiction shapes the way reality is interpreted and how truth can reorient that inner lens.\n\nThe goal of this chapter is to help the learner become more spiritually aware, more honest about distortion and accusation, and more grounded in God''s truth as the lens for recovery.", "lessons": [{"number": 1, "title": "Spiritual Awareness and Influence", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not every struggle is only visible or physical. Some battles involve spiritual influence.", "message": "This chapter shifts focus toward perception, deception, shame, and blindness. It begins by helping the learner recognize that addiction is not only behavioral or emotional. Spiritual influence also shapes how people interpret life, truth, and temptation."}}, {"type": "reading", "content": {"title": "Spiritual awareness helps a person recognize influences they once treated as normal.", "body": "Spiritual awareness does not mean becoming dramatic or fearful. It means recognizing that the inner life is shaped by more than emotions, moods and habits alone. Scripture describes real spiritual conflict, real deception, and real influence. With drug abuse and addiction, this matters because people often misread what is happening inside them. They may think every urge is just physical, every thought is just personal, and every temptation is just random. But recovery develops when the learner begins noticing how lies, shame, accusation, distortion, and confusion operate from a spiritual dimension. Spiritual awareness helps a person stop only seeing the surface, but know the battle is deeper.  2 Corinthians 10:3-4 “For though we walk in the flesh, we do not war according to the flesh. For the weapons of our warfare are not carnal but mighty in God for pulling down strongholds.”"}}, {"type": "mentor_note", "content": {"note": "You cannot fight most effectively until you know how to fight spiritually."}}, {"type": "video", "content": {"title": "Spiritual Awareness and Influence", "description": "A mentor-led introduction to spiritual awareness, showing how unseen influence can shape thought, temptation, and behavior."}}, {"type": "pause_reflect", "content": {"question": "Where do you sense that your struggle has involved more than a simple habit alone?", "context": "Think about repeated thoughts, accusations, temptations, or inner pressure that feel it has direct and personal intension against you with spiritual strategy."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one part of your struggle that now seems to involve a deeper spiritual battle."}}, {"type": "mood_checkin", "content": {"question": "How spiritually alert do you feel today?"}}, {"type": "daily_action", "content": {"title": "Notice the deeper battle", "action": "Pause once today and ask what deeper influence may be shaping your reaction, not just the visible trigger."}}, {"type": "mentor_note", "content": {"note": "Spiritual awareness is not paranoia. It is the discipline of recognizing spiritual life."}}, {"type": "quiz", "content": {"question": "What does spiritual awareness help with in this lesson?", "options": [{"text": "Ignoring deeper influence", "is_correct": false}, {"text": "Recognizing the battle beneath the surface", "is_correct": true}, {"text": "Avoiding responsibility", "is_correct": false}, {"text": "Reducing everything to emotion", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Drug abuse can involve spiritual deception and influence.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is this awareness important?", "options": [{"text": "It helps seeing the truth", "is_correct": true}, {"text": "It removes all struggle instantly", "is_correct": false}, {"text": "It makes truth unnecessary", "is_correct": false}, {"text": "It replaces discipline", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the opening frame for this chapter. In the next lesson, we will examine how addiction distorts perception."}}]}, {"number": 2, "title": "How Addiction Distorts Perception", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction changes not only behavior, but also the way a person sees.", "message": "One reason addiction is difficult to break is that it slowly reshapes perception. The person starts reading reality through craving, acquiring drugs, protection and need instead of truth."}}, {"type": "reading", "content": {"title": "Distorted perception makes destructive choices look reasonable.", "body": "When addiction distorts perception, the person may underestimate danger, overestimate their control, reinterpret consequences, mistrust help, or exaggerate the value of satisfaction. What is harmful begins looking like normal drug abusive living. What is wise begins looking restrictive. What is loving correction begins sounding like an attack. This type of distortion matters in how we perceive, because recovery depends on clear sight and vision. A person who cannot see the truth and accuracy will keep misreading both their current lifestyle and what is way out. Truth has to restore perception so choices can be made with pure vision and purpose.  2 Corinthians 4:18  “While we do not look at the things that are seen, but at the things which are not seen. For the things which are seen are temporary, but the things which are not seen are eternal”. 1 Corinthians 2:14  “But the natural man does not receive the things of the Spirit of God, for they are foolishness to him, nor can he know them, because they are spiritually discerned”."}}, {"type": "mentor_note", "content": {"note": "What you keep feeding will eventually start framing how you see."}}, {"type": "video", "content": {"title": "How Addiction Distorts Perception", "description": "A mentor-led explanation of how addiction alters perspective and why clear perception is essential for recovery."}}, {"type": "pause_reflect", "content": {"question": "Where has your perception felt most unreliable during the struggle?", "context": "Think about how you viewed the substance, yourself, other people, consequences, and help."}}, {"type": "journal_prompt", "content": {"prompt": "Write one example of a time you now realize your perception was deeply distorted."}}, {"type": "mood_checkin", "content": {"question": "How clear or clouded does your perception feel today?"}}, {"type": "daily_action", "content": {"title": "Question one distorted conclusion", "action": "Catch one conclusion today that may be shaped more by craving or fear than by truth."}}, {"type": "mentor_note", "content": {"note": "Recovery often begins by admitting that you have not been seeing things clearly."}}, {"type": "quiz", "content": {"question": "What does distorted perception do?", "options": [{"text": "Makes danger easier to see", "is_correct": false}, {"text": "Makes harmful choices seem ok", "is_correct": true}, {"text": "Eliminates craving", "is_correct": false}, {"text": "Guarantees freedom", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Clear sight matters in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps restore perception?", "options": [{"text": "Truth", "is_correct": true}, {"text": "More denial", "is_correct": false}, {"text": "More secrecy", "is_correct": false}, {"text": "Impulse", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have seen how addiction distorts perception. In the next lesson, we will focus directly on the nature of deception."}}]}, {"number": 3, "title": "The Nature of Deception", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Deception works when it sounds believable enough.", "message": "People don''t purposefully want to choose destruction on themselves, because it doesn''t have any benefits with such thinking. Deception leads the person to choose what has first been disguised, justified, or reframed. This lesson explores how deception operates in addiction."}}, {"type": "reading", "content": {"title": "Deception hides danger by changing the story around it.", "body": "The nature of deception is to make what is false feel true or appear true, and what is dangerous feel necessary, and what is destructive feel manageable. With drug abuse and addiction, deception often whispers that things are under control, that help is not needed, that damage is recoverable, or that the person is too far gone to change anyway. These distortions keep the cycle of drug abuse alive. Deception thrives where thoughts go unchallenged and truth is not applied clearly. This is why recovery requires more than just the idea of wanting to be clean. It requires active resistance to falsehood, deception and lies with truth and understanding.  2 Corinthians 11:14  And no wonder! For Satan himself transforms himself into an angel of light."}}, {"type": "mentor_note", "content": {"note": "A lie stays unchallenged when the person remains ignorant."}}, {"type": "video", "content": {"title": "The Nature of Deception", "description": "A mentor-led explanation of how deception reframes danger and keeps addictive cycles protected from truth."}}, {"type": "pause_reflect", "content": {"question": "Which deception has sounded most convincing in your life about drug abuse?", "context": "Name the message that most often despised your boundaries or weakened your resistance."}}, {"type": "journal_prompt", "content": {"prompt": "Write one lie that kept sounding convincing and one truth that exposes it."}}, {"type": "mood_checkin", "content": {"question": "How alert are you to deception today?"}}, {"type": "daily_action", "content": {"title": "Expose one lie clearly", "action": "Take one repeated false message and answer it today with a direct truth statement."}}, {"type": "mentor_note", "content": {"note": "The more specific the lie becomes, the more specific the truth must become in response."}}, {"type": "quiz", "content": {"question": "What does deception do according to this lesson?", "options": [{"text": "Makes falsehood obvious", "is_correct": false}, {"text": "Reframes danger and falsehood as believable", "is_correct": true}, {"text": "Removes temptation", "is_correct": false}, {"text": "Guarantees wisdom", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery requires resistance to falsehood.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken deception?", "options": [{"text": "Leaving it unexamined", "is_correct": false}, {"text": "Applying specific truth", "is_correct": true}, {"text": "More vagueness", "is_correct": false}, {"text": "Avoiding reflection", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have looked at deception more directly. In the next lesson, we will examine shame, fear, and guilt."}}]}, {"number": 4, "title": "Shame, Fear and Guilt", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Shame, fear and guilt often keep people trapped long after the damage is already visible.", "message": "These inner forces do not only describe emotion. They also shape behavior, concealment, avoidance, and the desire to keep numbing real feelings. This lesson helps separate bad emotions from bad and to understand their position with addiction."}}, {"type": "reading", "content": {"title": "Shame says you are ruined, fear says there is no safe way forward, and guilt reminds you what you have done wrong all this time.", "body": "Guilt can be a signal that something needs to be faced and made right. Shame, however, often goes further and tells the person that they themselves are the problem beyond hope. Fear then magnifies the sense that honesty, help, or change is too much responsibility and energy. Together these forces create powerful pressure toward concealment and repetition. Addiction often prevails where shame keeps getting masked, guilt stays unresolved, and fear blocks honest change. Recovery becomes effective when these realities are understood clearly and brought under truth instead of allowed to rule in silence.  Isaiah 41:10  Fear not, for I am with you;  Be not dismayed, for I am your God. I will strengthen you, Yes, I will help you, I will uphold you with My righteous right hand’.  Psalms 23:4  Yea, though I walk through the valley of the shadow of death, I will fear no evil, For You are with me, Your rod and Your staff, they comfort me."}}, {"type": "mentor_note", "content": {"note": "What is not understood clearly often keeps ruling deeply."}}, {"type": "video", "content": {"title": "Shame, Fear, and Guilt", "description": "A mentor-led explanation of the difference between shame, fear, and guilt, and how each one can strengthen addictive cycles."}}, {"type": "pause_reflect", "content": {"question": "Which of these has been strongest in your struggle: shame, fear, or guilt?", "context": "Think about how each one has affected your identity, your choices, and your willingness to seek help."}}, {"type": "journal_prompt", "content": {"prompt": "Write one example how shame, fear, or guilt has kept you stuck."}}, {"type": "mood_checkin", "content": {"question": "Which of these feels strongest in you today?"}}, {"type": "daily_action", "content": {"title": "Name what is pressing hardest", "action": "Choose the strongest inner pressure today and describe exactly how it has been influencing you."}}, {"type": "mentor_note", "content": {"note": "What is named clearly can begin to lose the power it held in silence."}}, {"type": "quiz", "content": {"question": "What does shame tend to say according to this lesson?", "options": [{"text": "Something needs correcting", "is_correct": false}, {"text": "You are ruined beyond hope", "is_correct": true}, {"text": "Ask for help", "is_correct": false}, {"text": "The danger is gone", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Fear can block honest change.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps recovery in this lesson?", "options": [{"text": "Letting silence rule", "is_correct": false}, {"text": "Naming these forces clearly under truth", "is_correct": true}, {"text": "Confusing them further", "is_correct": false}, {"text": "Ignoring guilt entirely", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have separated shame, fear, and guilt more clearly. In the next lesson, we will focus on the voice of condemnation."}}]}, {"number": 5, "title": "The Voice of Condemnation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Condemnation attacks identity and keeps the person fixed in defeat.", "message": "Condemnation does not simply point out wrong. It speaks as though failure is final, change is useless, and the person is already defeated. This lesson helps the learner recognize that voice clearly."}}, {"type": "reading", "content": {"title": "Condemnation does not correct. It crushes.", "body": "The voice of condemnation often sounds absolute, personal, and final. It says, ‘This is who you are’. You never change. God is done with you. There is no point trying again. These messages do not lead a person toward repentance, honesty, or healing. They push toward despair, hiding, and further bondage. When the person is in the addiction stage, condemnation can become one of the strongest reasons a person keeps returning to what harms them. They stop believing and become really challenged and they feel there is no meaningful alternative. Recovery requires learning to distinguish condemnation from conviction. Conviction invites change. Condemnation announces defeat.  Romans 8:1 There is therefore now no condemnation to those who are in Christ Jesus, who do walk according to the flesh, but according to the Spirit.  Luke 6:37  “Judge not, and you shall not be judged. Condemn not, and you shall not be condemned. Forgive, and you will be forgiven."}}, {"type": "mentor_note", "content": {"note": "A crushing voice is not the same as a truthful invitation to change."}}, {"type": "video", "content": {"title": "The Voice of Condemnation", "description": "A mentor-led explanation of condemnation, how it differs from conviction, and why it keeps addiction cycles alive."}}, {"type": "pause_reflect", "content": {"question": "What condemning message has felt most persistent in your struggle?", "context": "Name the exact voice or inner message that keeps telling you change is pointless or impossible."}}, {"type": "journal_prompt", "content": {"prompt": "Write one condemning message and then write how it differs from a truthful call to change."}}, {"type": "mood_checkin", "content": {"question": "How loud does condemnation feel today?"}}, {"type": "daily_action", "content": {"title": "Separate condemnation from conviction", "action": "Take one harsh inner message today and ask whether it invites healing or only announces defeat."}}, {"type": "mentor_note", "content": {"note": "Truth may confront you, but condemnation tries to bury you under what it confronts."}}, {"type": "quiz", "content": {"question": "How does condemnation operate in this lesson?", "options": [{"text": "It leads gently to change", "is_correct": false}, {"text": "It attacks identity and declares defeat", "is_correct": true}, {"text": "It always sounds hopeful", "is_correct": false}, {"text": "It removes shame immediately", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Conviction and condemnation are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does condemnation strengthen addiction?", "options": [{"text": "It creates meaningful hope", "is_correct": false}, {"text": "It pushes people toward despair and repetition", "is_correct": true}, {"text": "It clarifies identity", "is_correct": false}, {"text": "It builds trust", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have identified condemnation more clearly. In the next lesson, we will look at spiritual blindness and how it forms."}}]}, {"number": 6, "title": "Recognizing Spiritual Blindness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Spiritual blindness keeps the person from seeing God''s truth and grace.", "message": "Spiritual blindness can mean not having the knowledge of God, not seeing His Truth. The ability to see through the eyes of His Truth has such significant value that it hinges on life and death. This lesson helps the learner recognize how that blindness operates in addiction."}}, {"type": "reading", "content": {"title": "Spiritual blindness survives where truth is resisted, distorted, or kept at a distance.", "body": "Spiritual blindness may appear as denial, selective honesty, defensiveness, constant excuse-making, or repeated failure to connect actions with its fruit. A spiritually blind person may still talk about change while avoiding the truth required for it. With drug abuse and addiction, this type of blindness is very dangerous because it delays urgency and weakens conviction. The person may not fully grasp what direction their path is heading, how deeply they are compromised, or how necessary grace and truth really are. It is the knowledge of God that opens the spiritual eyes, removes the spiritual blindness and gives purposeful vision and direction.  Ephesians 1:17-18  that the God of our Lord Jesus Christ, the Father of glory, may give to you the spirit of wisdom and revelation in the knowledge of Him.  the eyes of your understanding being enlightened, that you may know what is the hope of His calling, what are the riches of the glory of His inheritance in the saints."}}, {"type": "mentor_note", "content": {"note": "A person can know facts and still remain spiritually blind to life."}}, {"type": "video", "content": {"title": "Recognizing Spiritual Blindness", "description": "A mentor-led explanation of spiritual blindness, denial, and the need for clearer sight in recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you think you have been least willing to see clearly?", "context": "Think about areas where you kept information but avoided its implications for your life."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where spiritual sight is still needed in your recovery."}}, {"type": "mood_checkin", "content": {"question": "How open are you to a spiritual life with God today?"}}, {"type": "daily_action", "content": {"title": "Ask for clearer vision", "action": "Pray specifically today for clearer sight in one area you have kept resisting."}}, {"type": "mentor_note", "content": {"note": "Clear sight is not comfortable at first, but it is kinder than blindness in the long run."}}, {"type": "quiz", "content": {"question": "What is spiritual blindness in this lesson?", "options": [{"text": "Only lacking information", "is_correct": false}, {"text": "Being unable or unwilling to accept the Truth of God", "is_correct": true}, {"text": "Instant peace", "is_correct": false}, {"text": "A permanent condition with no answer", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Spiritual blindness can delay urgency in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is the right response to blindness here?", "options": [{"text": "Protect it", "is_correct": false}, {"text": "Admit Godly sight is needed", "is_correct": true}, {"text": "Pretend facts are enough", "is_correct": false}, {"text": "Avoid prayer", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have looked at spiritual blindness more honestly. In the final lesson of this chapter, we will focus on seeing through God''s truth."}}]}, {"number": 7, "title": "Seeing Through God''s Truth", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The chapter ends not with distortion, but with restored sight.", "message": "Spiritual awareness, clear perception, resistance to deception, freedom from condemnation, and healing from spiritual blindness all depend on a stronger vision. That lens is God''s truth. This lesson focuses on seeing life, who we really are, and recovery through the truth."}}, {"type": "reading", "content": {"title": "God''s truth does more than inform. It reorients the whole inner life.", "body": "Seeing through God''s truth means allowing His Word (scripture), conviction, grace, and reality to shape interpretation more than craving, fear, shame, or deception. It means asking not only what feels true, but what God says is true. His Truth restores all areas of life with completeness. It reminds the person that the struggle is real, but not final; that damage is serious, but not beyond redemption; that temptation is powerful, but not beyond resistance; and that recovery is costly, but still possible. The person who learns to see through God''s truth is better able to resist the distortions that once controlled their responses.  John 8:32  “And you shall know the truth, and the truth shall make you free.”"}}, {"type": "mentor_note", "content": {"note": "A new life usually begins with a new lens, a new vision."}}, {"type": "video", "content": {"title": "Seeing Through God''s Truth", "description": "A mentor-led conclusion to the chapter, showing how God''s truth restores sight and reshapes the way the learner interprets struggle and hope."}}, {"type": "pause_reflect", "content": {"question": "Where do you most need God''s truth to replace distorted interpretation right now?", "context": "Consider your identity, your future, your struggle, your worth, and the possibility of change."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want to practice seeing through God''s truth instead of through a drug abuse perception."}}, {"type": "mood_checkin", "content": {"question": "How anchored do you feel in truth today?"}}, {"type": "daily_action", "content": {"title": "Choose the lens of truth", "action": "Take one repeated distorted interpretation today and consciously replace it with a truth-based one."}}, {"type": "mentor_note", "content": {"note": "Truth does not erase the battle, but it keeps the battle from defining reality falsely."}}, {"type": "quiz", "content": {"question": "What does God''s truth do in this lesson?", "options": [{"text": "Only provide information", "is_correct": false}, {"text": "Reorients how the inner life interprets reality", "is_correct": true}, {"text": "Removes all effort", "is_correct": false}, {"text": "Makes temptation irrelevant", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Truth can restore definitively in the middle of struggle.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What changes when a person sees through God''s truth?", "options": [{"text": "Distortions lose some control", "is_correct": true}, {"text": "Shame becomes more accurate", "is_correct": false}, {"text": "Blindness grows stronger", "is_correct": false}, {"text": "Hope disappears", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "Chapter 6 has moved from awareness to restored sight. You are ready to continue into Chapter 7 with a clearer understanding of inner conflict, law, and obedience."}}]}]}, {"number": 7, "title": "The Two Laws", "description": "Chapter 7 explains the inner conflict between the law of sin and death and the law of the Spirit of life. It helps the learner interpret the struggle more accurately, distinguish flesh from Spirit, understand the weight of daily choices, and walk in obedience under grace.\n\nThe goal of this chapter is to give the learner a clearer framework for understanding why conflict exists, how obedience becomes practical, and how God''s grace sustains recovery without compromise.", "lessons": [{"number": 1, "title": "The Law of Sin and Death", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "There is a pattern that keeps pulling the old life toward destruction.", "message": "This chapter begins by naming one of the core realities of the inner struggle: the law of sin and death. It describes the repeated pull toward drug abuse and what breaks life down instead of building it up."}}, {"type": "reading", "content": {"title": "The law of sin and death describes the inward pattern that keeps producing bondage and loss.", "body": "A law in this context is not merely a common rule written on paper. It is the power of a  recurring principle that keeps producing the same result. The law of sin and death names the pattern in fallen human nature that bends toward rebellion, self-rule, distortion, and destructive living. With drug abuse and addiction, this shows up as repeated cycles: desire, indulgence, regret, shame, and return. A person may sincerely want change, yet still feel the weight of a force stronger than good intentions alone. Recognizing this law helps the learner stop being confused by the conflict and start understanding why surface promises have often failed.  Romans 7:19-21  For the good that I will to do, I do not do, but the evil I will not to do, that I practice.  Now if I do what I will not to do, it is no longer I who do it, but sin that dwells in me.  I find then a law, that evil is present with me, the one who wills to do good."}}, {"type": "mentor_note", "content": {"note": "What repeats with power could be understood to be attached to a spiritual law."}}, {"type": "video", "content": {"title": "The Law of Sin and Death", "description": "A mentor-led introduction to the inner law that keeps drawing a person back toward destructive patterns."}}, {"type": "pause_reflect", "content": {"question": "Where have you seen the same destructive cycle repeat in your own life?", "context": "Think about patterns that kept returning even after regret, promises, or short-lived resolve."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one repeated cycle that helps you understand the pull of the law of sin and death."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of repeated destructive patterns today?"}}, {"type": "daily_action", "content": {"title": "Name the cycle", "action": "Write down one cycle clearly today from trigger to consequence so you stop speaking about it vaguely."}}, {"type": "mentor_note", "content": {"note": "Clarity about the pattern is the beginning of resistance to destructive laws attached to it."}}, {"type": "quiz", "content": {"question": "What does the law of sin and death describe in this lesson?", "options": [{"text": "A recurring destructive principle in fallen nature", "is_correct": true}, {"text": "A random feeling", "is_correct": false}, {"text": "A healthy habit", "is_correct": false}, {"text": "A temporary inconvenience", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A person can want change and still feel the weight of this law.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is naming this law useful?", "options": [{"text": "It removes responsibility", "is_correct": false}, {"text": "It explains the conflict more in depth", "is_correct": true}, {"text": "It guarantees instant freedom", "is_correct": false}, {"text": "It makes discipline unnecessary", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the first frame for Chapter 7. In the next lesson, we will look at the law of the Spirit of life."}}]}, {"number": 2, "title": "The Law of the Spirit of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The struggle is real, but it is not the only law at work.", "message": "The chapter now turns from the law that creates bondage to the powerful law that creates new life. The law of the Spirit of life explains how God works within a believer toward freedom, renewal, and obedience."}}, {"type": "reading", "content": {"title": "The law of the Spirit of life is the active principle power of God''s liberating work within the believer.", "body": "If the law of sin and death describes the pull toward destruction, the law of the Spirit of life describes the new principle by which God leads a person into freedom and newness of life. This law does not mean struggles instantly disappear. It means the learner no longer continuously has to suffer under the old pattern and law of destruction. God''s Spirit works to renew life, reveal the truth, action true obedience, and give a new vision forward. Recovery is sustained not only by resistance to sin, but by walking in the law of the Spirit of life in which is in Christ. This law introduces hope that is stronger than mere self-effort.  Romans 8:2  For the law of the Spirit of life in Christ Jesus has made me free from the law of sin and death.  Romans 8:11  But if the Spirit of Him who raised Jesus from the dead dwells in you, He who raised Christ from the dead will also give life to your moral bodies through His Spirit who dwells in you. Sonship through the Spirit."}}, {"type": "mentor_note", "content": {"note": "Freedom begins when the law of the spirit of life starts working within you."}}, {"type": "video", "content": {"title": "The Law of the Spirit of Life", "description": "A mentor-led explanation of the new life God gives and how it works against the old law of bondage."}}, {"type": "pause_reflect", "content": {"question": "Where have you seen even a small sign of new life or new desire in your recovery?", "context": "Look for small but real evidence that truth, conviction, or obedience is beginning to grow."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one sign that God is producing new life in you, even if it still feels fragile."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about real change today?"}}, {"type": "daily_action", "content": {"title": "Notice the new direction", "action": "Name one way today that your response is becoming more aligned with life instead of destruction."}}, {"type": "mentor_note", "content": {"note": "The old pattern may still speak, but it is no longer the only voice shaping the future."}}, {"type": "quiz", "content": {"question": "What does the law of the Spirit of life describe?", "options": [{"text": "The active work of God toward freedom", "is_correct": true}, {"text": "More shame", "is_correct": false}, {"text": "A reason to ignore struggle", "is_correct": false}, {"text": "A rejection of obedience", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: This law means struggle instantly disappears.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does this lesson add to recovery?", "options": [{"text": "Hopelessness", "is_correct": false}, {"text": "A stronger basis for hope than self-effort alone", "is_correct": true}, {"text": "More confusion", "is_correct": false}, {"text": "Less need for truth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have now seen that two different laws are at work. In the next lesson, we will examine the inner conflict between them."}}]}, {"number": 3, "title": "The Inner Conflict", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery often feels like a conflict because it is one.", "message": "Many people feel discouraged by inner tension, as if conflict means failure. This lesson explains that conflict is often evidence that two different forces are now competing within the same life."}}, {"type": "reading", "content": {"title": "The inner conflict is the collision between old desires and the renewed person.", "body": "The learner may feel torn between what they know is the right way and the truth, and what still feels familiar, attractive, or relieving when it comes to drug abuse. This conflict can be exhausting, but it is important to understand it properly. The presence of conflict does not necessarily mean that nothing is changing. It often means the law of sin and death is being confronted by the law of the Spirit of Life. The issue is not whether conflict exists, but which side is being fed, believed, and obeyed. Recovery becomes meaningful when the learner realizes the old ways are dangerous and starts interpreting conflict as a call to seek complete redemption.  Romans 7:15  For what I am doing, I do not understand. For what I will to do, that I do not practice, but what I hate, that I do."}}, {"type": "mentor_note", "content": {"note": "Consistent inner conflict is not the end of progress. It is often where progress must turn into new life."}}, {"type": "video", "content": {"title": "The Inner Conflict", "description": "A mentor-led explanation of why inner conflict exists and how to respond to it without panic or resignation."}}, {"type": "pause_reflect", "content": {"question": "How have you usually interpreted inner conflict in the past?", "context": "Consider whether you treated conflict as failure, confusion, or a normal part of growth."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you feel the inner conflict most strongly right now."}}, {"type": "mood_checkin", "content": {"question": "How steady do you feel in the middle of conflict today?"}}, {"type": "daily_action", "content": {"title": "Interpret conflict differently", "action": "When conflict appears today, remind yourself that the question is not whether there is tension, but what motivates you to overcome."}}, {"type": "mentor_note", "content": {"note": "The battle becomes more of purpose when it is understood instead of feared."}}, {"type": "quiz", "content": {"question": "What does the inner conflict reveal in this lesson?", "options": [{"text": "Only failure", "is_correct": false}, {"text": "A collision between old desires and a new life", "is_correct": true}, {"text": "Proof that change is impossible", "is_correct": false}, {"text": "A reason to give up", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Conflict automatically means nothing is changing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What matters most in conflict?", "options": [{"text": "Pretending it is not there", "is_correct": false}, {"text": "Being dependant on the Spirit of Life", "is_correct": true}, {"text": "How dramatic it feels", "is_correct": false}, {"text": "How long you can avoid thinking about it", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have framed the inner conflict more accurately for growth and not defeat. In the next lesson, we will compare flesh and Spirit more directly."}}]}, {"number": 4, "title": "Flesh Versus Spirit", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not every desire should be trusted, that''s the key.", "message": "This lesson helps the learner distinguish between the actions of the flesh, the sinful nature which opposes the power of the Spirit of Life. That difference matters in every recovery decision."}}, {"type": "reading", "content": {"title": "Flesh which is the sinful nature pulls toward self-rule and immediate relief, while the Spirit leads toward truth, life, and obedience.", "body": "The flesh is not simply the body. It refers to the sinful nature that resists God and craves satisfaction on its own terms. The Spirit of Life leads differently. The Spirit draws the learner toward truth, humility, surrender, patience, and peace, which is an entirely different life force. With drug abuse and addiction, the flesh often deeply craves satisfaction and confuses the mind to let the person act on these sinful desires. The Spirit of Life desires freedom from drug abuse, teaching restraint, showing trust, and alignment with God. Learning this difference helps the person practice and build onto principles that bring back true life into the person. Drug abuse sucks the life from the person, but the Spirit of Life in Christ Jesus restores the person by depositing life into the body, soul and spirit.  Galatians 5:16-17  I say then: Walk in the Spirit, and you shall not fulfill the lust of the flesh. For the flesh lusts against the Spirit, and the Spirit against the flesh, these are contrary to one another, so that you do not do the things that you wish."}}, {"type": "mentor_note", "content": {"note": "There is a war between the desires of the flesh and the Spirit of God that gives life."}}, {"type": "video", "content": {"title": "Flesh Versus Spirit", "description": "A mentor-led comparison of the flesh and the Spirit, and how they produce different directions in recovery."}}, {"type": "pause_reflect", "content": {"question": "What signs usually tell you that the flesh is trying to control?", "context": "Think about subtleties, timing, desires, emotional pressure, and the kind of outcome being promised."}}, {"type": "journal_prompt", "content": {"prompt": "Write down the difference between how the flesh speaks to you and how the Spirit leads you."}}, {"type": "mood_checkin", "content": {"question": "How discerning do you feel about your inner impulses today?"}}, {"type": "daily_action", "content": {"title": "Test the impulse", "action": "Before acting on one strong impulse today, ask whether it points toward self-rule or Spirit-led obedience."}}, {"type": "mentor_note", "content": {"note": "A wise life is built by learning the source of the voice, and acting upon the Truth."}}, {"type": "quiz", "content": {"question": "How does the flesh operate in this lesson?", "options": [{"text": "Toward self-rule and immediate relief", "is_correct": true}, {"text": "Toward steady truth", "is_correct": false}, {"text": "Toward humility by default", "is_correct": false}, {"text": "Toward patient obedience", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Every strong feeling should be trusted.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does this lesson train the learner to do?", "options": [{"text": "Follow intensity", "is_correct": false}, {"text": "Discern the source and direction of inner impulses", "is_correct": true}, {"text": "Avoid all reflection", "is_correct": false}, {"text": "Reject obedience", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You now have a sharper contrast between flesh and Spirit. In the next lesson, we will look at daily choices and their consequences."}}]}, {"number": 5, "title": "Daily Choices and Consequences", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Small daily choices are often where larger outcomes are quietly decided.", "message": "Recovery is not only shaped by dramatic or drastic moments. It is built by repeated daily choices that either strengthen life or reinforce bondage."}}, {"type": "reading", "content": {"title": "Consequences usually grow from repeated choices, not isolated moments alone.", "body": "Every day includes decisions about our thoughts, principles, life, boundaries, voice, relationships, and response. These choices are not neutral. They carry consequences and outcomes that often accumulate slowly before they become obvious. A learner may want freedom while still protecting their habits. This lesson emphasizes that daily choices are the practical space where deeper spiritual realities become visible. The human laws that govern normal life, daily desires, truth, and obedience all show up in ordinary decisions. Recovery becomes more stable when the learner respects the power of smaller choices and faithfulness.  Proverbs 3:5-8  Trust in the Lord with all your heart, And lean not on your own understanding;  In all your ways acknowledge Him, And He shall direct your paths.  Do not be wise in your own eyes; Fear the Lord and depart from evil. It will be health to your flesh, and strength to your bones."}}, {"type": "mentor_note", "content": {"note": "What you repeat quietly will eventually shape what you become publicly. Repeat life giving hope."}}, {"type": "video", "content": {"title": "Daily Choices and Consequences", "description": "A mentor-led lesson on how everyday decisions strengthen either bondage or recovery."}}, {"type": "pause_reflect", "content": {"question": "Which daily choice has the biggest long-term effect on your recovery right now?", "context": "Consider small patterns that either feed clarity and obedience or keep weakening them."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one daily choice that needs to change if you want a different long-term outcome."}}, {"type": "mood_checkin", "content": {"question": "How intentional do your daily choices feel today?"}}, {"type": "daily_action", "content": {"title": "Choose one faithful pattern", "action": "Pick one small daily behavior today that supports truth and recovery, and commit to repeating it."}}, {"type": "mentor_note", "content": {"note": "Large freedom is often built through small obedience."}}, {"type": "quiz", "content": {"question": "What does this lesson emphasize about consequences?", "options": [{"text": "They only come from dramatic failures", "is_correct": false}, {"text": "They often grow from small repeated decisions", "is_correct": true}, {"text": "They never affect recovery", "is_correct": false}, {"text": "They are always immediate", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Ordinary decisions are spiritually significant.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens stability in recovery here?", "options": [{"text": "Ignoring small habits", "is_correct": false}, {"text": "Respecting the power of small faithfulness", "is_correct": true}, {"text": "Waiting for dramatic change", "is_correct": false}, {"text": "Avoiding routines", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have focused on the weight of daily choices. In the next lesson, we will turn to walking in obedience."}}]}, {"number": 6, "title": "Walking in Obedience", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Obedience is not punishment. It is the path that aligns life and truth.", "message": "This lesson helps the learner see obedience as part of a responsible life, a means to walk in agreement with God''s Word and continue to build life."}}, {"type": "reading", "content": {"title": "Obedience gives structure to recovery by turning truth into action.", "body": "Many people can understand truth in theory but do not translate it into consistent action. Walking in obedience means responding to what is truthful with practical submission. It includes honest confession, changed patterns, guarded inputs, better boundaries, corrected priorities, and steady surrender. With drug abuse and addiction, disobedience often hides beneath rationalization. The person wants freedom while still negotiating with what keeps them bound. Obedience closes that gap. Obedience is very important, as it allows His grace into life. Recovery becomes more grounded when truth is obeyed, not merely admired.  James 1:22  But be doers of the Word, and not hearers only.  Luke 11:28  But He said, “More than that, blessed are those who hear the word of God and obey it!”  Romans 6:16 Do you not know that to whom you present yourselves slaves to obey, you are that one’s slaves whom you obey, whether of sin leading to death, or of obedience leading to righteousness?"}}, {"type": "mentor_note", "content": {"note": "Truth becomes stronger in the life that obeys and practices it."}}, {"type": "video", "content": {"title": "Walking in Obedience", "description": "A mentor-led lesson on turning known truth into concrete action and daily recovery structure."}}, {"type": "pause_reflect", "content": {"question": "Where is there a gap between what you know and what you are practicing?", "context": "Look for one place where you agree with the truth in principle but have not yet walked it out consistently."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where obedience needs to become more concrete in your recovery."}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to obey what you already know today?"}}, {"type": "daily_action", "content": {"title": "Turn truth into practice", "action": "Take one truth you already know and attach one visible action to it today."}}, {"type": "mentor_note", "content": {"note": "Lasting change usually requires more than agreement. It requires alignment."}}, {"type": "quiz", "content": {"question": "What does obedience do in this lesson?", "options": [{"text": "Turns truth into action", "is_correct": true}, {"text": "Replaces grace", "is_correct": false}, {"text": "Makes recovery effortless", "is_correct": false}, {"text": "Eliminates all weakness", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A person can admire truth without obeying it.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is obedience important in addiction recovery?", "options": [{"text": "It closes the gap between knowing and practicing truth", "is_correct": true}, {"text": "It removes the need for honesty", "is_correct": false}, {"text": "It allows negotiation with bondage", "is_correct": false}, {"text": "It avoids daily structure", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have connected truth with practical obedience. In the final lesson, we will look at living under God''s grace."}}]}, {"number": 7, "title": "Living Under God''s Grace", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The chapter ends by grounding obedience and recovery in grace, not in self-salvation.", "message": "Grace is not permission to drift. It is the spiritual help and mercy of God that makes real change possible without leaving the learner trapped in condemnation."}}, {"type": "reading", "content": {"title": "Living under grace means depending on God''s Word while continuing to walk in truth and obedience.", "body": "Grace matters because recovery can become distorted in two opposite directions. Some give up because they believe failure has disqualified them. Others excuse compromise because they misuse grace as permission. Godly grace does neither. Grace restores the fallen and the addict, strengthens the weak, and keeps the person moving forward in truth without denying the seriousness of a drug abusive life. It creates humility instead of pride and perseverance instead of despair. Living under God''s grace means refusing both self-condemnation and careless compromise. It means receiving mercy and continuing the walk into freedom.  2 Corinthians 12:9 And He said to me, “My grace is sufficient for you, for My strength is made perfect in weakness."}}, {"type": "mentor_note", "content": {"note": "Grace is the life and power that makes the person rise above anything."}}, {"type": "video", "content": {"title": "Living Under God''s Grace", "description": "A mentor-led conclusion to Chapter 7, showing how grace sustains the learner in truth, obedience, and hope."}}, {"type": "pause_reflect", "content": {"question": "Which distortion are you more vulnerable to: despair or careless compromise?", "context": "Think honestly about whether you tend to collapse under failure or excuse what still needs to change."}}, {"type": "journal_prompt", "content": {"prompt": "Write about how beautiful it would be to live under grace."}}, {"type": "mood_checkin", "content": {"question": "How anchored do you feel in grace today?"}}, {"type": "daily_action", "content": {"title": "Receive mercy and keep walking", "action": "If you feel discouraged today, answer it with grace and one concrete next step instead of retreating into shame."}}, {"type": "mentor_note", "content": {"note": "Grace keeps the person moving forward without pretending the path no longer matters."}}, {"type": "quiz", "content": {"question": "What does grace do in this lesson?", "options": [{"text": "Permits compromise", "is_correct": false}, {"text": "Sustains recovery without condemnation", "is_correct": true}, {"text": "Makes obedience irrelevant", "is_correct": false}, {"text": "Encourages passivity", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Grace and truth belong together in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does living under grace reject?", "options": [{"text": "Both self-condemnation and careless compromise", "is_correct": true}, {"text": "Mercy", "is_correct": false}, {"text": "Hope", "is_correct": false}, {"text": "Perseverance", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "Chapter 7 now gives you a clearer understanding of law, conflict, obedience, and grace. You are ready to continue into the next chapter with stronger inner structure."}}]}]}, {"number": 8, "title": "The Spiritual War", "description": "Chapter 8 helps the learner understand the spiritual war around drug abuse and addiction recovery. It focuses on warfare, the enemy''s strategies, temptation and resistance, strongholds and bondage, the armor of God, victory through Christ, and standing firm in recovery.\n\nThe goal of this chapter is to make the learner more spiritually alert, better equipped, and steadier under pressure as they continue the recovery journey.", "lessons": [{"number": 1, "title": "Understanding Spiritual Warfare", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The recovery journey comprises conflict that is spiritual as well as personal.", "message": "This chapter begins by helping the person understand that the struggle is not only against habits, emotions, or circumstances. There is also a spiritual war that must be understood soberly."}}, {"type": "reading", "content": {"title": "Spiritual warfare means the believer lives in real conflict around truth, temptation, obedience, and identity.", "body": "Spiritual warfare is not theatrical language for dramatic personalities. It is the ongoing reality that there is conflict around what a person believes, desires, obeys, and becomes. In addiction recovery, this war often shows up through lies, temptation, accusation, compromise, fear, and discouragement. The person needs a calm but serious understanding of this conflict. Without it, they may misread repeated pressure as purely personal weakness and fail to prepare appropriately. Understanding warfare helps the person stay alert, humble, and anchored in truth.  2 Corinthians 10:3-6  For though we walk in the flesh, we do not war according to the flesh.  For the weapons of our warfare are not carnal but mighty in God for pulling down strongholds.  Casting down arguments and every high thing that exalts itself against the knowledge, bringing every thought into captivity to the obedience of Christ, and being ready to punish all disobedience when your obedience is fulfilled."}}, {"type": "mentor_note", "content": {"note": "Some battles keep repeating because they are not being discerned correctly."}}, {"type": "video", "content": {"title": "Understanding Spiritual Warfare", "description": "A mentor-led introduction to spiritual warfare and its relevance to Christian recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you felt such pressure that feels like spiritual war?", "context": "Think about repeated lies, temptation patterns, fear, condemnation, or attacks against hope and identity."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one part of your recovery that now looks more like spiritual conflict than simple weakness."}}, {"type": "mood_checkin", "content": {"question": "How spiritually alert do you feel today?"}}, {"type": "daily_action", "content": {"title": "Take the conflict seriously", "action": "Identify one area today where you need to respond with spiritual alertness instead of only frustration."}}, {"type": "mentor_note", "content": {"note": "Alertness grows when the battle is named without exaggeration or denial."}}, {"type": "quiz", "content": {"question": "What is spiritual warfare in this lesson?", "options": [{"text": "An imaginary conflict", "is_correct": false}, {"text": "Real conflict around truth, temptation, obedience, and identity", "is_correct": true}, {"text": "Only emotional pressure", "is_correct": false}, {"text": "A public performance", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery can include spiritual conflict.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is understanding warfare important?", "options": [{"text": "It helps the learner prepare and stay alert", "is_correct": true}, {"text": "It creates panic", "is_correct": false}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It replaces truth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the opening frame for Chapter 8. In the next lesson, we will examine the enemy''s strategies."}}]}, {"number": 2, "title": "The Enemy''s Strategies", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not every attack looks obvious. Many work through strategy, timing, and repetition.", "message": "This lesson helps the person understand how the enemy often works through subtle and repeated methods rather than dramatic events."}}, {"type": "reading", "content": {"title": "The enemy''s strategies often exploit weakness, confusion, secrecy, and exhaustion.", "body": "In recovery, the enemy''s strategies include planting lies, magnifying shame, isolating the person, normalizing compromise, attacking identity, and waiting for moments of fatigue or discouragement. The point is not to become preoccupied with darkness, but to become wise about how pressure and attacks operate. Strategy matters because many fallen incidents do not begin at the moment of visible failure. They begin earlier in thought patterns, unmanaged compromise, ignored boundaries, and unchallenged lies. Discernment helps expose the setup before the collapse becomes visible.  1 Peter 5:8  Be sober, be vigilant; because your adversary the devil walks about like a roaring lion, seeking whom he may devour.  2 Corinthians 2:11  lest Satan should take advantage of us, for we are not ignorant of his devices."}}, {"type": "mentor_note", "content": {"note": "Many defeats are prepared long before they are acted out."}}, {"type": "video", "content": {"title": "The Enemy''s Strategies", "description": "A mentor-led lesson on recognizing spiritual strategies that exploit weakness and destabilize recovery."}}, {"type": "pause_reflect", "content": {"question": "Which strategy of the evil one seems to affect you most often: lies, isolation, shame, fatigue, or compromise?", "context": "Look for patterns that repeatedly set you up before visible failure happens."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one strategy that has kept reappearing in your life and how you can identify it earlier."}}, {"type": "mood_checkin", "content": {"question": "How discerning do you feel about patterns of attack today?"}}, {"type": "daily_action", "content": {"title": "Spot the setup", "action": "Watch today for the early setup of temptation, not only the final moment of pressure."}}, {"type": "mentor_note", "content": {"note": "Discernment often saves a person earlier than willpower can."}}, {"type": "quiz", "content": {"question": "What does this lesson emphasize about the enemy''s work?", "options": [{"text": "It is always obvious", "is_correct": false}, {"text": "It often uses subtle and repeated strategy", "is_correct": true}, {"text": "It never targets weakness", "is_correct": false}, {"text": "It only appears in major crises", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Visible failure is often prepared earlier by smaller compromises.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps the learner here?", "options": [{"text": "Discernment about the setup", "is_correct": true}, {"text": "More denial", "is_correct": false}, {"text": "Less honesty", "is_correct": false}, {"text": "Ignoring patterns", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have looked at strategy more clearly. In the next lesson, we will focus on temptation and resistance."}}]}, {"number": 3, "title": "Temptation and Resistance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Temptation is real, but can be resisted.", "message": "This lesson helps the person treat temptation seriously without surrendering to it as though resistance is impossible."}}, {"type": "reading", "content": {"title": "Resistance becomes effective when temptation is understood and responded to decisively.", "body": "Temptation often begins in subtle ways without sometimes grasping the magnitude of the temptation itself. It may start as a suggestion, an image, a memory, a rationalization, or a quiet inner permission. If it is allowed to be entertained unchallenged, it often gains strength of force. Resistance is not the denial that temptation exists. It is the decision to interrupt its power by creating boundaries, through prayer, transformed perception, honesty and truth. The earlier a regular temptation is recognized, the more strength the person usually has to resist it. Delayed resistance often becomes weaker resistance.  James 4:7  Therefore submit to God. Resist the devil and he will flee from you. James 1:14-16  But each one is tempted when he is drawn away by his own desires and enticed.  Then, when desire has conceived, it gives birth to sin; when it is full-grown, brings forth death.  Do not be deceived, my beloved brethren."}}, {"type": "mentor_note", "content": {"note": "The temptation must be recognized, called for what it is and attempt to resist it."}}, {"type": "video", "content": {"title": "Temptation and Resistance", "description": "A mentor-led lesson on how temptation grows and how resistance becomes more effective when it is early and concrete."}}, {"type": "pause_reflect", "content": {"question": "At what stage do you usually take temptation seriously: early, late, or only after you have already been affected by it?", "context": "Consider whether you respond to temptation as soon as it begins or only after it has gained momentum."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one way you can respond earlier and more decisively to temptation."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to resist temptation today?"}}, {"type": "daily_action", "content": {"title": "Interrupt temptation early", "action": "As soon as a tempting thought appears today, interrupt it with one concrete truth or change of direction."}}, {"type": "mentor_note", "content": {"note": "Early resistance is often one of the most practical forms of wisdom."}}, {"type": "quiz", "content": {"question": "What does this lesson teach about resistance?", "options": [{"text": "It is impossible", "is_correct": false}, {"text": "It grows stronger when temptation is recognized early", "is_correct": true}, {"text": "It only matters after failure", "is_correct": false}, {"text": "It replaces boundaries", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Delayed resistance often becomes weaker resistance.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What should the person do with temptation?", "options": [{"text": "Entertain it quietly", "is_correct": false}, {"text": "resist it with truth and action", "is_correct": true}, {"text": "Ignore it completely", "is_correct": false}, {"text": "Let it grow before responding", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have tied temptation to practical resistance. In the next lesson, we will look at strongholds and bondage."}}]}, {"number": 4, "title": "Strongholds and Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some patterns are not only habits. They become fortified places in the inner life.", "message": "This lesson helps the person understand how repeated compromise, false beliefs, and unresolved pain and situations can build strongholds that deepen bondage."}}, {"type": "reading", "content": {"title": "Strongholds form where lies, patterns, and agreements are reinforced over time.", "body": "A stronghold is not simply a bad day or a single wrong choice. It is a reinforced pattern, a natural habit in the mind and life where falsehood, compromise, and repeated surrender have gained depth. With drug abuse and addiction, addiction to drugs is in itself a powerful stronghold. Other types of strongholds could be for example sexual lust, deep anger, violence and so forth. These types of strongholds would have developed for years and have dug its roots into the soul of the person. Recovery requires more than behavior interruption. It also requires dismantling the beliefs, permissions, and hidden agreements that these strongholds have. It requires a warrior spirit to stand against these strongholds to even begin dismantling it.  2 Corinthians 10:4  For the weapons of our warfare are not carnal but mighty in God for pulling down strongholds."}}, {"type": "mentor_note", "content": {"note": "What is reinforced repeatedly, eventually can become a stronghold."}}, {"type": "video", "content": {"title": "Strongholds and Bondage", "description": "A mentor-led lesson on how strongholds form and why they must be dismantled, not merely managed."}}, {"type": "pause_reflect", "content": {"question": "What stronghold do you think has had the deepest hold on you?", "context": "Think about entrenched lies, repeated patterns, and the inner agreements that kept the cycle protected."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one stronghold that needs to be confronted not only in behavior, but also in belief and agreement."}}, {"type": "mood_checkin", "content": {"question": "How stuck or free do you feel in your inner life today?"}}, {"type": "daily_action", "content": {"title": "Name the fortified place", "action": "Identify one place today where the struggle feels reinforced, and write down what false agreement may be strengthening it."}}, {"type": "mentor_note", "content": {"note": "Bondage grows strongest where it remains unnamed and defended."}}, {"type": "quiz", "content": {"question": "What is a stronghold in this lesson?", "options": [{"text": "A passing feeling", "is_correct": false}, {"text": "A reinforced life habit of falsehood and compromise", "is_correct": true}, {"text": "A healthy discipline", "is_correct": false}, {"text": "Only an external problem", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery requires dismantling hidden agreements, not only interrupting behavior.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is this lesson important?", "options": [{"text": "It helps the person identify deeper bondage honestly", "is_correct": true}, {"text": "It avoids real causes", "is_correct": false}, {"text": "It removes truth", "is_correct": false}, {"text": "It makes patterns less serious", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have looked at strongholds more directly. In the next lesson, we will focus on the armor of God."}}]}, {"number": 5, "title": "The Armor of God", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Spiritual warfare requires spiritual adaptation.", "message": "This lesson gives the person a framework for standing ready rather than reacting only after being overcome with sin."}}, {"type": "reading", "content": {"title": "The armor of God describes a life equipped by truth, righteousness, readiness, faith, salvation, and the Word of God.", "body": "The armor of God is not a slogan for difficult days. It is a picture of how the believer is meant to stand. Truth shapes the mind. Righteousness guards the heart from compromise. Readiness keeps the person prepared to move in peace. Faith protects against destructive accusation and lies. Salvation strengthens identity and assurance. The Word of God is the sword that cuts through all forms of life to the obedience of God, and in the person''s life. Recovery becomes purpose driven, believing in Truth, strengthened by courage and power.  Ephesians 6:11-13  Put on the whole armor of God, that you may be able to stand against the wiles of the devil.  For we do not wrestle against flesh n blood, but against principalities, against powers, against rulers of the darkness of this age, against spiritual hosts of wickedness in the heavenly places.  Therefore take up the whole armor of God, that you may be able to withstand in the evil day, and having done all, to stand."}}, {"type": "mentor_note", "content": {"note": "The battle is handled better by the person who is trained for battle against sin."}}, {"type": "video", "content": {"title": "The Armor of God", "description": "A mentor-led lesson on the armor of God and how it gives structure to spiritual readiness in recovery."}}, {"type": "pause_reflect", "content": {"question": "Which part of your spiritual life feels weakest right now?", "context": "Think about truth, faith, readiness, identity, or your practical use of Scripture."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one piece of spiritual preparation you need to strengthen in a practical way."}}, {"type": "mood_checkin", "content": {"question": "How equipped do you feel for spiritual pressure today?"}}, {"type": "daily_action", "content": {"title": "Strengthen one point of readiness", "action": "Pick one element of spiritual preparation today and strengthen it with one concrete action."}}, {"type": "mentor_note", "content": {"note": "Preparation is one form of obedience to the reality of battle."}}, {"type": "quiz", "content": {"question": "What does the armor of God represent in this lesson?", "options": [{"text": "A symbolic but impractical idea", "is_correct": false}, {"text": "A life equipped by truth, faith, righteousness, and the Word", "is_correct": true}, {"text": "Only emotional strength", "is_correct": false}, {"text": "Only crisis reaction", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Preparation should be daily, not only emergency-based.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is this lesson useful in recovery?", "options": [{"text": "It helps the person stand equipped before pressure rises", "is_correct": true}, {"text": "It removes discipline", "is_correct": false}, {"text": "It replaces truth with symbolism", "is_correct": false}, {"text": "It keeps the learner passive", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have looked at spiritual preparation more concretely. In the next lesson, we will focus on victory through Christ."}}]}, {"number": 6, "title": "Victory Through Christ", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Victory is not self-generated. It is walked in and through Christ.", "message": "This lesson helps the person understand that victory is grounded in Christ''s power and work, not in personal strength in all."}}, {"type": "reading", "content": {"title": "Victory through Christ means the person fights from dependence on Him.", "body": "Many people approach recovery with a hidden belief that if they fail, it proves they were never strong enough. That belief keeps the focus on the self. Victory through Christ redirects the focus. The person stands not in self-sufficiency, but in dependence on the One who has overcome sin, death, and condemnation. This does not make effort unnecessary. It changes the source where strength and wisdom comes from. Instead of trying to manufacture freedom by willpower alone, the person begins to lean into Christ''s strength, truth, and sustaining presence.  1 Corinthians 15:57  But thanks be to God, who gives us the victory through our Lord Jesus Christ.  Romans 8:37  Yet in all these things we are more than conquerors through Him who loved us."}}, {"type": "mentor_note", "content": {"note": "Victory becomes definitive when confidence shifts from self to Christ."}}, {"type": "video", "content": {"title": "Victory Through Christ", "description": "A mentor-led lesson on why Christian victory is grounded in Christ''s strength rather than self-sufficiency."}}, {"type": "pause_reflect", "content": {"question": "Where do you still act as though victory depends only on your own strength?", "context": "Consider the places where failure still feels like proof that everything rests on your performance."}}, {"type": "journal_prompt", "content": {"prompt": "Write about what it would mean for you to depend more consciously on Christ in the middle of struggle."}}, {"type": "mood_checkin", "content": {"question": "How dependent on Christ do you feel today?"}}, {"type": "daily_action", "content": {"title": "Shift your confidence", "action": "When pressure comes today, answer it by consciously leaning on Christ instead of only trying to force your way through it."}}, {"type": "mentor_note", "content": {"note": "The strongest confidence is often the one that has stopped pretending it is self-made."}}, {"type": "quiz", "content": {"question": "What does victory through Christ mean in this lesson?", "options": [{"text": "Victory through self-sufficiency", "is_correct": false}, {"text": "Victory through dependence on Christ", "is_correct": true}, {"text": "Victory without effort", "is_correct": false}, {"text": "Victory through denial", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: This lesson removes all need for effort.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What changes when confidence shifts to Christ?", "options": [{"text": "Victory becomes steadier and less self-driven", "is_correct": true}, {"text": "Truth becomes weaker", "is_correct": false}, {"text": "Responsibility disappears", "is_correct": false}, {"text": "Discipline no longer matters", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have looked at victory more accurately. In the final lesson, we will focus on standing firm in recovery."}}]}, {"number": 7, "title": "Standing Firm in Recovery", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The chapter ends with the call not only to fight, but to remain standing.", "message": "Standing firm means staying steady in truth, boundaries, dependence, and obedience even when pressure does not disappear immediately."}}, {"type": "reading", "content": {"title": "Recovery is strengthened by standing in Truth.", "body": "Some people think standing firm means never feeling weakness. In reality, it means remaining anchored and refusing to surrender ground when temptation, lies, fatigue, or discouragement return. Standing firm requires boundaries, ongoing truth, prayer, alertness, humility, and perseverance. It does always appear like sudden victory, but often more important overall strength in the person. A stable recovery is built when the person keeps standing grounded instead of repeatedly drifting back into compromise.  Isaiah 41:10  Fear not, for I am with you; Be not dismayed, for I am your God. I will strengthen you, Yes, I will help you, I will uphold you with My righteous right hand."}}, {"type": "mentor_note", "content": {"note": "Many battles are won not by speed, but by steadiness and consistency."}}, {"type": "video", "content": {"title": "Standing Firm in Recovery", "description": "A mentor-led conclusion to Chapter 9, showing how spiritual steadiness protects long-term recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you most need consistency right now?", "context": "Think about the area where you are most vulnerable to drift, compromise, fatigue, or discouragement."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one practical way you can stand firmer in your recovery this week."}}, {"type": "mood_checkin", "content": {"question": "How steady do you feel in recovery today?"}}, {"type": "daily_action", "content": {"title": "Hold your ground", "action": "Choose one boundary or truth today that you will hold firmly instead of negotiating with it."}}, {"type": "mentor_note", "content": {"note": "Consistency is one of the quiet strengths that protects long-term freedom."}}, {"type": "quiz", "content": {"question": "What does standing firm mean in this lesson?", "options": [{"text": "Never feeling weak", "is_correct": false}, {"text": "Remaining anchored in truth and obedience under pressure", "is_correct": true}, {"text": "Avoiding all conflict", "is_correct": false}, {"text": "Only waiting for dramatic breakthrough", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Long-term recovery often depends on steadiness.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does this lesson emphasize most?", "options": [{"text": "Persevering stability under pressure", "is_correct": true}, {"text": "Fast emotional change only", "is_correct": false}, {"text": "Removing all effort", "is_correct": false}, {"text": "Ignoring boundaries", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "Chapter 8 is complete. You are ready to continue into the next chapter with a stronger understanding of the battle around the mind."}}]}]}, {"number": 9, "title": "The Mind Battlefield", "description": "Chapter 9 focuses on the inner battle of thought processes, interpretation, emotions, and mental renewal. It guides the person through renewing the mind, naming harmful patterns, taking thoughts captive, answering cravings with truth, replacing lies with Scripture, building godly thinking, emotional maturity, and long-term stability.\n\nThe goal of this chapter is to help the person become more disciplined, truthful, emotionally steady, and mentally renewed in a way that supports lasting recovery.", "lessons": [{"number": 1, "title": "Renewing the Mind", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery deepens when the mind is renewed, not only restrained.", "message": "This chapter begins by treating the mind as a battlefield where recovery is either strengthened or weakened."}}, {"type": "reading", "content": {"title": "Renewal of the mind changes the way the person interprets life.", "body": "Renewing the mind means replacing old assumptions and ways, lies, distorted perceptions, and self-defeating interpretations with truth shaped by His Word. Drug abuse and addiction often forces the person toward escape, cravings, shame, and hopelessness the more the person loses control over drug abuse. Renewal is the gradual process by which thought patterns are retrained and restructured. It is not instant, but is the only progress.  Romans 12:2  And do not be conformed to this world, but be transformed by the renewing of your mind, that you may prove what is that good and acceptable and perfect will of God."}}, {"type": "mentor_note", "content": {"note": "A renewed life requires a renewed way of thinking."}}, {"type": "video", "content": {"title": "Renewing the Mind", "description": "A mentor-led introduction to mental renewal in Christian recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you most need mental renewal right now?", "context": "Think about identity, cravings, fear, shame, and the way you interpret setbacks."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one recurring thought pattern that needs renewal."}}, {"type": "mood_checkin", "content": {"question": "How clear or cluttered does your mind feel today?"}}, {"type": "daily_action", "content": {"title": "Replace one old pattern", "action": "Catch one recurring thought today and answer it with a truth-based alternative."}}, {"type": "mentor_note", "content": {"note": "Change often becomes durable when thought patterns begin to change."}}, {"type": "quiz", "content": {"question": "What does renewing the mind involve?", "options": [{"text": "Replacing distorted thinking with truth", "is_correct": true}, {"text": "Ignoring thoughts", "is_correct": false}, {"text": "Only managing behavior", "is_correct": false}, {"text": "Avoiding reflection", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Renewal is essential in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does renewal matter?", "options": [{"text": "It retrains how life is interpreted", "is_correct": true}, {"text": "It removes all effort", "is_correct": false}, {"text": "It makes truth optional", "is_correct": false}, {"text": "It replaces discipline", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the starting point for Chapter 9. In the next lesson, we will identify harmful thought patterns."}}]}, {"number": 2, "title": "Identifying Harmful Thought Patterns", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "You cannot correct what you do not first identify.", "message": "This lesson helps the learner recognize thought patterns that quietly support bondage."}}, {"type": "reading", "content": {"title": "Harmful thought patterns often normalize incorrect living, shame, entitlement, exaggeration, and self-deception.", "body": "Some patterns feel normal because they have been repeated for years, and embedded in the mind and soul. When there are harmful thought patterns like in the case of drug and substance abuse, with heavy addiction there might be hopelessness in the mind, self-pity, entitlement, minimization, and mental escape routes. Addiction often survives where harmful thought patterns are left unchallenged, and these mental strongholds are very challenging for the person. Identifying them and being honest about these mental strongholds and thought patterns is only the beginning of the battle."}}, {"type": "mentor_note", "content": {"note": "A repeated thought can become a trusted lie if it is never challenged."}}, {"type": "video", "content": {"title": "Identifying Harmful Thought Patterns", "description": "A mentor-led lesson on naming damaging mental patterns early and honestly."}}, {"type": "pause_reflect", "content": {"question": "Which harmful thought pattern seems strongest in you?", "context": "Think about exaggeration, denial, entitlement, shame, or hopeless conclusions."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one harmful thought pattern and how it has influenced your choices."}}, {"type": "mood_checkin", "content": {"question": "How mentally aware do you feel today?"}}, {"type": "daily_action", "content": {"title": "Name the pattern", "action": "When a harmful pattern appears today, label it clearly instead of letting it stay vague."}}, {"type": "mentor_note", "content": {"note": "Naming a pattern weakens the power it holds in silence."}}, {"type": "quiz", "content": {"question": "What is the main task in this lesson?", "options": [{"text": "Identify damaging mental patterns", "is_correct": true}, {"text": "Ignore thoughts", "is_correct": false}, {"text": "Only track behavior", "is_correct": false}, {"text": "Avoid honesty", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Harmful thoughts can quietly sustain bondage.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is identification important?", "options": [{"text": "It prepares thoughts to be challenged", "is_correct": true}, {"text": "It ends all struggle instantly", "is_correct": false}, {"text": "It replaces truth", "is_correct": false}, {"text": "It removes responsibility", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have named harmful thought patterns more clearly. In the next lesson, we will focus on taking thoughts captive."}}]}, {"number": 3, "title": "Taking Thoughts Captive", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not every thought deserves agreement.", "message": "This lesson helps the person move from passive mental acceptance to active mental stewardship."}}, {"type": "reading", "content": {"title": "Taking thoughts captive means testing them instead of automatically trusting them.", "body": "Many people assume that because a thought appeared, it must be meaningful, accurate, or worth following. This lesson rejects that assumption. Taking thoughts captive means taking hold of that thought, idea, ideology to examine it, compare them with truth, and refuse agreement where they contradict what God says. The learner becomes less passive and more responsible in the mental battle.  2 Corinthians 10:4-5  For the weapons of our warfare are not carnal but mighty in God for pulling down strongholds, Casting down arguments and every high thing that exalts itself against the knowledge of God, bringing every thought into captivity to the obedience of Christ."}}, {"type": "mentor_note", "content": {"note": "A thought gains power when it is believed without examination."}}, {"type": "video", "content": {"title": "Taking Thoughts Captive", "description": "A mentor-led lesson on actively testing and redirecting thoughts."}}, {"type": "pause_reflect", "content": {"question": "What kind of thought do you most often accept without testing?", "context": "Think about condemning thoughts, craving thoughts, fearful thoughts, or self-justifying thoughts."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one recent thought you should have examined more carefully."}}, {"type": "mood_checkin", "content": {"question": "How mentally guarded do you feel today?"}}, {"type": "daily_action", "content": {"title": "Test the thought", "action": "Before agreeing with one strong thought today, pause and test it against truth."}}, {"type": "mentor_note", "content": {"note": "Stewarded thoughts build stronger lives than unchecked ones."}}, {"type": "quiz", "content": {"question": "What does taking thoughts captive mean?", "options": [{"text": "Testing thoughts against truth", "is_correct": true}, {"text": "Believing every thought", "is_correct": false}, {"text": "Avoiding reflection", "is_correct": false}, {"text": "Only controlling speech", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Thoughts should be examined before agreement.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What changes when thoughts are controlled?", "options": [{"text": "The person becomes less passive and more responsible", "is_correct": true}, {"text": "Truth becomes unnecessary", "is_correct": false}, {"text": "Shame becomes stronger", "is_correct": false}, {"text": "Temptation disappears forever", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have looked at active mental stewardship. In the next lesson, we will focus on cravings and truth."}}]}, {"number": 4, "title": "Managing Cravings Through Truth", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Cravings feel powerful, but they do not get final authority.", "message": "This lesson helps the person respond to cravings with the truth of His Word rather than panic, surrender, or fantasy."}}, {"type": "reading", "content": {"title": "Cravings become less dominant when they are interpreted truthfully and answered concretely.", "body": "Cravings often carry urgency and demand. It tries to make the person feel that relief is necessary now, it''s a devastating urge to take drugs to calm the craving. When the person leans on God, it interrupts that pressure by reminding the person that cravings are real but temporary, strong but not sovereign, persuasive but not trustworthy. Managing cravings through truth means combining right interpretation with practical response: pause, pray, rethink, and refuse false conclusions.  Philippians 4:6-7  Be anxious for nothing, but in everything by prayer and supplication, with thanksgiving, let your requests be made known to God;  and the peace of God, which surpasses all understanding, will guard your hearts and minds through Christ Jesus. Meditate on these things."}}, {"type": "mentor_note", "content": {"note": "A craving becomes more dangerous when it''s in full control of the mind, the person thinks of nothing else."}}, {"type": "video", "content": {"title": "Managing Cravings Through Truth", "description": "A mentor-led lesson on interpreting cravings correctly and responding with truth."}}, {"type": "pause_reflect", "content": {"question": "How do you usually interpret cravings when they rise?", "context": "Do you treat them like its in full control, a crisis, or instead something that can be answered with truth?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down one truth statement that helps you answer cravings more clearly."}}, {"type": "mood_checkin", "content": {"question": "How intense do cravings feel for you today?"}}, {"type": "daily_action", "content": {"title": "Answer the urge", "action": "When a craving rises today, respond with one prepared truth statement and one practical redirect."}}, {"type": "mentor_note", "content": {"note": "The craving may be strong, but truth can still lead the response."}}, {"type": "quiz", "content": {"question": "What does this lesson teach about cravings?", "options": [{"text": "They are final authority", "is_correct": false}, {"text": "They can be answered with truth", "is_correct": true}, {"text": "They should be worshipped", "is_correct": false}, {"text": "They remove choice", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Cravings are intense and controlling.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps here?", "options": [{"text": "Truth plus practical response", "is_correct": true}, {"text": "Panic", "is_correct": false}, {"text": "Silence", "is_correct": false}, {"text": "Fantasy", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have connected cravings with truth-based response. In the next lesson, we will replace lies with Scripture."}}]}, {"number": 5, "title": "Replacing Lies with Scripture", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lies lose power when answered with specific truth.", "message": "This lesson helps the person stop fighting inner pressure with vague inner hope."}}, {"type": "reading", "content": {"title": "Scripture gives specific truth for specific and all battles.", "body": "General inspiration is often not enough when lies are specific. The person needs truth that speaks directly to what the person feels and going through that''s challenging, whether it''s shame, hopelessness, temptation, condemnation, and identity confusion. Replacing lies with Scripture means learning to recognize the exact lie and answer it with the correct truth. This builds clarity, steadiness, and a more disciplined inner response to life."}}, {"type": "mentor_note", "content": {"note": "Specific lies require specific truth from the Word of God."}}, {"type": "video", "content": {"title": "Replacing Lies with Scripture", "description": "A mentor-led lesson on using Scripture precisely in the mental battle."}}, {"type": "pause_reflect", "content": {"question": "Which lie in your life most needs a direct Word from God?", "context": "Choose one repeated lie and think about the truth that exposes it."}}, {"type": "journal_prompt", "content": {"prompt": "Write one lie and the Scripture-based truth you want to use against it."}}, {"type": "mood_checkin", "content": {"question": "How anchored in Scripture do you feel today?"}}, {"type": "daily_action", "content": {"title": "Prepare the answer", "action": "Choose one lie today and write down the specific truth you will use against it next time."}}, {"type": "mentor_note", "content": {"note": "Truth becomes sharper when it is applied precisely."}}, {"type": "quiz", "content": {"question": "What is the main practice in this lesson?", "options": [{"text": "Answering lies with specific truth", "is_correct": true}, {"text": "Using vague motivation only", "is_correct": false}, {"text": "Ignoring Scripture", "is_correct": false}, {"text": "Avoiding precision", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: General inspiration is always enough.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does specific truth matter?", "options": [{"text": "It answers the actual lie more clearly", "is_correct": true}, {"text": "It increases confusion", "is_correct": false}, {"text": "It removes discipline", "is_correct": false}, {"text": "It weakens focus", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have connected lies with specific Scriptural responses. In the next lesson, we will build Godly thinking."}}]}, {"number": 6, "title": "Building Godly Thinking", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The goal is not only stopping bad thoughts, but building thoughts of purpose.", "message": "This lesson helps the person move from a defensive mentality toward life giving, Godly thinking."}}, {"type": "reading", "content": {"title": "Godly thinking is formed by repeated alignment with His Word, wisdom, knowledge and understanding.", "body": "The person must eventually do more than interrupt lies. They must also build a healthier mentality, thoughts and spiritual life. Godly thinking includes relationship with God, sober living, truthfulness, peace of mind, hope, and outcomes based on faith. It is shaped by repeated choices about what the person meditates on, Godly values, and principles. A stronger inner life grows when Godly thinking becomes a regular devotion."}}, {"type": "mentor_note", "content": {"note": "What is rehearsed inwardly will often be lived outwardly."}}, {"type": "video", "content": {"title": "Building Godly Thinking", "description": "A mentor-led lesson on moving from mental defense to constructive godly thinking."}}, {"type": "pause_reflect", "content": {"question": "What kind of thought life are you trying to build, not only defend?", "context": "Think about what you want your mind to become more consistent in producing."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one godly thought pattern you want to strengthen intentionally."}}, {"type": "mood_checkin", "content": {"question": "How constructive does your inner world feel today?"}}, {"type": "daily_action", "content": {"title": "Rehearse what is true", "action": "Choose one true, healthy thought to repeat and dwell on intentionally today."}}, {"type": "mentor_note", "content": {"note": "A stronger mind is often built by what it learns to dwell on well."}}, {"type": "quiz", "content": {"question": "What does this lesson emphasize?", "options": [{"text": "Building a spiritual mentality", "is_correct": true}, {"text": "Only suppressing thoughts", "is_correct": false}, {"text": "Ignoring truth", "is_correct": false}, {"text": "Avoiding discipline", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A healthy mental life must be built, not only defended.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What shapes Godly thinking?", "options": [{"text": "Repeated alignment with His Word", "is_correct": true}, {"text": "Passive drift", "is_correct": false}, {"text": "Compromise", "is_correct": false}, {"text": "Mental escape", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have looked at constructive Godly thinking. In the next lesson, we will focus on emotional maturity."}}]}, {"number": 7, "title": "Developing Emotional Maturity", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Emotional intensity should not control the whole recovery process.", "message": "This lesson helps the person relate to truthful and healthy emotions without letting it dominate interpretation and decision making that leads towards bad outcomes."}}, {"type": "reading", "content": {"title": "Emotional maturity grows when feelings are acknowledged, interpreted well, and governed by truth.", "body": "Emotions matter, but it does not automatically tell the whole truth. Emotional maturity means the person can feel strongly without surrendering mentally to what leads to bad outcomes. They learn to understand emotions, appreciate emotions, live it properly, and allow themselves to grow into their own character. Drug abuse and addiction often thrives where emotions can become an insane rollercoaster. Recovery grows stronger when emotion is honored without being obeyed blindly.  Proverbs 16:32  He who is slow to anger is better than the mighty, And he who rules his spirit than he who takes a city.  Galatians 5: 22-26  But the fruit of the Spirit is love, joy, peace, longsuffering, kindness, goodness, faithfulness, gentleness, self-control.  Against such there is no law.  And those who are Christ’s have crucified the flesh with its passions and desires.  If we live in the Spirit, let us also walk in the Spirit.  Let us not become conceited, provoking one another, envying one another"}}, {"type": "mentor_note", "content": {"note": "Maturity does not deny emotion. It appreciates it wisely."}}, {"type": "video", "content": {"title": "Developing Emotional Maturity", "description": "A mentor-led lesson on emotional honesty, steadiness, and truth-based response."}}, {"type": "pause_reflect", "content": {"question": "Which emotion most often disrupts your clarity?", "context": "Think about fear, shame, anger, loneliness, or discouragement."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one emotion that needs wiser interpretation in your recovery."}}, {"type": "mood_checkin", "content": {"question": "How emotionally steady do you feel today?"}}, {"type": "daily_action", "content": {"title": "Slow the feeling", "action": "When a strong heightened emotion rises today, take time to understand before acting upon it."}}, {"type": "mentor_note", "content": {"note": "A steadier life is often built by learning to slow emotion under truth."}}, {"type": "quiz", "content": {"question": "What is emotional maturity in this lesson?", "options": [{"text": "Ignoring feelings", "is_correct": false}, {"text": "Acknowledging feelings and appreciating diversity", "is_correct": true}, {"text": "Following every emotion", "is_correct": false}, {"text": "Avoiding honesty", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Uncontrolled emotion should not automatically rule recovery decisions.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this matter in addiction recovery?", "options": [{"text": "Because emotion can become ruler instead of signal", "is_correct": true}, {"text": "Because feelings never matter", "is_correct": false}, {"text": "Because truth is optional", "is_correct": false}, {"text": "Because maturity removes emotion", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You have connected emotional maturity with recovery steadiness. In the final lesson, we will focus on long-term freedom and stability."}}]}, {"number": 8, "title": "Long-Term Freedom and Stability", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This chapter ends by looking beyond short-term progress to indefinite freedom.", "message": "The goal is not only surviving today. It is building the mental and spiritual stability that supports complete freedom."}}, {"type": "reading", "content": {"title": "Long-term stability is built through repeated accepting of the Word of God to maturity.", "body": "Short-term progress matters, but recovery becomes powerful when it is stabilized by habits of His Word, renewed thinking, emotional maturity, healthy rhythms, and ongoing dependence on God. The person must stop treating freedom like a moment and start treating it like a way of life with continuous transformation. Stability is built slowly, but it is built intentionally.  Proverbs 18:10  The name of the Lord is a strong tower;  The righteous run to it and they are safe.  Proverb 24:5-6  A wise man is strong, Yes, a man of knowledge increases strength;  For by wise counsel you will wage your own war, And in a multitude of counselors there is safety."}}, {"type": "mentor_note", "content": {"note": "Lasting freedom is usually the fruit of repeated faithfulness."}}, {"type": "video", "content": {"title": "Long-Term Freedom and Stability", "description": "A mentor-led conclusion to Chapter 10 on building durable mental and spiritual stability."}}, {"type": "pause_reflect", "content": {"question": "What do you still need in order to become more stable over the long term?", "context": "Think about habits, truth, rhythms, emotional steadiness, accountability, and dependence on God."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one practical change that would strengthen long-term stability in your life."}}, {"type": "mood_checkin", "content": {"question": "How stable does your recovery feel today?"}}, {"type": "daily_action", "content": {"title": "Support the future", "action": "Choose one action today that strengthens the future stability of your recovery, not only immediate relief."}}, {"type": "mentor_note", "content": {"note": "Freedom becomes durable where it is supported by others."}}, {"type": "quiz", "content": {"question": "What does complete freedom require here?", "options": [{"text": "Intentional support and absolute faithfulness to God", "is_correct": true}, {"text": "Only short-term emotion", "is_correct": false}, {"text": "No structure", "is_correct": false}, {"text": "No discipline", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Stability is built slowly and intentionally.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is the main closing emphasis of this chapter?", "options": [{"text": "Durable freedom through repeated faithfulness", "is_correct": true}, {"text": "Quick fixes", "is_correct": false}, {"text": "Passive hope", "is_correct": false}, {"text": "Ignoring the mind", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "Chapter 9 is complete. You are ready to continue into Chapter 10 with a deeper focus on salvation, power and grace of The Tree of Life."}}]}]}, {"number": 10, "title": "The Tree of Life", "description": "Chapter 10 turns the person toward restored life in Christ. It focuses on Christ as the source of life, returning to God''s design, the gift of salvation, receiving grace, spiritual growth, fruitful living, and walking in newness of life.\n\nThe goal of this chapter is to help the person move beyond defensive recovery into a life that is rooted in Christ, shaped by grace, and visible through growth and fruit.", "lessons": [{"number": 1, "title": "Christ as the Source of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The answer to death and bondage is not only restraint, but life from the right source.", "message": "This chapter turns from conflict and law toward the source of true restoration. It begins by placing Christ at the center as the Creator and source of life."}}, {"type": "reading", "content": {"title": "Life cannot be restored by the old worldly system. It must come from Christ.", "body": "Drug abuse and addiction drains life, narrows vision, and weakens the inner person. The Tree of Life points the person back to God''s intended source of spiritual nourishment, divine purpose and meaningful relationship with Him. For the person, that source is fulfilled by Christ Jesus. Christ is not merely an example of better behavior. He is the One through whom new life is created, sustained, a fruitful life and eternal freedom. Recovery becomes shallow when Christ is treated as an optional spiritual support. True spiritual life becomes meaningful and deeper when He is fully acknowledged and understood as the source from whom life itself comes for newness of life.  John 14:6  Jesus said to him, “I am the Way, the Truth, and the Life. No one comes to the Father except through me.  John 1:3-4  All things were made through Him and without Him nothing was made that was made. In Him was life, and the life was the light of men."}}, {"type": "mentor_note", "content": {"note": "The deepest hunger cannot be healed by substitutes."}}, {"type": "video", "content": {"title": "Jesus Christ as the Source of Life", "description": "A mentor-led lesson on why Christ is not an accessory to recovery, but the source of restored life."}}, {"type": "pause_reflect", "content": {"question": "In what ways have you looked for life from sources that could not truly sustain you?", "context": "Consider drug abuse itself, other drug abusers, false religions, and any other place you tried to find what only God could give."}}, {"type": "journal_prompt", "content": {"prompt": "Write about what it means to treat Christ as the source of life instead of treating Him as a last resort."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to the true source of life today?"}}, {"type": "daily_action", "content": {"title": "Return to the right source", "action": "Pause today and name one false source you must stop leaning on so your dependence can be redirected toward Christ."}}, {"type": "mentor_note", "content": {"note": "What feeds life matters more than anything that appears true but leads to death."}}, {"type": "quiz", "content": {"question": "What is the main focus of this lesson?", "options": [{"text": "Christ as the source of restored life", "is_correct": true}, {"text": "Behavior management only", "is_correct": false}, {"text": "Avoiding spiritual growth", "is_correct": false}, {"text": "Reducing recovery to habit tracking", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery becomes deeper when Christ is central rather than optional.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It points the person toward the right source whom is Christ", "is_correct": true}, {"text": "It replaces honesty", "is_correct": false}, {"text": "It removes all discipline", "is_correct": false}, {"text": "It makes struggle irrelevant", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the starting point for Chapter 8. In the next lesson, we will look at returning to God''s design."}}]}, {"number": 2, "title": "Returning to God''s Design", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing is not only the answer to a damaged life. It is a return to your original purpose.", "message": "Recovery makes more sense when the person understands what human life was designed for in the first place and what it looks like. This lesson focuses on returning to God''s design instead of merely avoiding collapse."}}, {"type": "reading", "content": {"title": "God''s design gives direction to restoration.", "body": "People often define recovery only negatively: stop using, stop relapsing, stop breaking things. Those goals matter, but they are incomplete on their own. Returning to God''s design means asking what the person was actually created for: communion with God, living in Truth, obedience to Father, stewardship of His purpose, loving all mankind, and fruitful living. When that design is forgotten, recovery may become merely defensive. When it is remembered, the person starts moving toward a renewed life, not just away from the ruins of the old one.  Genesis 1:26-28  Then God said, “Let Us make an in Our image, according to Our likeness; let them have dominion over the fish of the sea, over the birds of the air, and over the cattle, over all the earth and over every creeping thing that creeps on the earth.”  So God created man in His own image, in the image of God He created him, male and female He created them.  Then God blessed them, and God said to them, “Be fruitful and multiply; fill the earth and subdue it, have dominion over the fish of the sea, over the birds of the air, and over every living thing that moves on the earth.’"}}, {"type": "mentor_note", "content": {"note": "A life without God''s original design will always settle for survival."}}, {"type": "video", "content": {"title": "Returning to God''s Design", "description": "A mentor-led lesson on how God''s original design gives positive direction to recovery and rebuilding."}}, {"type": "pause_reflect", "content": {"question": "What part of God''s design for your life feels most neglected right now?", "context": "Think about your relationship with God, your calling, your purpose in life, your character, your relationship with God and with others."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want recovery to become a return to purpose, not just an escape from damage."}}, {"type": "mood_checkin", "content": {"question": "How purposeful does your recovery feel today?"}}, {"type": "daily_action", "content": {"title": "Aim beyond survival", "action": "Choose one area today where you will act as someone rebuilding according to God''s design, not just someone avoiding failure."}}, {"type": "mentor_note", "content": {"note": "Restoration becomes clearer when design is remembered."}}, {"type": "quiz", "content": {"question": "What does this lesson add to recovery?", "options": [{"text": "Only more rules", "is_correct": false}, {"text": "A return to God''s intended design", "is_correct": true}, {"text": "Less responsibility", "is_correct": false}, {"text": "A focus on survival only", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery can become too defensive if design is forgotten.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is God''s design important here?", "options": [{"text": "It gives meaningful direction to restoration", "is_correct": true}, {"text": "It weakens purpose", "is_correct": false}, {"text": "It removes the need for growth", "is_correct": false}, {"text": "It makes obedience optional", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have connected recovery with God''s design and purpose. In the next lesson, we will look at the gift of salvation."}}]}, {"number": 3, "title": "The Gift of Salvation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery without salvation may improve behavior, but it cannot fully restore the soul.", "message": "This lesson places salvation where it belongs: at the center of the person''s deepest need. Drug abuse and addiction is very serious, but the need for reconciling with God is deeper still."}}, {"type": "reading", "content": {"title": "Salvation addresses the root relationship that every other healing depends on.", "body": "Salvation is not a decorative religious concept added to recovery. It is the work of God that reconciles the sinner to Himself through Christ Jesus. Without that reconciliation, the person may chase self improvement without ever receiving the deepest answers to why drug abuse is so powerful or why it even exists. The gift of salvation matters because it changes the core parts of the human creation, its very make-up, identity, hope, and future. It does not trivialize the recovery journey. It places that journey inside a larger redemptive purpose to life that reaches beyond symptom management into restored relationship with God.  Ephesians 2:8  For by grace you have been saved through faith, and that not of yourself, it is the gift of God."}}, {"type": "mentor_note", "content": {"note": "Behavioral change is valuable, but reconciliation with Christ is deeper."}}, {"type": "video", "content": {"title": "The Gift of Salvation", "description": "A mentor-led lesson on why salvation is central to Christian recovery and how it reframes the learner''s deepest need."}}, {"type": "pause_reflect", "content": {"question": "How does seeing salvation as a gift change the way you view your recovery?", "context": "Consider how grace, identity, forgiveness, and reconciliation affect your understanding of change."}}, {"type": "journal_prompt", "content": {"prompt": "Write about the difference between self-improvement and salvation-centered restoration."}}, {"type": "mood_checkin", "content": {"question": "How secure do you feel in God''s saving grace today?"}}, {"type": "daily_action", "content": {"title": "Let recovery sit inside salvation", "action": "Take a moment today to remind yourself that your recovery journey sits inside a bigger story of salvation and reconciliation."}}, {"type": "mentor_note", "content": {"note": "The heart changes most deeply when it knows it has been saved, not just corrected."}}, {"type": "quiz", "content": {"question": "What does salvation address in this lesson?", "options": [{"text": "Only temporary habits", "is_correct": false}, {"text": "A saving relationship with God", "is_correct": true}, {"text": "Only external behavior", "is_correct": false}, {"text": "Only emotions", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Salvation is central, not decorative in Christian recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does this lesson change for the person?", "options": [{"text": "Identity, standing, hope, and future", "is_correct": true}, {"text": "Nothing beyond routine", "is_correct": false}, {"text": "Only schedule planning", "is_correct": false}, {"text": "Only social behavior", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have placed salvation in the center of the bigger picture. In the next lesson, we will focus on receiving God''s grace."}}]}, {"number": 4, "title": "Receiving God''s Grace", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Many people talk about grace without really receiving it.", "message": "This lesson helps the person move beyond abstract belief, but to receive God''s grace, mercy, kindness and goodness."}}, {"type": "reading", "content": {"title": "Grace must be received, not merely admired.", "body": "A person may agree that grace exists while still living as though everything depends on proving worth, hiding failure, or earning acceptance. Receiving God''s grace means allowing His Wisdom to answer unknowns, His patience to build strength, and His truth to expose compromise without pushing the person into despair. Grace is not softness toward sin. It is God''s hand that keeps the person moving toward healing without being swallowed by condemnation. Recovery becomes more sustainable when grace is actually received and not only spoken about.  Ephesians 2:8-9  For by grace you have been saved through faith, and that not of yourselves, it is the gift of God, not of works, lest anyone should boast.  2 Corinthians 12:9  And He said to me, “My grace is sufficient for you, for My strength is made perfect in weakness.”  Therefore most gladly I will rather boast in my infirmities, that the power of Christ may rest upon me."}}, {"type": "mentor_note", "content": {"note": "What is not received by grace cannot yet become the ultimate progress."}}, {"type": "video", "content": {"title": "Receiving God''s Grace", "description": "A mentor-led lesson on how God''s grace moves from concept to lived support in recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you still struggle to actually receive grace?", "context": "Think about places where you still live as though you must perform perfectly before drawing near to God."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where receiving God''s grace would change the way you carry your recovery."}}, {"type": "mood_checkin", "content": {"question": "How open are you to God''s grace today?"}}, {"type": "daily_action", "content": {"title": "Stop arguing with mercy", "action": "When shame rises today, answer it by naming one way God''s grace is still available to you right now."}}, {"type": "mentor_note", "content": {"note": "Grace becomes powerful when it is trusted as God''s power at work."}}, {"type": "quiz", "content": {"question": "What does this lesson say about grace?", "options": [{"text": "It is only a concept", "is_correct": false}, {"text": "It must be received, not merely admired", "is_correct": true}, {"text": "It removes truth", "is_correct": false}, {"text": "It excuses secrecy", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Grace means softness toward sin.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does receiving grace matter in recovery?", "options": [{"text": "It helps the learner move forward without condemnation", "is_correct": true}, {"text": "It replaces honesty", "is_correct": false}, {"text": "It removes structure", "is_correct": false}, {"text": "It makes change unnecessary", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have looked at grace as something to receive, not only describe. In the next lesson, we will focus on spiritual growth and healing."}}]}, {"number": 5, "title": "Spiritual Growth and Healing", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing is not only about stopping harm. It is also about growing well.", "message": "This lesson helps the person understand that recovery must include spiritual growth, not only crisis management or damage control."}}, {"type": "reading", "content": {"title": "Growth and healing belong together in a restored life.", "body": "Many people begin recovery in emergency mode, which is understandable. But over time, a deeper question must emerge: what kind of person am I becoming as healing unfolds? Spiritual growth includes growing in the Word of God, humility, consistency, patience, discernment, obedience, and dependence on God. Healing becomes stronger when the person stops viewing themselves only as wounded and trying to survive, but instead starts seeing themselves as a person being transformed. Growth gives recovery depth, structure, and forward movement."}}, {"type": "mentor_note", "content": {"note": "A healed life is not empty space. It is cultivated ground."}}, {"type": "video", "content": {"title": "Spiritual Growth and Healing", "description": "A mentor-led lesson on how healing and formation work together in the Christian recovery journey."}}, {"type": "pause_reflect", "content": {"question": "Where do you most need growth, not just relief?", "context": "Consider character, discipline, relationships, truthfulness, stability, and obedience."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want spiritual growth to become part of your healing, not an afterthought."}}, {"type": "mood_checkin", "content": {"question": "How much do you feel like you are growing, not just coping, today?"}}, {"type": "daily_action", "content": {"title": "Choose spiritual growth, not only relief", "action": "Pick one area where you usually seek immediate relief and replace that instinct today with one step that supports long-term growth."}}, {"type": "mentor_note", "content": {"note": "Growth turns survival into formation."}}, {"type": "quiz", "content": {"question": "What does this lesson add to healing?", "options": [{"text": "The importance of spiritual growth and transformation", "is_correct": true}, {"text": "A rejection of discipline", "is_correct": false}, {"text": "Only crisis thinking", "is_correct": false}, {"text": "Less purpose", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Healing is stronger when spiritual growth is part of it.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What shift does this lesson encourage?", "options": [{"text": "From survival only to spiritual transformation", "is_correct": true}, {"text": "From honesty to image management", "is_correct": false}, {"text": "From purpose to passivity", "is_correct": false}, {"text": "From growth to avoidance", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have tied healing to spiritual growth. In the next lesson, we will look at living a fruitful life."}}]}, {"number": 6, "title": "Living a Fruitful Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Freedom is not the final picture unless it also becomes fruitful living.", "message": "This lesson pushes the person beyond private recovery and toward visible spiritual fruit in daily life, character, and relationships."}}, {"type": "reading", "content": {"title": "Spiritual fruit is the visible evidence of life rooted in Grace and Truth.", "body": "A fruitful life is not defined by image, performance, or outward perfection. It is defined by the steady evidence that God''s life is shaping within the person and working what comes out of them. Spiritual fruit bears evidence in how the person thinks, speaks, relates, endures, serves, and chooses. Drug abuse and addiction often narrows life to self-protection and short-term relief. Spiritual fruit creates freedom to love again, stability, purpose, and sharing a graceful life. Recovery matures when the person no longer asks only how to avoid collapse, but how to live in a way that blesses others and honors God.  Galatians 5:22-23  But the fruit of the Spirit is love, joy, peace, longsuffering, kindness, goodness, faithfulness, gentleness, self-control. Against such there is no law."}}, {"type": "mentor_note", "content": {"note": "Life is known not only by what it escapes, but by what it creates."}}, {"type": "video", "content": {"title": "Living a Fruitful Life", "description": "A mentor-led lesson on how true recovery becomes visible through fruit in character, purpose, and relationships."}}, {"type": "pause_reflect", "content": {"question": "What kind of fruit do you most want to see grow in your life?", "context": "Think about qualities and outcomes that would show your life is being restored in a real and visible way."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one kind of spiritual fruit you want your recovery to begin producing more clearly."}}, {"type": "mood_checkin", "content": {"question": "How fruitful does your life feel today?"}}, {"type": "daily_action", "content": {"title": "Look for visible fruit", "action": "Identify one small sign today that life is becoming more fruitful, even if it still feels early and incomplete."}}, {"type": "mentor_note", "content": {"note": "Fruit grows where life stays connected to the Tree of Life."}}, {"type": "quiz", "content": {"question": "What is fruit in this lesson?", "options": [{"text": "Outward perfection", "is_correct": false}, {"text": "Visible evidence of life rooted in Christ", "is_correct": true}, {"text": "Only emotional relief", "is_correct": false}, {"text": "A social performance", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery should eventually become fruitful, not only defensive.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What question does this lesson add?", "options": [{"text": "How can I bless and honor God through restored living?", "is_correct": true}, {"text": "How can I stay hidden longer?", "is_correct": false}, {"text": "How can I avoid all growth?", "is_correct": false}, {"text": "How can I keep life narrow?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have looked at the fruit of restored life. In the final lesson, we will focus on walking in newness of life."}}]}, {"number": 7, "title": "Walking in Newness of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The chapter ends with movement, not theory.", "message": "Newness of life is not just a spiritual phrase. It is the daily reality of walking in purpose because a different life is now at work within you."}}, {"type": "reading", "content": {"title": "Newness of life is lived through repeated alignment with what God has made possible.", "body": "Walking in newness of life means refusing to keep defining yourself by the old pattern you walked in before. It means living as someone who has been called forward, out and into truth, grace, obedience, and restored purpose. This does not mean pretending the old struggle never existed. It means that the old struggle is no longer the final authority over identity in Christ or your future. The person who walks in newness of life learns to move differently, interpret differently, choose differently, and hope differently. That is how restored life becomes visible over time.  Ezekiel 36:26  I will give you a new heart and put a new spirit within you; I will take the heart of stone out of your flesh and give you a heart of flesh.  2 Corinthians 5:17  Therefore, if anyone is in Christ, he is a new creation; old things have passed away; behold, all things have become new."}}, {"type": "mentor_note", "content": {"note": "Newness of life is proved by the direction of the walk."}}, {"type": "video", "content": {"title": "Walking in Newness of Life", "description": "A mentor-led conclusion to Chapter 8, showing how restored life becomes a lived path and not only a hopeful idea."}}, {"type": "pause_reflect", "content": {"question": "What would it look like for you to walk more fully in newness of life this week?", "context": "Think about identity, choices, routines, relationships, and the way you respond when challenged."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one concrete sign that you are beginning to walk in newness of life rather than returning to old identity."}}, {"type": "mood_checkin", "content": {"question": "How forward-moving does your life feel today?"}}, {"type": "daily_action", "content": {"title": "Walk like life is new", "action": "Choose one action today that reflects your new direction instead of echoing your former pattern."}}, {"type": "mentor_note", "content": {"note": "The new life becomes evident with faith, hope and love."}}, {"type": "quiz", "content": {"question": "What does newness of life mean in this lesson?", "options": [{"text": "Forgetting the past existed", "is_correct": false}, {"text": "Walking in a different direction because God''s life is at work", "is_correct": true}, {"text": "Escaping all responsibility", "is_correct": false}, {"text": "Avoiding daily choices", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The old struggle is no longer the final authority over identity or direction.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "How does this chapter end?", "options": [{"text": "With progressive movement into a new life", "is_correct": true}, {"text": "With passivity", "is_correct": false}, {"text": "With vague optimism only", "is_correct": false}, {"text": "With no practical next step", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "Chapter 10 is complete. You are ready to continue into Chapter 11 with a deeper focus on love, healing, and restored relationships."}}]}]}, {"number": 11, "title": "Love", "description": "Chapter 11 closes the course by focusing on love as the foundational spiritual fruit for healing. It covers God''s love, receiving acceptance, healthy self-understanding, forgiveness, loving others well, restoring relationships, compassion, and walking in love daily.\n\nThe goal of this chapter is to help the learner move from survival and restoration into a daily life shaped by love, truth, mercy, and purpose driven relationships.", "lessons": [{"number": 1, "title": "Understanding God''s Love", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The final chapter begins at the deepest source of healing: God''s love.", "message": "This lesson helps the learner understand that recovery is not only about correction, but also about receiving the love of God properly."}}, {"type": "reading", "content": {"title": "God''s love gives the person a new foundation for identity, hope, and healing.", "body": "Many people know the phrase God is love, but might feel that difficult times do not make it feel that God loves us. God''s love is not sentimental weakness. God''s love is powerful, and stands through any test known to man. Understanding that love changes how the person views discipline, failure, worth, and the possibility of transforming life.  1 Corinthians 13:4-7  Love suffers long and is kind, love does not envy, love does not parade itself, is not puffed up;  does not behave rudely, does not seek its own, is not provoked, thinks no evil;  does not rejoice in iniquity, but rejoices in the truth;  bears all things, believes all things, hopes all things, endures all things."}}, {"type": "mentor_note", "content": {"note": "Love understood rightly can steady what fear has kept unstable."}}, {"type": "video", "content": {"title": "Understanding God''s Love", "description": "A mentor-led lesson on the meaning and healing power of God''s love."}}, {"type": "pause_reflect", "content": {"question": "How has your view of God''s love been shaped by your struggle?", "context": "Think about whether you have seen God as distant, angry, patient, near, corrective, or welcoming."}}, {"type": "journal_prompt", "content": {"prompt": "Write about what you believe God''s love means for your recovery."}}, {"type": "mood_checkin", "content": {"question": "How loved by God do you feel today?"}}, {"type": "daily_action", "content": {"title": "Receive the foundation", "action": "Pause today and remind yourself of one truth about God''s love that challenges fear or shame."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes steadier when love is received as a foundation, not as an afterthought."}}, {"type": "quiz", "content": {"question": "What does God''s love provide in this lesson?", "options": [{"text": "A foundation for identity and healing", "is_correct": true}, {"text": "Permission for compromise", "is_correct": false}, {"text": "Only emotion", "is_correct": false}, {"text": "Less truth", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: God''s love is patient and restorative, not sentimental weakness.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is this lesson important?", "options": [{"text": "It changes how the learner views worth, failure, and healing", "is_correct": true}, {"text": "It removes discipline", "is_correct": false}, {"text": "It replaces truth", "is_correct": false}, {"text": "It weakens hope", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 1.", "encouragement": "You now have the opening frame for Chapter 11. In the next lesson, we will focus on receiving love and acceptance."}}]}, {"number": 2, "title": "Receiving Love and Acceptance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Many people hear about love but still struggle to receive it.", "message": "This lesson helps the person move from intellectual agreement into spiritual acceptance of love from God."}}, {"type": "reading", "content": {"title": "Love must be embraced, not merely described from a distance.", "body": "Some people keep living as though acceptance must be earned after they begin to heal from drug abuse and addiction. That kind of mindset blocks deep healing. Receiving love and acceptance means allowing God''s grace to enter into the deeper parts of the heart, into new identity formation for newness of life. Accepting this transformative love is what will open new doors in life, connections with purpose, close relationships and just general healthy wellbeing.  1 John 4:8  He who does not love does not know God, for God is love."}}, {"type": "mentor_note", "content": {"note": "What pure gifts are not received yet cannot establish the heart."}}, {"type": "video", "content": {"title": "Receiving Love and Acceptance", "description": "A mentor-led lesson on receiving God''s acceptance and letting it reshape shame and fear."}}, {"type": "pause_reflect", "content": {"question": "Where do you still resist being loved or accepted by God?", "context": "Think about areas where shame or performance still seem stronger than grace."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where receiving acceptance would change the way you carry your struggle."}}, {"type": "mood_checkin", "content": {"question": "How accepted do you feel today?"}}, {"type": "daily_action", "content": {"title": "Stop arguing with acceptance", "action": "When shame speaks today, answer it by naming one way God''s acceptance remains available to you."}}, {"type": "mentor_note", "content": {"note": "Accepted people often become more honest, not less."}}, {"type": "quiz", "content": {"question": "What is the central movement in this lesson?", "options": [{"text": "Receiving love and acceptance", "is_correct": true}, {"text": "Earning worth", "is_correct": false}, {"text": "Avoiding grace", "is_correct": false}, {"text": "Hiding failure", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Acceptance means denial of sin.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does acceptance help with?", "options": [{"text": "It helps calm shame and support honesty", "is_correct": true}, {"text": "It removes truth", "is_correct": false}, {"text": "It weakens healing", "is_correct": false}, {"text": "It creates passivity", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 2.", "encouragement": "You have looked at receiving love and acceptance. In the next lesson, we will focus on loving yourself through God''s eyes."}}]}, {"number": 3, "title": "Loving Yourself Through God''s Eyes", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Self-hatred is not humility, and recovery cannot mature while identity stays unresolved.", "message": "This lesson helps the person distinguish between prideful self-focus and healthy self-understanding through God''s eyes."}}, {"type": "reading", "content": {"title": "To love yourself through the eyes of God is not pride.", "body": "Many people in recovery swing between self-condemnation and self-protection. Neither is healthy. Loving yourself through God''s eyes means agreeing with His truth about who you truly are and how he created you. Purposeful self-understanding becomes a healthier ground for change than self-hatred ever could. The original design of mankind were beautiful inside the heart and spirit and beautifully created in body. Humanity is the crown of God''s creation, and that is what needs to be restored again. And the first step is love.  Psalm 139:14  I will praise You, for I am fearfully and wonderfully made; Marvelous are Your works, And that my soul knows very well."}}, {"type": "mentor_note", "content": {"note": "Truthful self-understanding heals more deeply than self-contempt."}}, {"type": "video", "content": {"title": "Loving Yourself Through God''s Eyes", "description": "A mentor-led lesson on healthy self-understanding, dignity, and responsibility."}}, {"type": "pause_reflect", "content": {"question": "Where do you most struggle to see yourself the way God sees you?", "context": "Think about worth, dignity, weakness, responsibility, and the lies you often agree with."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one false belief about yourself that needs to be replaced with God''s truth."}}, {"type": "mood_checkin", "content": {"question": "How peacefully do you relate to yourself today?"}}, {"type": "daily_action", "content": {"title": "Reject the false identity", "action": "When self-condemnation rises today, answer it with one truthful statement about who you are before God."}}, {"type": "mentor_note", "content": {"note": "The person who sees themselves rightly is often more free to change."}}, {"type": "quiz", "content": {"question": "What does loving yourself through God''s eyes mean?", "options": [{"text": "Worshipping yourself", "is_correct": false}, {"text": "Knowing how wonder God created you", "is_correct": true}, {"text": "Ignoring sin", "is_correct": false}, {"text": "Excusing all weakness", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Self-hatred is not the same as humility.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It replaces false identity with truthful self-understanding", "is_correct": true}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It weakens conviction", "is_correct": false}, {"text": "It avoids honesty", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 3.", "encouragement": "You have looked at identity and self-understanding more clearly. In the next lesson, we will focus on forgiveness and healing."}}]}, {"number": 4, "title": "Forgiveness and Healing", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing often slows where forgiveness is resisted.", "message": "This lesson helps the person understand forgiveness as a serious part of healing, not as a shortcut around pain relief."}}, {"type": "reading", "content": {"title": "Forgiveness releases the heart from being governed by unresolved offense.", "body": "Forgiveness does not call evil good, and it does not pretend harm did not happen. It does, however, stop handing ongoing control of the heart to the offense. In recovery, unforgiveness can keep bitterness, anger, self-protection, and pain recycling underneath everything else. Healing deepens when forgiveness is sincere, remorseful and understood, so truth and grace may guide the person.  1 Peter 4:8  And above all things have fervent love for one another, for “love will cover a multitude of sins.”"}}, {"type": "mentor_note", "content": {"note": "What is held too tightly in pain often keeps holding the person back."}}, {"type": "video", "content": {"title": "Forgiveness and Healing", "description": "A mentor-led lesson on why forgiveness matters in recovery and healing."}}, {"type": "pause_reflect", "content": {"question": "Where do you feel resistance when you think about forgiveness?", "context": "Think about people, events, and places where pain still shapes your inner reactions strongly."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where forgiveness may be part of your next healing step."}}, {"type": "mood_checkin", "content": {"question": "How heavy or free does your heart feel today?"}}, {"type": "daily_action", "content": {"title": "Move one step toward release", "action": "Take one honest step today toward releasing an offense or person into God''s hands rather than feeding it inwardly."}}, {"type": "mentor_note", "content": {"note": "Forgiveness is not forgetting. It is refusing to keep living under the rule of the offense."}}, {"type": "quiz", "content": {"question": "What does forgiveness do in this lesson?", "options": [{"text": "Pretends harm did not happen", "is_correct": false}, {"text": "Releases the heart from being governed by offense", "is_correct": true}, {"text": "Removes all consequences", "is_correct": false}, {"text": "Avoids truth", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Unforgiveness can keep pain recycling in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is this lesson important?", "options": [{"text": "It connects healing with release any inner offenses", "is_correct": true}, {"text": "It excuses evil", "is_correct": false}, {"text": "It weakens boundaries", "is_correct": false}, {"text": "It removes responsibility", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 4.", "encouragement": "You have looked at forgiveness as part of healing. In the next lesson, we will focus on loving others well."}}]}, {"number": 5, "title": "Loving Others Well", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery is not complete if the heart remains unable to love sincerely.", "message": "This lesson helps the person move beyond self-preservation into healthier ways of relating to other people."}}, {"type": "reading", "content": {"title": "Loving others sincerely requires truth, humility, patience and kindness.", "body": "We know that drug abuse and addiction can leave severely damaged people in its wake, and makes it extremely difficult for forgiveness. That is why love is the healing power of God that works in the depths of the heart to change a person. Loving others well does not mean becoming naïve, passive, or without boundaries. It means growing in truthful, patient, humble, and responsible love. The learner begins to move from relational harm toward proper care, relational maturity and pure love.  1 John 4:8  He who does not love does not know God, for God is love.  Mark 12:31  And the second, like it, is this: ‘You shall love your neighbor as yourself.’  There is no other commandment greater than these.”"}}, {"type": "mentor_note", "content": {"note": "Love has a deep responsibility towards our neighbors."}}, {"type": "video", "content": {"title": "Loving Others Well", "description": "A mentor-led lesson on relational maturity, patience, and truth-based love."}}, {"type": "pause_reflect", "content": {"question": "What makes loving others well hardest for you right now?", "context": "Think about trust, selfishness, fear, defensiveness, and relational damage from the past."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one relational pattern that needs to change if you want to love others more well."}}, {"type": "mood_checkin", "content": {"question": "How relationally open or guarded do you feel today?"}}, {"type": "daily_action", "content": {"title": "Practice one healthier response", "action": "Choose one person today and respond with more honesty, patience, or humility than you usually would."}}, {"type": "mentor_note", "content": {"note": "Love matures when seen as spiritual and eternal."}}, {"type": "quiz", "content": {"question": "What does loving others well require in this lesson?", "options": [{"text": "Passivity", "is_correct": false}, {"text": "Truth, humility, patience, and kindness", "is_correct": true}, {"text": "Only feeling", "is_correct": false}, {"text": "Avoiding people", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Loving well does not mean having no boundaries.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It moves recovery toward relational maturity", "is_correct": true}, {"text": "It increases selfishness", "is_correct": false}, {"text": "It removes honesty", "is_correct": false}, {"text": "It avoids growth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 5.", "encouragement": "You have focused on loving others with more maturity. In the next lesson, we will look at restoring relationships."}}]}, {"number": 6, "title": "Restoring Relationships", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some relationships can be rebuilt, but restoration requires truth and patience.", "message": "This lesson helps the person think carefully about what relationship restoration actually requires."}}, {"type": "reading", "content": {"title": "Restoration is built through honesty, time, inner change, and wise decisions.", "body": "Broken relationships are not repaired by apology alone. They are repaired over time through truthfulness, changed conduct, consistency, and the patient rebuilding of trust where appropriate. Some relationships may not be fully restorable in the same form, but many can move toward greater peace, honesty, or healing. This lesson teaches the person to pursue restoration wisely rather than sentimentally.  Proverbs 10:12  Hatred stirs up strife, But love covers all sins"}}, {"type": "mentor_note", "content": {"note": "Trust usually returns through repeated expressions of love."}}, {"type": "video", "content": {"title": "Restoring Relationships", "description": "A mentor-led lesson on what wise relational restoration looks like in recovery."}}, {"type": "pause_reflect", "content": {"question": "Which relationship in your life most needs wisdom, patience, and truth right now?", "context": "Think about relationships marked by pain, disappointment, mistrust, or emotional distance."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one relationship where restoration may require slower, wiser expectations."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about restoration today?"}}, {"type": "daily_action", "content": {"title": "Choose one repairing step", "action": "Take one small repairing step today where it is appropriate: honesty, ownership, patience, or changed conduct."}}, {"type": "mentor_note", "content": {"note": "Restoration grows as love is expressed with actions consistently."}}, {"type": "quiz", "content": {"question": "What builds restoration in this lesson?", "options": [{"text": "Rushed apology only", "is_correct": false}, {"text": "Honesty, time, change, and wise decisions", "is_correct": true}, {"text": "Pressure", "is_correct": false}, {"text": "Pretending nothing happened", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Not every relationship will be restored in the same way.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is the main emphasis here?", "options": [{"text": "Wise and patient rebuilding where appropriate", "is_correct": true}, {"text": "Sentimental repair", "is_correct": false}, {"text": "Forced closeness", "is_correct": false}, {"text": "Avoiding ownership", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 6.", "encouragement": "You have looked at restoration more wisely. In the next lesson, we will focus on compassion."}}]}, {"number": 7, "title": "Living a Life of Compassion", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing is also a part of showing compassion for others.", "message": "This lesson helps the person grow in care, awareness, kindness and love toward other people. Love and compassion is not a weakness of character."}}, {"type": "reading", "content": {"title": "Compassion develops where pain has once lived in the person.", "body": "People who have suffered and gone through extreme difficulty often become either softer and wiser or harder and more closed. Compassion does not mean agreement with wrong or surrender of boundaries. It means the person becomes able to see others with mercy, patience, and understanding while still honoring truth. Recovery matures beautifully when pain is transformed into compassion, love, kindness, goodness and a giving heart. ."}}, {"type": "mentor_note", "content": {"note": "Healed pain often becomes a gentler lens for seeing others."}}, {"type": "video", "content": {"title": "Living a Life of Compassion", "description": "A mentor-led lesson on how mercy and compassion become part of restored character."}}, {"type": "pause_reflect", "content": {"question": "Where do you still struggle to show compassion?", "context": "Think about people who disappoint you, remind you of pain, or harsh circumstances."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one place where compassion needs to grow in your life."}}, {"type": "mood_checkin", "content": {"question": "How compassionate does your heart feel today?"}}, {"type": "daily_action", "content": {"title": "Lead with mercy", "action": "Choose one interaction today where you will intentionally respond with more mercy and patience."}}, {"type": "mentor_note", "content": {"note": "Compassion does not weaken truth. It changes the tone in which truth is carried."}}, {"type": "quiz", "content": {"question": "What is compassion in this lesson?", "options": [{"text": "Boundaryless softness", "is_correct": false}, {"text": "Mercy and patience carried with truth", "is_correct": true}, {"text": "Agreement with wrong", "is_correct": false}, {"text": "Avoidance of honesty", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Compassion and truth can grow together.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It turns healed pain into gentler character", "is_correct": true}, {"text": "It removes wisdom", "is_correct": false}, {"text": "It creates denial", "is_correct": false}, {"text": "It weakens recovery", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 7.", "encouragement": "You have looked at compassion as part of restored character. In the final lesson, we will focus on walking in love daily."}}]}, {"number": 8, "title": "Walking in Love Daily", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The course closes by turning love into a daily way of life.", "message": "This final lesson helps the person understand that love is not merely a feeling, but a daily path of response, discipline, truth, and grace."}}, {"type": "reading", "content": {"title": "Walking in love daily means making love visible through ordinary faithfulness.", "body": "Love becomes most credible when it is practiced in normal life: in patience, forgiveness, honesty, humility, service, restraint, and faithfulness. The person does not graduate into a life where love happens automatically. They keep choosing it. Walking in love daily is a practical way of living under what God has taught throughout the whole course. It is the spiritual fruit of recovery that quenches a thirsty soul and feeds your soul with nourishment from God.  1 John 4:16  And we have known and believed the love that God has for us. God is love, and he who abides in love abides in God, and God in him."}}, {"type": "mentor_note", "content": {"note": "Love must be embedded in the character of the person eternally."}}, {"type": "video", "content": {"title": "Walking in Love Daily", "description": "A mentor-led conclusion to Chapter 11 and the Christian-guided course, showing how love becomes a daily walk."}}, {"type": "pause_reflect", "content": {"question": "What would it look like for you to walk in love more consistently this week?", "context": "Think about small daily responses where love can become more visible and deliberate."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one specific way you want to walk in love more consistently from this point forward."}}, {"type": "mood_checkin", "content": {"question": "How willing are you to walk in love today?"}}, {"type": "daily_action", "content": {"title": "Make love visible", "action": "Choose one ordinary situation today and respond in a way that makes love visible through truth and faithfulness."}}, {"type": "mentor_note", "content": {"note": "The strongest form of love is often the one practiced steadily, not dramatically."}}, {"type": "quiz", "content": {"question": "What does walking in love daily mean in this lesson?", "options": [{"text": "Waiting for feelings only", "is_correct": false}, {"text": "Making love visible through acts of kindness", "is_correct": true}, {"text": "Ignoring boundaries", "is_correct": false}, {"text": "Avoiding truth", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Love must be chosen repeatedly in daily life.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "How does this chapter close the course?", "options": [{"text": "By turning recovery into a daily walk of visible love", "is_correct": true}, {"text": "By removing responsibility", "is_correct": false}, {"text": "By ending growth", "is_correct": false}, {"text": "By reducing love to emotion", "is_correct": false}]}}, {"type": "complete", "content": {"message": "You have completed Lesson 8.", "encouragement": "Chapter 11 is complete. The Christian-guided course now closes with love becoming a daily, lived expression of healing and restored life."}}]}]}]'::jsonb) loop
    select id into chapter_record from chapters
    where course_version_id = course_version and title = chapter_item->>'title'
    order by created_at limit 1;
    if chapter_record is null and (chapter_item->>'number')::integer = 5 then
      select id into chapter_record from chapters
      where course_version_id = course_version and title = 'The Three Stages of Drug Abuse'
      order by created_at limit 1;
    end if;
    if chapter_record is null then
      raise exception 'Missing chapter: %', chapter_item->>'title';
    end if;
    update chapters set title = chapter_item->>'title', description = chapter_item->>'description',
      sort_order = (chapter_item->>'number')::integer, updated_at = now()
    where id = chapter_record;

    for lesson_item in select value from jsonb_array_elements(chapter_item->'lessons') loop
      select id into lesson_record from lessons
      where chapter_id = chapter_record and lesson_number = (lesson_item->>'number')::integer
      order by created_at limit 1;
      if lesson_record is null then
        raise exception 'Missing lesson % in chapter %', lesson_item->>'number', chapter_item->>'title';
      end if;
      update lessons set title = lesson_item->>'title', estimated_minutes = (lesson_item->>'minutes')::integer,
        opening_message = lesson_item->'blocks'->0->'content'->>'message',
        encouragement_message = lesson_item->'blocks'->12->'content'->>'encouragement',
        sort_order = (lesson_item->>'number')::integer, updated_at = now()
      where id = lesson_record;

      block_position := 0;
      for block_item in select value from jsonb_array_elements(lesson_item->'blocks') loop
        block_position := block_position + 1;
        select id into block_record from lesson_content_blocks
        where lesson_id = lesson_record and sort_order = block_position
        order by created_at limit 1;
        if block_record is null then
          insert into lesson_content_blocks (lesson_id, block_type, content, sort_order)
          values (lesson_record, block_item->>'type', block_item->'content', block_position);
        else
          update lesson_content_blocks set block_type = block_item->>'type', content = block_item->'content',
            updated_at = now() where id = block_record;
        end if;
      end loop;
      delete from lesson_content_blocks where lesson_id = lesson_record and sort_order > block_position;
    end loop;
  end loop;
end $$;
